/* Shared naming pool; loaded before the first world is created. */
const nameWords={
 first:'Amara Arlo Asha Atlas Avery Azra Bowie Cairo Cassia Celine Dario Eden Elio Ember Ezra Farah Felix Hana Idris Imani Indigo Iris Jalen Jaya Juno Kai Kairo Keira Kofi Lana Leif Lena Leon Liora Luca Lumi Lyra Maeve Malik Maren Mateo Micah Milan Mira Nia Nico Noa Nova Nyla Omar Orion Remi Rio Rumi Sage Sanaa Selah Shiloh Skye Sol Sora Talia Theo Uma Veda Wren Yara Zara Zuri'.split(' '),
 last:'Ash Banks Bell Bloom Blue Brooks Cole Cove Cruz Dawn Dean Drift Ellis Ever Finch Flint Frost Gray Grove Hale Harbor Hart Hayes Hollow James Jett Knox Lake Lane Laneaux Laurent Lennox Lune Mar Mercer Monroe Moon Moss North Ocean Park Quinn Rain Reed Reyes Rhodes Rivers Rose Rowan Saint Shore Solis Stone Storm Sun Vale Vega Voss Wells West Wilde Winter Wolf Woods York Zephyr'.split(' '),
 adj:'Amber Ancient Astral Bitter Blue Borrowed Broken Burning Celestial Chrome Cold Crimson Crystal Distant Electric Empty Faded Fallen Fevered Final Floating Forgotten Fragile Golden Hidden Hollow Honest Infinite Ivory Late Liquid Lonely Lost Lucid Lunar Midnight Modern Neon Northern Paper Parallel Quiet Restless Royal Scarlet Secret Silver Slow Soft Solar Southern Stolen Summer Tender Velvet Violet Wandering Wild Winter Young'.split(' '),
 noun:'Afterglow Air Angels Ashes Atlas Avenue Bloom Bones Bridges Butterflies Cathedral Cities Clouds Coast Comets Confessions Crown Daybreak Days Desert Diamonds Distance Dreams Dust Echoes Eden Embers Empire Fever Fire Flowers Ghosts Glass Gravity Heartbeats Highways Horizon Hours Letters Light Lightning Love Memories Mercury Mirrors Moments Moonlight Motion Names Nights Noise Oceans Orbit Paradise Perfume Photographs Promises Rain Rivers Roads Roses Satellites Seasons Shadows Silence Skyline Smoke Snow Sparks Stars Static Stories Strangers Sunrise Thunder Tides Tomorrow Truth Visions Voices Waves Weather Wings Wishes'.split(' '),
 phrase:['Stay a Little Longer','Nothing Left to Prove','Meet Me Halfway','We Were Almost Forever','Nobody Knows Yet','When the Room Goes Quiet','Before You Leave','All the Things We Never Said','Call Me When You Land','Somewhere We Belong','No One Gets Out Unchanged','I Remember Everything','Let the Record Play','What We Leave Behind','Never Learned to Say Goodbye','The Other Side of Home','One More Night in the City','You Look Like a Memory','Something Worth Keeping','This Is Where We Begin'],
 songLead:['Chasing','Dancing Through','Dreaming of','Falling into','Holding onto','Running from','Waiting for','Walking Through','Lost in','Made of','Under','Beyond','After','Before','Between','Without'],
 albumLead:['A Map of','A Season of','An Atlas of','Archives of','Echoes of','Everything Before','Fragments of','Letters from','Life After','Notes on','Portraits of','Postcards from','Songs for','Stories of','The Art of','The Colour of','The Edge of','The Language of','The Shape of','The Weight of']
};
const namingRecent={artist:[],song:[],album:[]};
function namingState(){try{return s}catch{return null}}
function nameCandidate(kind){const p=a=>a[Math.floor(Math.random()*a.length)],w=nameWords;if(kind==='artist')return p(w.first)+' '+p(w.last);const shape=Math.floor(Math.random()*4);return shape===0?p(w.adj)+' '+p(w.noun):shape===1?p(kind==='album'?w.albumLead:w.songLead)+' '+p(w.noun):shape===2?p(w.phrase):p(w.adj)+' '+p(w.noun)+' / '+p(w.noun)}
function generate(kind,current=''){if(!['artist','song','album'].includes(kind))kind='song';const state=namingState();const history=state?(state.nameHistory??={artist:[],song:[],album:[]}):namingRecent;for(const k of ['artist','song','album'])if(!Array.isArray(history[k]))history[k]=[];const used=new Set([current,...history[kind],...namingRecent[kind]]);if(state){if(kind==='artist'){used.add(state.name);state.world.forEach(x=>used.add(x.name))}else{(kind==='song'?state.songs:state.albums).forEach(x=>used.add(x.title));if(state.draft)used.add(state.draft.title);(state.projects||[]).forEach(x=>used.add(x.title));state.world.forEach(a=>a.catalog.forEach(x=>used.add(x.title)))}}let value;for(let i=0;i<100;i++){value=nameCandidate(kind);if(!used.has(value))break}if(used.has(value)){const base=value;let n=2;while(used.has(value))value=base+' '+n++}history[kind].push(value);history[kind]=history[kind].slice(-500);namingRecent[kind].push(value);namingRecent[kind]=namingRecent[kind].slice(-500);return value}

function numberLabel(n,long=false){if(!Number.isFinite(n))return 'Unavailable';const units=[['',''],['K','thousand'],['M','million'],['B','billion'],['T','trillion'],['Qa','quadrillion'],['Qi','quintillion'],['Sx','sextillion'],['Sp','septillion'],['Oc','octillion'],['No','nonillion'],['Dc','decillion']];let magnitude=Math.abs(n),i=magnitude>=1000?Math.min(11,Math.floor(Math.log10(magnitude)/3)):0;let scaled=magnitude/1000**i;if(Number(scaled.toFixed(2))>=1000&&i<11){i++;scaled=magnitude/1000**i}if(i===11&&scaled>=1000)return n.toExponential(2);const value=scaled.toLocaleString('en-US',{maximumFractionDigits:i?2:0});return (n<0?'−':'')+value+(i?(long?' '+units[i][1]:units[i][0]):'')}
function currencyLabel(n,long=false){return (n<0?'−':'')+'$'+numberLabel(Math.abs(n),long)}
const SANDBOX=/^\/(?:offline\/)?sandbox(?:\/|$)/.test(globalThis.location?.pathname||'');
const OFFLINE=/^\/offline(?:\/|$)/.test(globalThis.location?.pathname||'');
const SAVE_URL=SANDBOX?'/api/sandbox/save':'/api/save';

const icons=['<path d="M3 10 12 3l9 7v11h-6v-7H9v7H3z"/>','<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>','<path d="M4 20V11h4v9M10 20V4h4v16M16 20V8h4v12"/>','<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c6 6 6 12 0 18-6-6-6-12 0-18"/>','<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'];
const $=id=>document.getElementById(id),clamp=(v,l=0,h=100)=>Math.max(l,Math.min(h,v)),pick=a=>a[Math.floor(Math.random()*a.length)],rand=(a,b)=>a+Math.random()*(b-a),fmt=n=>Math.abs(n)>=1e9?numberLabel(n):Math.round(n).toLocaleString('en-US'),money=n=>Math.abs(n)>=1e6?currencyLabel(n):new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:Number.isInteger(n)?0:2,maximumFractionDigits:2}).format(n),compact=n=>numberLabel(n),esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tierNames=['Unknown','Emerging','Breakout','Star','Superstar','Global star','Global icon'];
const thresholds=[0,1000,25000,250000,2000000,20000000,100000000];
const tier=f=>thresholds.reduce((t,n,i)=>f>=n?i:t,0);
const genres=['Hip-hop','R&B','Pop','Rock','Country','Electronic','Latin','Afrobeats','Jazz','Gospel','Reggae','Indie folk','K-pop','Metal'];
const titles={song:[['After','Before','Beyond','Under','Without','Chasing','Finding','Only','Midnight','Last'],['the Rain','the Lights','Home','Tomorrow','the Noise','Your Shadow','a Promise','the Silence','the Sun','the City']],album:[['Letters from','The Weight of','A Season of','Life After','The Art of','Everything About','Somewhere Beyond','Nothing but','A World of','Made of'],['Midnight','Becoming','Silence','Gold','Yesterday','the Fall','Us','Daylight','Pressure','Dreams']]};
function fillName(id,kind){$(id).value=generate(kind,$(id).value)}
const seeds=[['NOVA VALE','Pop',180000000],['ORION SAINT','R&B',120000000],['SOL REYES','Latin',65000000],['SEOUL NIGHTS','K-pop',42000000],['ATLAS RED','Rock',29000000],['SAINT REIGN','Hip-hop',11500000],['AMARA SUN','Afrobeats',8000000],['LUCAS REED','Country',4300000],['NEON HARBOR','Electronic',2600000],['IVY MONROE','R&B',850000],['JUNE STATIC','Rock',750000],['ZION ROOTS','Reggae',410000],['ELLA NORTH','Country',300000],['MILES BLUE','Jazz',140000],['GRACE RIVERS','Gospel',80000],['IRON HOLLOW','Metal',45000],['MARLOW','Indie folk',22000],['KAI MONROE','Pop',6500],['RIO ASH','Hip-hop',2400],['LENA WELLS','Electronic',640],['JUNO GRAY','R&B',230],['ACE LANE','Hip-hop',85],['LUZ MAR','Latin',350],['KOFI DAWN','Afrobeats',110]];
function makeWorld(){return seeds.map(([name,genre,fans],i)=>({id:i,name:generate('artist'),genre,fans,skill:clamp(30+tier(fans)*10+rand(-8,8)),reputation:clamp(12+tier(fans)*13+rand(-5,5)),relation:0,lastTalk:0,lastNegotiate:0,discount:0,nextRelease:2+i%6,catalog:[{title:generate('song'),type:'Single',week:-i%4,base:Math.round(fans*rand(.5,.9)),streams:Math.round(fans*rand(.3,.7)),total:Math.round(fans*rand(2,6)),factor:1}],weekly:0}))}
function baseFresh(){return {achievements:initialAchievements(),chartBook:initialChartBook(),finance:initialFinance(),careerRecords:{sinceWeek:1,tours:[],openMics:0,royalties:0,liveGross:0,liveProfit:0},developmentVersion:1,development:initialDevelopment(),pacingVersion:1,chartRulesVersion:2,chartWeek:1,name:'Solace',genre:'Hip-hop',background:'Bedroom artist',week:1,cash:650,fans:42,energy:100,skill:0,reputation:8,stage:0,loyalty:20,ap:6,songs:[],albums:[],draft:null,boost:0,streams:0,total:0,started:false,world:makeWorld(),feed:[],history:[{week:1,text:'Your story starts here. Six time slots. One first impression.'}]}}
let saveReady=false,saveBusy=false,saveConflict=false,saveTimer,lastSaved='',saveEtag=null;
let s=fresh(),tab='Home',careerTab='Profile',industryTab='Artists',chartKind='Songs',chartMine=false,certificateFilter='Songs',achievementFilter='All',filter='All',genreFilter='All';
const THEME_KEY='encore-theme-v1',TOUR_KEY='encore-gameplay-tour-v2-'+(SANDBOX?'sandbox':'career');
let titleVisible=true,tourStep=-1,theme='light';
try{theme=localStorage.getItem(THEME_KEY)==='dark'?'dark':'light'}catch{}
function applyTheme(){if(!document.documentElement)return;document.documentElement.dataset.theme=theme;const setting=document.querySelector?.('meta[name="theme-color"]');if(setting)setting.content=theme==='dark'?'#111a2c':'#f3f7ff'}
function toggleTheme(){theme=theme==='light'?'dark':'light';try{localStorage.setItem(THEME_KEY,theme)}catch{}applyTheme();renderTitle();if(tab==='Artist')render()}
function tourHasPlayed(){try{return localStorage.getItem(TOUR_KEY)==='yes'}catch{return false}}
function markTourSeen(){try{localStorage.setItem(TOUR_KEY,'yes')}catch{}}
function renderTitle(){const el=$('title-screen');if(!el)return;el.hidden=!titleVisible;if(el.hidden){document.body?.classList.remove('in-intro');return}document.body?.classList.add('in-intro');
el.innerHTML=`<div class="intro-shell"><div class="intro-top"><span>ENCORE ${SANDBOX?'<small>LAB</small>':''}</span><button class="intro-theme" onclick="toggleTheme()" aria-label="Switch to ${theme==='dark'?'light':'dark'} mode">${theme==='dark'?'☀ Light mode':'◐ Dark mode'}</button></div><div class="intro-art" aria-hidden="true"><div class="intro-record"><div class="intro-label"><b>E</b><span>YOUR STORY<br>ON RECORD</span></div></div><div class="intro-groove"></div></div><div class="intro-overline">THE ARTIST LIFE SIM · BETA ${GAME_VERSION}</div><h1>Every legend starts somewhere.</h1><p>Make the records. Build your audience. Live with the choices that shape your career.</p><div class="intro-career">${s.started?`<span>CONTINUE AS</span><strong>${esc(s.name)}</strong><small>Year ${Math.floor((s.week-1)/52)+1} · Week ${(s.week-1)%52+1} · ${esc(s.genre)}</small>`:`<span>NEW CAREER</span><strong>The stage is yours</strong><small>Choose your background and write your first chapter.</small>`}</div><button class="intro-primary" onclick="enterGame()" ${saveReady?'':'disabled'}>${!saveReady?'Loading career…':s.started?'Continue career':'Start career'}</button><button class="intro-secondary" onclick="betaInfo()">Beta info & feedback</button><div class="intro-footer">${OFFLINE?'Saved on this device':'Career autosaved in this browser'} · ${SANDBOX?'Separate test career':'No sign-up'}</div></div>`}
let tourOrigin=null,tourTarget=null;
const gameplayTour=[
{page:'Home',target:'.home-dashboard',title:'Your weekly resources',text:()=>`You have ${s.ap} time slots and ${s.energy} energy. Most actions use both. Cash pays for recordings and features; fans determine your reach.`},
{page:'Home',target:'.home-quick',title:'Keep your career moving',text:()=>`Work earns $180 for 1 slot and 15 energy. Open mics earn cash, fans, and Stage Presence XP. Rest restores up to 30 energy for 1 slot.`},
{page:'Create',target:'.screen-create .grid > .card',title:'Turn an idea into a song',text:()=>s.draft?`This is your current song. The checked stages show what you have finished. Recording costs $40 and mixing costs $30; each uses 1 slot and 15 energy.`:`Enter a title or use Shuffle, choose a creative direction, then Start writing. Writing uses 1 slot and 10 energy. Recording and mixing follow here.`},
{page:'Create',target:'.screen-create .grid > .card',title:'Finish, then release',text:()=>`A full single takes 4 slots, 45 energy, and $90: write → record ($40) → mix ($30) → release ($20). You can continue across weeks. Release results arrive when you advance the week.`},
{page:'Stats',target:'.development-card',title:'Train before recording',text:()=>`Tap Train on a stat to choose a session. Training uses energy, but no time slot. Writing, Recording, and Producing shape quality; Charisma and Marketability help it connect. Higher levels need more XP.`},
{page:'Industry',section:'Artists',target:'.artistgrid',title:'Build relationships and book features',text:()=>`Tap an artist to talk, support, or negotiate. Features need an active song, enough fans and reputation, and sometimes cash. Friendship can lower the fee; beef hurts your chances.`},
{page:'Industry',section:'Charts',target:'.chart-summary',title:'Watch your records compete',text:()=>`Charts update after each week. Each entry tracks movement, debut, peak, and weeks charting. A good song still needs enough streams to beat the competition.`},
{page:'Career',section:'Releases',target:'.screen-career .grid > .card',title:'Follow your catalog',text:()=>`Released songs and albums live here. Open a release for its performance, chart history, and certification progress. Finished tracks for future albums stay in Create.`},
{page:'Career',section:'Achievements',target:'.achievement-controls',title:'Keep your milestones',text:()=>`Achievements unlock as your career grows. This screen also holds your briefing archive and pop-up toggle. Your songs and albums get one combined report every four weeks.`},
{page:'Home',target:'.weekbar',title:'Advance when you are ready',text:()=>`Advance week calculates streams, fans, royalties, overhead, and tax reserves. It restores six slots and up to 40 energy. Unused slots do not carry over. Review the confirmation, then read your recap.`}
];
function tourOffer(){if(!saveReady||tourHasPlayed())return;modal(`<h2>Learn by touring your career?</h2><p>We’ll move through the actual game screens and point out the controls. Next and Back guide the tour; you can skip anytime.</p><div class="controls"><button class="secondary" onclick="markTourSeen();$('modal').close()">Skip and play</button><button class="primary" onclick="openTour(0)">Start gameplay tour</button><button class="secondary" onclick="markTourSeen();startPractice()">Practice a release</button></div>`)}
function showTitle(){if(!saveReady)return;if(tourStep>=0)endTour(false);titleVisible=true;renderTitle()}
function enterGame(){if(!saveReady)return;titleVisible=false;renderTitle();go('Home');if(!s.started&&!SANDBOX)setup();else tourOffer()}
function openTour(step=0){if(!saveReady||saveConflict)return;if($('modal').open)$('modal').close();if(tourStep<0)tourOrigin={tab,careerTab,industryTab,chartKind,chartMine};titleVisible=false;tourStep=Math.max(0,Math.min(gameplayTour.length-1,step));renderTitle();const t=gameplayTour[tourStep];if(t.page==='Industry'){industryTab=t.section;if(t.section==='Charts'){chartKind='Songs';chartMine=false}}if(t.page==='Career')careerTab=t.section;tab=t.page;render();renderGameplayTour();}
function clearTourTarget(){if(tourTarget){tourTarget.classList?.remove('tour-target');if(tourTarget.style)tourTarget.style.scrollMarginTop='';tourTarget=null}}
function renderGameplayTour(){const panel=$('gameplay-tour');if(!panel)return;clearTourTarget();panel.hidden=tourStep<0;document.body?.classList[tourStep>=0?'add':'remove']('tour-running');for(const el of document.querySelectorAll?.('main,nav,.weekbar')||[])el.inert=tourStep>=0;if(tourStep<0)return;const t=gameplayTour[tourStep];panel.innerHTML=`<div class="coach-inner"><div class="coach-top"><span>GAMEPLAY TOUR · ${tourStep+1} / ${gameplayTour.length}</span><button class="text-button" onclick="endTour()">Skip tour</button></div><h2 id="coach-title">${esc(t.title)}</h2><p>${esc(t.text())}</p><div class="coach-controls"><button class="secondary" ${tourStep===0?'disabled':''} onclick="openTour(tourStep-1)">Back</button><span>${esc(t.page)}${t.section?' · '+esc(t.section):''}</span><button class="primary" onclick="${tourStep===gameplayTour.length-1?'endTour()':'openTour(tourStep+1)'}">${tourStep===gameplayTour.length-1?'Finish tour':'Next'}</button></div></div>`;const target=document.querySelector?.(t.target);if(target){tourTarget=target;target.classList?.add('tour-target');if(target.style)target.style.scrollMarginTop=((panel.getBoundingClientRect?.().height||220)+18)+'px';target.scrollIntoView?.({behavior:'auto',block:'start'})}panel.querySelector?.('h2')?.setAttribute('tabindex','-1');panel.querySelector?.('h2')?.focus({preventScroll:true})}
function endTour(mark=true){if(mark)markTourSeen();tourStep=-1;renderGameplayTour();titleVisible=false;renderTitle();if(tourOrigin){({tab,careerTab,industryTab,chartKind,chartMine}=tourOrigin);tourOrigin=null}render();window.scrollTo?.(0,0);scheduleBriefing()}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(window.tt);window.tt=setTimeout(()=>$('toast').hidden=true,3500)}function log(t){s.history.unshift({week:s.week,text:t});s.history=s.history.slice(0,100)}function go(t){tab=({Studio:'Create',Training:'Stats'}[t]||t);render();window.scrollTo(0,0)}function spend(energy=10,cost=0){if(!saveReady||saveConflict)return false;if(!s.ap){toast('Your week is full. Advance for six new slots.');return false}if(s.energy<energy){toast('Rest to recover energy first.');return false}if(cost>0&&s.cash<cost){toast('Not enough cash. Work a shift or save up.');return false}s.started=true;s.ap--;s.energy-=energy;changeCash(-cost);s.finance.week.expenses=cents(s.finance.week.expenses+cost);return true}
function modal(html,style=''){ $('modal').className=style;$('modal').innerHTML=`<button class="close" onclick="$('modal').close()" aria-label="Close">×</button>${html}`;if(!$('modal').open)$('modal').showModal()}
function render(){if(!saveReady)return;migrateExpansion();migrateExperience();migrateLabelBusiness();scanAchievements();applyTheme();$('week').textContent='YEAR '+(Math.floor((s.week-1)/52)+1)+' · WEEK '+((s.week-1)%52+1);$('time').textContent=s.ap+' of 6 time slots available';$('weekly-cost').textContent='Career overhead: '+Math.round(operationRate()*100)+'%';$('nav').innerHTML=['Career','Create','Home','Stats','Industry'].map((t,i)=>`<button class="${(tab===t)?'active':''} ${t==='Home'?'nav-home':''}" aria-current="${(tab===t)?'page':'false'}" onclick="go('${t}')"><svg viewBox="0 0 24 24" aria-hidden="true">${icons[{Home:0,Create:1,Career:4,Industry:3,Stats:2}[t]]}</svg>${t}</button>`).join('');$('app').innerHTML=offlineBanner()+sandboxBar()+({Home:home,Create:studio,Studio:studio,Career:career,Industry:industry,Artist:artist,Stats:training,Training:training}[tab])();$('app').className='screen-'+tab.toLowerCase();queueSave();scheduleBriefing()}
function head(label,title,right=''){return `<div class="heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1></div>${right}`+'</div>'}
function stats(){return `<div class="stats">${[['Cash',money(s.cash)],['True fans',compact(s.fans)],['Last week’s streams',compact(s.streams)],['Energy',s.energy+'<span style="font-size:15px" class="muted"> /100</span>']].map(([l,v])=>`<div class="stat"><label>${l}</label><strong>${v}</strong></div>`).join('')}</div>`}
function latestReleaseCard(){const track=s.songs.filter(x=>x.released).slice().sort((a,b)=>b.released-a.released||b.id-a.id)[0];if(!track)return '';return `<section class="card latest-release"><span class="eyebrow">Latest release</span><h2>${esc(track.title)}</h2><div class="release-summary"><div><strong>${compact(track.streams||0)}</strong><small>Weekly streams</small></div><div><strong>${chartPosition(track)?'#'+chartPosition(track):'Uncharted'}</strong><small>Current chart</small></div></div><button class="secondary" onclick="releaseDetails('songs',${track.id})">View release</button></section>`}
function home(){const latest=s.songs.filter(x=>x.released).slice().sort((a,b)=>(b.released||0)-(a.released||0))[0];return `<div class="home-heading"><div><span class="eyebrow">Year ${Math.floor((s.week-1)/52)+1} · Week ${(s.week-1)%52+1}</span><h1>${esc(s.name)}</h1></div><span class="pill">${tierNames[tier(s.fans)]}</span></div>`+homeStats()+betaHomeNotice()+`<section class="home-focus"><div><span class="eyebrow">${s.draft?'In progress':latest?'Latest release':'Your first chapter'}</span><h2>${esc(s.draft?s.draft.title:latest?latest.title:'Make your first record')}</h2><p>${s.draft?'Pick up where you left off in the studio.':latest?compact(latest.streams||0)+' streams this week · '+(chartPosition(latest)?'Chart #'+chartPosition(latest):'Uncharted'):'Your story starts in the studio. Write, record, mix, and release.'}</p></div><button class="primary" onclick="${s.started?"go('Studio')":"setup()"}">${s.started?s.draft?'Continue song':'Open studio':'Create artist'}</button></section><div class="home-brief"><button onclick="careerTab='Achievements';go('Career')"><strong>Briefings</strong><span>${s.achievements.briefings.filter(x=>!x.read&&!x.id.startsWith('cert:')).length} new · ${Object.keys(s.achievements.unlocked).length} achievements</span></button><button onclick="careerTab='Profile';go('Career')"><strong>Career file</strong><span>${s.songs.filter(x=>x.released).length} releases · ${compact(s.total)} plays</span></button></div><section class="home-quick"><div class="sectionhead"><h2>Quick moves</h2><button class="text-button" onclick="openTour(0)">How to play</button></div><div class="actions"><button class="action" onclick="action('work')">Work a shift<small>+$180 · 1 slot · 15 energy</small></button><button class="action" onclick="action('gig')">Open mic<small>Earn cash & fans · 1 slot · 20 energy</small></button><button class="action" onclick="action('rest')">Rest<small>+30 energy · 1 slot</small></button></div></section>`}
function action(a){if(a==='rest'&&s.energy===100){toast('You’re fully rested. Save that time slot for something else.');return}if(a==='practice'){trainingDetail('writing');return}if(a==='promo'&&s.boost>0){toast('Your campaign is already running for this week.');return}if(a==='rest'){if(!spend(0))return;s.energy=clamp(s.energy+30);log('You recovered up to 30 energy.')}if(a==='work'){if(!spend(15))return;changeCash(180);recordIncome('wages',180);log('A shift paid $180. A little more runway.')}if(a==='practice'){if(!spend(10))return;s.skill=clamp(s.skill+4);log('Craft improved by 4. Your next session will benefit.')}if(a==='gig'){if(!spend(20))return;let fans=Math.round(5+level('stagePresence')*.16+level('charisma')*.04),pay=Math.round(25+level('marketability')*.2);changeCash(pay);recordIncome('live',pay);s.fans+=fans;s.careerRecords.openMics++;s.careerRecords.liveGross+=pay;s.careerRecords.liveProfit+=pay;gainXP('stagePresence',30);log('Open mic: '+fans+' new fans, '+money(pay)+' earned, +30 Stage Presence XP.')}if(a==='promo'){if(!s.songs.some(x=>x.released)){toast('Release a song first.');return}if(!spend(10,50))return;s.boost=campaignBoost();log('A $50 campaign adds '+Math.round(s.boost*100)+'% to catalog streams this week.')}render()}
function nameInput(id,kind,value='',placeholder=''){return `<div class="namefield"><input id="${id}" name="${id}" value="${esc(value)}" placeholder="${placeholder}" maxlength="55" required><button class="secondary" type="button" onclick="fillName('${id}','${kind}');if('${id}'==='songtitle')captureStudioIdea(this.closest('form'))">Shuffle</button></div>${kind==='song'||kind==='album'?dialMarkup(id,kind):''}`}
function newSong(e){e.preventDefault();if(s.draft)return;let f=new FormData(e.target),production=studioPackages[Number(f.get('package'))]||studioPackages[0];if(!spend(10,production.fee))return;s.studioIdea={title:'',mood:f.get('mood'),package:String(f.get('package')||'0')};s.started=true;s.draft={id:Date.now()+Math.random(),title:f.get('songtitle').trim()||generate('song'),mood:f.get('mood'),steps:1,quality:0,feature:null,development:JSON.parse(JSON.stringify(s.development)),songRules:2,genre:s.genre,productionBudget:production.fee,productionBonus:production.quality,variation:rand(-8,8),appeal:rand(-12,12)};scoreSong(s.draft);log('Started writing “'+s.draft.title+'”.');render()}
function progressSong(){let d=s.draft;if(!d||d.steps>=3||!spend(15,d.steps===1?40:30))return;d.steps++;if(d.songRules===2){for(const k of (d.steps===2?['recording','charisma']:['producing','marketability','viralAbility']))d.development[k]={...s.development[k]};scoreSong(d)}else d.quality=clamp(Math.round(d.quality+6+level(d.steps===2?'recording':'producing')*.06));render()}
function finishSong(release,confirmed=false){let d=s.draft;if(!d||d.steps!==3)return;if(release&&!confirmed){modal(`<h2>Publish this single?</h2><p>“${esc(d.title)}” will enter your released catalog. You cannot edit the finished recording afterward. Results arrive when you advance the week.</p><p>$20 · 1 time slot · 5 energy</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep in studio</button><button class="primary" onclick="$('modal').close();finishSong(true,true)">Release single</button></div>`);return}if(release&&!spend(5,20))return;const song={...d,released:release?s.week:null,streams:0,total:0,peak:null,album:null};s.songs.push(song);s.draft=null;log('“'+song.title+'” '+(release?'is out. Results arrive at the end of this week.':'is ready for your album.'));render();toast(release?'Single released. Advance the week for results.':'Finished track saved.')}
function releaseShelf(id,confirmed=false){let x=s.songs.find(x=>x.id===id);if(!x||x.released)return;if(!confirmed){modal(`<h2>Release “${esc(x.title)}”?</h2><p>This publishes the finished recording. Pay $20, 1 slot and 5 energy. Results arrive at week close.</p><button class="primary" onclick="releaseShelf(${id},true)">Publish single</button>`);return}if(!spend(5,20))return;$('modal').close();x.released=s.week;log('“'+x.title+'” is out.');render()}
function albumForm(){let eligible=s.songs.filter(x=>!x.album);modal(`<div class="eyebrow">Your next era</div><h2>Assemble an album.</h2><form class="form" onsubmit="releaseAlbum(event)"><label>Album title${nameInput('albumtitle','album')}</label>${pricingField()}<p class="fine">Select at least 3 tracks. Existing singles retain their streams; new tracks debut together.</p>${eligible.length?eligible.map(x=>`<label class="row" style="justify-content:flex-start"><input style="width:20px;margin:0" type="checkbox" name="track" value="${x.id}"><span>${esc(x.title)} <small class="muted">${x.released?'Released single':'Unreleased'}</small></span></label>`).join(''):'<p>Finish some tracks in the studio first.</p>'}<button class="primary" ${eligible.length<3?'disabled':''}>Release album · $100</button><span class="fine">1 slot · 10 energy</span></form>`)}
let pendingAlbum=null;
function releaseAlbum(e,confirmed=false){e?.preventDefault();let f=confirmed?pendingAlbum:new FormData(e.target);if(!f)return;let ids=f.getAll('track').map(Number),tracks=s.songs.filter(x=>ids.includes(x.id)&&!x.album);if(tracks.length<3){toast('Choose at least 3 finished tracks.');return}if(!confirmed){pendingAlbum=f;modal(`<h2>Publish this album?</h2><p>${tracks.length} tracks · ${money(Number(f.get('price'))||10)} download price · $100 release fee · 1 slot · 10 energy. Unreleased tracks debut together, and each chosen song joins this album permanently.</p><button class="primary" onclick="releaseAlbum(null,true)">Publish album</button>`);return}if(!spend(10,100))return;pendingAlbum=null;let a={price:albumPrices.some(p=>p.value===Number(f.get('price')))?Number(f.get('price')):10,sales:0,salesRevenue:0,weeklySales:0,id:Date.now(),title:f.get('albumtitle').trim()||generate('album'),week:s.week,tracks:tracks.map(x=>x.id),criticalReception:Math.round(clamp(tracks.reduce((n,x)=>n+x.quality,0)/tracks.length+rand(-8,8))),cohesion:Math.round(clamp(85-(Math.max(...tracks.map(x=>x.quality))-Math.min(...tracks.map(x=>x.quality)))*.4+(s.expansion.albumRollout&&s.expansion.albumRollout.until>=s.week&&ids.includes(s.expansion.albumRollout.lead)?10:0)))};tracks.forEach(x=>{x.album=a.id;if(!x.released)x.released=s.week;x.albumBoost=s.week});s.albums.push(a);updateCertifications();log('Released “'+a.title+'”, a '+tracks.length+'-track album.');$('modal').close();tab='Career';render()}
function outcome(f){return f<.65?'Flop':f>=1.5?'Hit':'On target'}
const CHART_FLOOR=250000,CHART_SIZE=100;
function widerIndustry(){const week=s.chartWeek??Math.max(1,s.week-1);const first=['Luna','Cedar','Apollo','Ruby','Dante','Willow','Elio','Sable','Raven','Nico','Violet','Ocean','Remi','Arden','Flora'];const last=['Echo','Coast','Bloom','Fox','Ray','Moon','King','Waves','Hart','Wren'];return Array.from({length:150},(_,i)=>{let era=Math.floor((week+i%8)/8),swing=.82+.36*(.5+.5*Math.sin(i*2.7+week*.61));return {key:'bg:s:'+i+':'+era,releaseWeek:era*8-i%8,title:titles.song[0][(i+era)%10]+' '+titles.song[1][(Math.floor(i/10)+era*3)%10],artist:first[i%15]+' '+last[Math.floor(i/15)],tier:i<20?'Global star':i<75?'Superstar':'Star',streams:Math.round((100000+12000000*Math.pow(1-i/150,3))*swing),background:true}})}

function chartPosition(track){let i=chart().findIndex(x=>x.you&&x.id===track.id);return i<0?null:i+1}
function migrateCharts(){if(s.chartRulesVersion===2)return;for(const track of s.songs){if(track.peak)track.legacyPeak=track.peak;track.peak=null} s.chartRulesVersion=2;s.chartWeek=Math.max(1,s.week-1);log('Global Top 100 now includes the wider industry. Earlier prototype peaks are kept in your release details.');}

function catalog(){let songs=s.songs.filter(x=>x.released);return head('Your music in the world','Your catalog.',`<span class="pill">${songs.length} songs · ${s.albums.length} albums</span>`)+metricRail([['Weekly plays',compact(s.streams)],['Lifetime plays',compact(s.total)],['Fans',compact(s.fans)],['Reputation',s.reputation+'/100']])+`<div class="grid"><section class="card"><div class="sectionhead"><h2>Discography</h2><button class="secondary" onclick="go('Studio')">New music</button></div>${songs.length?songs.slice().reverse().map(x=>`<div class="track"><span class="recordno">${x.album?'ALB':'SGL'}</span><div><button class="release-link" onclick="releaseDetails('songs',${x.id})">${esc(x.title)}</button>${certBadge(x,'songs')}<span class="fine">${x.feature?'feat. '+esc(x.feature.name)+' · ':''}${x.total?outcome(x.factor):'Awaiting debut'}${chartPosition(x)?' · #'+chartPosition(x):x.total?' · Uncharted':''}${x.peak===1?' · Chart topper':x.peak?' · Peak #'+x.peak:''}</span><div class="fine">${esc(x.lifecycle||'Awaiting discovery')} · Quality ${x.quality}/100 · Commercial ${x.commercial??'—'}/100</div><div class="fine">${compact(x.streams)} this week · ${compact(x.total)} total</div>${x.legacyPeak?`<p class="fine">Earlier prototype peak: #${x.legacyPeak} (old chart rules)</p>`:''}${x.breakdown?`<details><summary class="fine">Why this result?</summary><p class="fine">${esc(x.breakdown)}</p></details>`:''}</div>${x.factor?`<span class="badge">${x.factor.toFixed(1)}×</span>`:''}</div>`).join(''):'<div class="empty"><h3>Your first era starts here.</h3><p>Release a single or build an album.</p></div>'}${s.albums.length?'<h2 style="margin-top:24px">Albums</h2>'+s.albums.map(a=>{let ts=s.songs.filter(x=>a.tracks.includes(x.id));return `<div class="row"><div><button class="release-link" onclick="releaseDetails('albums',${a.id})">${esc(a.title)}</button>${certBadge(a,'albums')}<span class="fine">${ts.length} tracks · Week ${a.week} · Cohesion ${a.cohesion??'—'}/100</span><p class="fine">${money(a.price)} download · ${fmt(a.sales)} copies sold · ${money(a.salesRevenue)} gross</p><button class="secondary" onclick="changeAlbumPrice(${a.id})">Change price</button></div><strong>${compact(ts.reduce((n,x)=>n+x.total,0))} total</strong></div>`}).join(''):''}</section><div><section class="card"><h2>Your artist</h2><button class="secondary" onclick="go('Artist')">Profile & save settings</button><hr><h2>Live circuit</h2><p>Progress from local rooms to stadiums. Compare demand, budgets, and ticket revenue before booking.</p><p class="fine">Three shows per run · 2 slots · Upfront budgets and energy vary by skills.</p><button class="secondary" onclick="playTour()" ${s.fans<250?'disabled':''}>Review tour venues</button></section><section class="card"><h2>What counts as a hit?</h2><p>A debut below <strong>0.65×</strong> its expected audience is a flop. At <strong>1.5×</strong> or higher, it’s a hit. Number one on the global song chart earns “chart topper.”</p><p class="fine">A superstar’s flop can still dwarf an unknown artist’s hit. The multiplier measures performance relative to your reach at release.</p></section><section class="card"><h2>Plan your next era</h2><p>Compare promotion budgets or announce a four-week album rollout. Costs and boosts are shown before purchase.</p><button class="secondary" onclick="careerTab='Campaigns';render()">Campaigns & rollouts</button></section></div></div>`}
function relationship(a){return a.relation<=-40?'Beef':a.relation<0?'Tense':a.relation<30?'Unfamiliar':a.relation<60?'Friendly':a.relation<85?'Close':'Inner circle'}
function baseFee(a){let t=tier(a.fans);return Math.round([80,900,5000,25000,140000,650000,2000000][t]*(.65+a.reputation/100)*Math.pow(Math.max(1,a.fans/Math.max(500,thresholds[t])),.18)/10)*10}
function freeEligible(a){return accessible(a)&&a.relation>=(tier(a.fans)>=5?98:90)&&s.reputation>=a.reputation-10}
function quote(a){if(freeEligible(a))return 0;return Math.max(10,Math.round(baseFee(a)*(1-Math.max(-60,a.relation)*.006)*(1-a.discount)/10)*10)}
function featureNeeds(a){let t=tier(a.fans);return {fans:t>=2?thresholds[t-2]:0,rep:Math.max([0,5,15,30,48,65,82][t],Math.round(a.reputation)-25),relation:[0,0,0,15,30,50,70][t]}}
function accessible(a){let n=featureNeeds(a);return a.relation>-40&&s.fans>=n.fans&&s.reputation>=n.rep&&a.relation>=n.relation}
function featureRequirements(a){let n=featureNeeds(a);return `<div class="requirements">${[['Fans',s.fans,n.fans,compact],['Reputation',s.reputation,n.rep,fmt],['Relationship',a.relation,n.relation,fmt]].map(([label,v,min,format])=>`<div><span>${v>=min?'✓':'○'} ${label}</span><strong>${format(v)} / ${format(min)}</strong></div>`).join('')}</div>`}

function profile(id){let a=s.world[id],fee=quote(a),blocked=a.relation<=-40,access=accessible(a);modal(`<div class="eyebrow">${tierNames[tier(a.fans)]} · ${esc(a.genre)}</div><h2>${esc(a.name)}</h2><p>${compact(a.fans)} fans · ${compact(a.catalog.reduce((n,x)=>n+x.streams,0))} weekly streams</p><div class="row"><span>${relationship(a)}</span><strong class="${a.relation<0?'bad':'highlight'}">${a.relation>0?'+':''}${a.relation} / 100</strong></div><p class="fine">Talk builds trust. Support helps faster. Beef damages trust, raises fees, and at −40 shuts collaborations down.</p><div class="controls"><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'talk')">Talk · 1 slot</button><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'support')">Support · $25</button><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'beef')">Start beef</button>${a.relation<0?`<button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'apologize')">Apologize</button>`:''}</div><p class="fine">One social interaction per artist per week. Each uses 1 slot and 5 energy.</p><hr style="border:0;border-top:1px solid var(--line);margin:23px 0"><h3>Feature offer</h3><p class="fine">Artist reputation: ${fmt(a.reputation)}/100. Audience and reputation set the base price; friendship and negotiation can reduce it.</p><div class="quote">${fee===0?'On the house':money(fee)}</div><p class="fine">Standard fee ${money(baseFee(a))} · ${a.discount?'Negotiated discount active':'Relationship-adjusted quote'}</p><p>${blocked?'They won’t collaborate while you’re beefing. Repair the relationship first.':!access?'Meet all three requirements below before they will consider your record.':freeEligible(a)?'They trust you enough to waive the fee.':'They’re open to a feature. The price reflects your relationship.'}</p>${featureRequirements(a)}<div class="controls"><button class="secondary" ${blocked||!access||a.lastNegotiate===s.week?'disabled':''} onclick="negotiate(${id})">Negotiate · 1 slot</button><button class="primary" ${blocked||!access||!s.draft||!!s.draft.feature||s.cash<fee?'disabled':''} onclick="bookFeature(${id})">${fee===0?'Accept free feature':'Book · '+money(fee)}</button></div><p class="fine">${!s.draft?'Start a song in Studio to attach a feature.':s.draft.feature?'Your current song already has a guest.':'Booking attaches the artist to your current song. Fee is charged immediately; booking itself uses no extra slot.'} A guest expands reach but does not guarantee a hit.</p><h3 style="margin-top:24px">Recent releases</h3>${a.catalog.slice(-3).reverse().map(x=>`<div class="row"><div><strong>${esc(x.title)}</strong><div class="fine">${x.type} · ${outcome(x.factor)}</div></div><span>${compact(x.streams)} / wk</span></div>`).join('')}`)}
function social(id,kind,confirmed=false){if(kind==='beef'&&!confirmed){modal(`<h2>Call out ${esc(s.world[id].name)}?</h2><p>This costs one time slot and 5 energy. Relationship falls by 35 and fan loyalty and reputation by 2. Feature fees rise; at −40 they refuse to collaborate.</p><div class="controls"><button class="secondary" onclick="profile(${id})">Keep the peace</button><button class="primary" onclick="social(${id},'beef',true)">Start beef</button></div>`);return}let a=s.world[id];if(a.lastTalk===s.week)return;if(!spend(5,kind==='support'?25:0))return;let delta=kind==='beef'?-35:kind==='apologize'?20:kind==='support'?15:Math.round(rand(7,12));if(delta>0&&kind!=='apologize')delta=Math.max(1,Math.round(delta/(1+Math.max(0,tier(a.fans)-tier(s.fans))*.5))); a.relation=clamp(a.relation+delta,-100,100);a.lastTalk=s.week;if(kind==='beef'){a.discount=0;s.loyalty=clamp(s.loyalty-2);s.reputation=clamp(s.reputation-2);log('You called out '+a.name+'. Relationship fell by 35; loyalty and reputation fell by 2.')}else log((kind==='apologize'?'You apologized to ':kind==='support'?'You supported ':'You talked with ')+a.name+'. Relationship +'+delta+'.');render();profile(id)}
function negotiate(id){let a=s.world[id];if(a.lastNegotiate===s.week||a.relation<=-40||!accessible(a)||!spend(5))return;a.lastNegotiate=s.week;let chance=clamp(35+a.relation*.4+(s.reputation-a.reputation)*.35-Math.max(0,tier(a.fans)-tier(s.fans))*5,10,90);if(Math.random()*100<chance){a.discount=Math.min(.4,a.discount+.15);log(a.name+' agreed to a lower feature fee.');toast('Negotiation landed. Your quote is lower.')}else{a.relation=clamp(a.relation-3,-100,100);log(a.name+' declined the offer. Relationship −3.');toast('They declined. You can try again next week.')}render();profile(id)}
function bookFeature(id,confirmed=false){if(!saveReady||saveConflict)return;let a=s.world[id],fee=quote(a);if(!s.draft||s.draft.feature||a.relation<=-40||!accessible(a)||s.cash<fee)return;if(fee>0&&!confirmed){modal(`<h2>Confirm feature</h2><p>${esc(a.name)} will join “${esc(s.draft.title)}”.</p><div class="row"><span>Charged now</span><strong>${money(fee)}</strong></div><p>No time slot is used. The fee is non-refundable and a feature does not guarantee a hit.</p><div class="controls"><button class="secondary" onclick="profile(${id})">Back to offer</button><button class="primary" onclick="bookFeature(${id},true)">Pay ${money(fee)}</button></div>`);return}changeCash(-fee);s.finance.week.expenses=cents(s.finance.week.expenses+fee);s.draft.feature={id:a.id,name:a.name,fans:a.fans,fee};a.relation=clamp(a.relation+5,-100,100);a.discount=0;log(a.name+' joined “'+s.draft.title+'” for '+(fee?money(fee):'free')+'.');$('modal').close();render();toast('Feature booked. Finish your record in Studio.')}
function industry(){let tabs=['Artists','Charts','New releases'];let top=head('A living music scene','The industry.')+`<div class="chips">${tabs.map(x=>`<button class="${industryTab===x?'selected':''}" onclick="industryTab='${x}';render()">${x}</button>`).join('')}</div>`;if(industryTab==='Charts')return top+chartHub();if(industryTab==='New releases')return top+`<section class="card"><h2>This week in music</h2>${s.feed.length?s.feed.slice(0,30).map(x=>`<div class="track"><span class="recordno">${x.type==='Album'?'ALB':'SGL'}</span><div><h3>${esc(x.title)}</h3><span class="fine">${esc(x.name)} · ${x.tier} · Week ${x.week}</span><p class="fine">${compact(x.streams)} debut streams · ${x.result}</p></div></div>`).join(''):'<p>The next releases arrive when you advance the week.</p>'}</section>`;return top+`<div class="chips">${['All',...tierNames].map(x=>`<button class="${filter===x?'selected':''}" onclick="filter='${x}';render()">${x}</button>`).join('')}</div><div class="roster-controls"><label>Genre <select onchange="genreFilter=this.value;render()">${['All',...genres].map(g=>`<option ${g===genreFilter?'selected':''}>${g}</option>`).join('')}</select></label><span class="fine">${s.world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter)).length} artists · Tap to meet</span></div><div class="artistgrid">${s.world.filter(a=>(filter==='All'||tierNames[tier(a.fans)]===filter)&&(genreFilter==='All'||a.genre===genreFilter)).map(a=>`<button class="artistcard" onclick="profile(${a.id})"><div class="initials">${a.name.split(' ').map(x=>x[0]).join('')}</div><span class="tier">${tierNames[tier(a.fans)]}</span><h3>${esc(a.name)}</h3><p>${esc(a.genre)} · ${compact(a.fans)} fans</p><p>${compact(a.catalog.reduce((n,x)=>n+x.streams,0))} streams / week</p><p class="rep-line">Reputation <strong>${fmt(a.reputation)}/100</strong></p><p class="${a.relation<0?'bad':''}">${relationship(a)} · ${a.relation>0?'+':''}${a.relation}</p><span class="feature-price">${a.relation<=-40?'Beef · unavailable':quote(a)?'Feature '+money(quote(a)):'Free feature'}</span><span class="fine">${accessible(a)?'Open to collaborate':'Career requirements apply'}</span></button>`).join('')}</div><section class="card" style="margin-top:20px"><h2>Different leagues. Same industry.</h2><p>Unknown → Emerging → Breakout → Star → Superstar → Global star → Global icon. Icons start at 100 million fans in this fictional world.</p><p class="fine">Stream totals depend on audience size, release quality, reception, promotion, features, and catalog age. Artists release new singles and albums on their own schedules.</p></section>`}
function artist(){return head('Identity & growth',esc(s.name)+'.',`<button class="secondary" onclick="setup()">Edit profile</button>`)+`<button class="training-launch" onclick="go('Training')"><span><strong>Training & stat improvement</strong><small>See your stats, choose an activity, and track your progress</small></span><span>Open training</span></button>`+`<section class="identity-banner"><span class="identity-monogram">${esc(s.name.slice(0,2).toUpperCase())}</span><div><span class="eyebrow">${esc(s.genre)} · ${s.labelBusiness?.company?'Founder, '+esc(s.labelBusiness.company.name):s.expansion.contract?esc(s.expansion.contract.name):'Independent'}</span><h2>${tierNames[tier(s.fans)]}</h2><p>${compact(s.fans)} fans · Reputation ${s.reputation}/100</p></div></section>`+`<div class="grid"><section class="card"><span class="tier">${tierNames[tier(s.fans)]} · ${s.labelBusiness?.company?'Founder, '+esc(s.labelBusiness.company.name):s.expansion.contract?esc(s.expansion.contract.name):'Independent'}</span><h2 style="margin-top:14px">${esc(s.genre)} · ${esc(s.background)}</h2>${[['Reputation',s.reputation],['Fan loyalty',s.loyalty],['Energy',s.energy]].map(([t,n])=>`<div class="sectionhead" style="margin:22px 0 0"><span>${t}</span><strong>${n}/100</strong></div><div class="bar"><i style="width:${n}%"></i></div>`).join('')}</section><section class="card" style="align-self:start"><h2>Your career so far</h2><p class="fine">Reputation grows through quality releases (+1 at quality 60+) and hits (+2). Public beef costs 2 reputation. Fame alone won’t unlock every collaboration.</p>${[['Weeks',s.week],['Released tracks',s.songs.filter(x=>x.released).length],['Albums',s.albums.length],['Lifetime streams',compact(s.total)],['Close relationships',s.world.filter(x=>x.relation>=60).length]].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join('')}<p class="fine">Playable simulation. Your career autosaves. Return with this browser to continue. Use Career → Saves to export a backup before switching browsers or clearing cookies. No audio is generated. Economy values are game settings, not real-world income forecasts.</p><div class="settings-actions"><button class="secondary" onclick="betaInfo()">Beta & feedback</button><button class="secondary" onclick="careerTab='Saves';go('Career')">Export, import & recovery</button><button class="secondary" onclick="toggleTheme()">${theme==='dark'?'Use light mode':'Use dark mode'}</button><button class="secondary" onclick="openTour(0)">Replay how to play</button><button class="secondary" onclick="showTitle()">Title screen</button></div><button class="secondary" onclick="resetAsk()">Start a new career</button></section></div>`}
const backgroundStarts={
'Bedroom artist':{craft:35,stage:25,fans:42,marketability:25,viralAbility:25,description:'A stronger foundation in writing, recording, and producing.'},
'Local performer':{craft:25,stage:40,fans:60,marketability:25,viralAbility:25,description:'More stage experience and a small local following.'},
'Online creator':{craft:20,stage:20,fans:120,marketability:40,viralAbility:40,description:'A larger starting audience and stronger promotion and discovery skills.'}
};
function backgroundPreview(name){const b=backgroundStarts[name]||backgroundStarts['Bedroom artist'];return `<p>${b.description}</p><dl class="profile-facts">${[['Writing / Recording / Producing',b.craft+' each'],['Charisma / Touring','25 each'],['Marketability',b.marketability],['Stage Presence',b.stage],['Viral Ability',b.viralAbility],['Starting fans',b.fans]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><p class="fine">Every background starts with $650, 100 energy, and 6 time slots. Applied once when you begin.</p>`}
function applyStartingBackground(name){const key=Object.hasOwn(backgroundStarts,name)?name:'Bedroom artist',b=backgroundStarts[key];s.background=key;s.skill=b.craft;s.stage=b.stage;s.fans=b.fans;s.development=initialDevelopment(b.craft,b.stage,25);s.development.marketability.level=b.marketability;s.development.viralAbility.level=b.viralAbility;s.backgroundRules=1}
function setup(){modal(`<div class="eyebrow">Your name on the marquee</div><h2>${s.started?'Your artist.':'Create your artist.'}</h2><form class="form" onsubmit="saveProfile(event)"><label>Stage name${nameInput('artistname','artist',s.name)}</label><label>Genre<select name="genre">${genres.map(x=>`<option ${s.genre===x?'selected':''}>${x}</option>`).join('')}</select></label>${s.started?'':`<label>Background<select name="bg" onchange="$('background-preview').innerHTML=backgroundPreview(this.value)"><option>Bedroom artist</option><option>Local performer</option><option>Online creator</option></select></label><div id="background-preview">${backgroundPreview('Bedroom artist')}</div>`}<button class="primary">${s.started?'Save profile':'Begin your career'}</button></form>`)}
function saveProfile(e){e.preventDefault();if(!saveReady||saveConflict)return;const firstProfile=!s.started;let f=new FormData(e.target);s.name=f.get('artistname').trim()||generate('artist');s.genre=f.get('genre');if(!s.started){applyStartingBackground(f.get('bg'));s.started=true}$('modal').close();render();if(firstProfile)tourOffer()}
function resetAsk(){modal(`<h2>A fresh start?</h2><p>${SANDBOX?'This resets only your sandbox, including its test releases. Your normal career is untouched.':'This erases the current career and all relationships.'}</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="newCareer()">New career</button></div>`)}
// Reception varies independently of audience size. A hit is relative to expected reach.
function reception(quality){let r=Math.random(),luck=r<.15?rand(.3,.55):r>.9?rand(1.7,2.4):rand(.8,1.2);return Math.max(.15,luck*(.35+quality*.014))}
function worldWeek(){s.world.forEach(a=>{a.catalog.forEach(x=>{x.streams=Math.max(1,Math.round(x.streams*rand(.82,.96)));x.total+=x.streams});if(s.week>=a.nextRelease){let type=Math.random()<.25?'Album':'Single',factor=reception(a.skill),base=Math.round(a.fans*rand(.55,.85)*(type==='Album'?4:1)),streams=Math.round(base*factor),x={uid:a.nextCatalogId++,title:generate(type==='Album'?'album':'song'),type,week:s.week,base,factor,streams,total:streams};a.catalog.push(x);a.fans+=Math.round(streams*.009);a.reputation=clamp(a.reputation+(factor>=1.5?.4:factor<.65?-.3:0));s.feed.unshift({name:a.name,title:x.title,type,week:s.week,tier:tierNames[tier(a.fans)],streams,result:outcome(factor)});a.nextRelease=s.week+Math.round(rand(4,9));if(type==='Album'){let trackStreams=Math.round(streams*.25);a.catalog.push({uid:a.nextCatalogId++,title:generate('song'),type:'Single',week:s.week,base:Math.round(base*.25),factor,streams:trackStreams,total:trackStreams,fromAlbum:true,albumIndex:a.catalog.length-1});x.streams-=trackStreams;x.total-=trackStreams}}a.weekly=a.catalog.reduce((n,x)=>n+x.streams,0)});s.feed=s.feed.slice(0,60)}
function advance(confirmed=false){if(!saveReady||saveConflict)return;if(!confirmed){modal(`<h2>Finish the week?</h2><p>You have ${s.ap} unused time slot${s.ap===1?'':'s'}. They won’t carry over. Career overhead is ${Math.round(operationRate()*100)}% of music income; a tax reserve may also be set aside.</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep playing</button><button class="primary" onclick="$('modal').close();advance(true)">Finish week</button></div>`);return}beginCareerWeek();const overheadRate=operationRate();let count=0,added=0,debut=[];s.songs.filter(x=>x.released).forEach(x=>{let n;if(x.factor===undefined){let guest=x.feature?s.world[x.feature.id]:null;let featureReach=guest?x.feature.fans*(guest.relation<=-40?.004:.018):0;x.base=reach(x);x.factor=reception(x.quality)*(x.songRules===2?(.55+x.commercial*.009):1)*(x.mood.startsWith('Raw')?rand(.65,1.4):directionFor(x).reach)*(1+s.boost)*(x.albumBoost===s.week?1.15:1);x.launchFans=s.fans;n=Math.round(x.base*x.factor);x.debutStreams=n;x.organic=n/(1+s.boost)/(x.albumBoost===s.week?1.15:1);x.breakdown='Expected reach '+compact(x.base)+'; quality '+x.quality+'/100'+(x.songRules===2?'; commercial potential '+x.commercial+'/100':'')+'; '+x.mood.split(' /')[0].toLowerCase()+' direction'+(guest?'; guest '+guest.name:'')+'; promotion '+Math.round(s.boost*100)+'%. Audience reception helped determine the final '+x.factor.toFixed(2)+'× debut. '+(x.factor<.65?'Try improving your craft before your next recording.':x.factor>=1.5?'This release outperformed its expected audience.':'This release performed within the expected range.');s.reputation=clamp(s.reputation+(x.quality>=60?1:0)+(x.factor>=1.5?2:0));debut.push(x);log('“'+x.title+'” debuted with '+compact(n)+' streams: '+outcome(x.factor).toLowerCase()+'.')}else{let guest=x.feature?s.world[x.feature.id]:null;let conflict=guest&&guest.relation<=-40?.8:1;x.organic=Math.max(8,(x.organic??x.streams)*rand(...directionFor(x).decay)+s.fans*.002/Math.sqrt(Math.max(1,s.songs.filter(x=>x.released).length)));n=Math.round(x.organic*(1+s.boost)*conflict*(x.albumBoost===s.week?1.15:1));if(x.songRules===2&&Math.random()<(.005+level('viralAbility')*.00045)*directionFor(x).viral){n=Math.round(n*rand(1.8,3.5));log('“'+x.title+'” caught a viral discovery wave.')} }n=adjustReleaseStreams(x,n);if(x.released===s.week){x.debutStreams=n;x.breakdown+=' Genre fit '+x.marketFit+'%; release spacing '+Math.round(x.rolloutFactor*100)+'%.'}x.streams=n;x.total+=n;count+=n;added+=Math.round(n*directionFor(x).fans*(1+s.loyalty/200)*(x.songRules===2?.75+level('charisma')*.005:1))});settleAlbumSales();worldWeek();settleLabelWeek();s.chartWeek=s.week;for(const a of s.albums)if(a.debutStreams===undefined&&a.week===s.week)a.debutStreams=albumStreams(a);let rankings=compileSongs();updateChartRecords(rankings);rankings.forEach((x,i)=>{if(x.you){let track=s.songs.find(y=>y.id===x.id);track.peak=Math.min(track.peak||Infinity,i+1)}});s.streams=count;s.total+=count;added=settleAudience(count,added);s.fans=Math.max(0,s.fans+added);let royalties=Math.round(count*.50*100)/100;const financial=closeFinances(royalties,overheadRate);s.energy=clamp(s.energy+40);if(added>0)s.loyalty=clamp(s.loyalty+1);s.careerRecords.royalties+=royalties;s.lastReport={cashChange:financial.net,finance:financial,streams:count,fans:added,royalties,debut:debut.map(x=>x.id)};finishCareerWeek();let completed=s.week;const earned=scanAchievements();catalogReport(completed);weeklyNews(completed);s.week++;s.ap=6;s.boost=0;log(count?compact(count)+' streams, '+fmt(added)+' net fans, and '+money(royalties)+' in royalties.':'A fresh week. New records are dropping around you.');if(s.cash<0)log('Your balance is below zero. Work shifts can cover the shortfall.');render();weekRecap(completed,count,added,debut,financial,earned)}
function reach(track){let guest=track.feature?s.world[track.feature.id]:null;let featureReach=guest?track.feature.fans*(guest.relation<=-40?.004:.018)*(guest.genre===s.genre?1:.8):0;return Math.round(180+s.fans*.9+featureReach)}
function nextStep(){let heading,text,button,handler;
if(!s.started){heading='Start with one record';text='Create your artist, then write, record, mix, and release a single. Each week gives you six time slots.';button='Create artist';handler='setup()'}
else if(s.cash<0){heading='Give yourself some runway';text='A work shift earns $180 before taxes and can help cover career expenses, even when your balance is negative.';button='Work a shift';handler="action('work')"}
else if(s.energy<15){heading='Take a breather';text='Rest restores 30 energy for one time slot. A new week restores up to 40 energy.';button='Rest';handler="action('rest')"}
else if(s.draft){heading=['','Put down the vocals','Give it a final mix','Your record is ready'][s.draft.steps];text=s.draft.steps===3?'Release it now for $20 or save it for an album.':'You can pause a project and continue next week. Your work stays in the studio.';button='Continue record';handler="go('Studio')"}
else if(!s.songs.some(x=>x.released)){heading='Make your first single';text='Budget $90 and four time slots to go from idea to release. You can work on it over more than one week.';button='Open studio';handler="go('Studio')"}
else if(s.songs.some(x=>x.released&&x.factor===undefined)){heading='Your debut is on the way';text='Advance the week to see the results. If you still have time, practice, rest, or work a shift.';button='Review releases';handler="go('Career')"}
else if(s.week<=8){heading='Build a rhythm that works';text='Work covers bills. Practice improves future records. Open mics grow your first audience. You don’t need a feature or an album yet.';button='Review your results';handler="go('Career')"}
else return '';
return `<section class="card guide"><div><span class="eyebrow">Your next step</span><h3>${heading}</h3><p>${text}</p></div><button class="secondary" onclick="${handler}">${button}</button></section>`}

function exactCash(n){return Math.abs(n)>=1e6?currencyLabel(n,true):new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n)}
function homeStats(){let report=s.lastReport;return `<section class="home-dashboard" aria-label="Career overview"><div class="overview-numbers">${[
['cash','Cash',s.cash<0?'−$'+compact(-s.cash):'$'+compact(s.cash),s.cash<0?'Balance below zero':'Available to spend',s.cash<0],
['fans','True fans',compact(s.fans),report?'+'+fmt(report.fans)+' last week':'Building your audience',false],
['streams','Streams',compact(s.streams),s.week>1?'Week '+(s.week-1)+' results':'First results pending',false]
].map(([key,label,value,note,low])=>`<button class="overview-stat ${low?'overview-low':''}" onclick="statDetail('${key}')" aria-label="${label}: ${key==='cash'?exactCash(s.cash):fmt(key==='fans'?s.fans:s.streams)}. View details"><span class="overview-label">${label}</span><strong>${value}</strong><span class="overview-note">${note}</span></button>`).join('')}</div><div class="overview-resources"><button onclick="statDetail('energy')" class="resource-item ${s.energy<20?'overview-low':''}"><span>Energy <strong>${s.energy}/100</strong></span><span class="resource-meter" aria-hidden="true"><i style="width:${s.energy}%"></i></span></button><button onclick="statDetail('time')" class="resource-item"><span>Time left <strong>${s.ap}/6 slots</strong></span><span class="time-slots" aria-hidden="true">${Array.from({length:6},(_,i)=>`<i class="${i<s.ap?'filled':''}"></i>`).join('')}</span></button></div><div class="overview-caption">Tap a stat for the full breakdown</div></section>`}
function statDetail(key){let r=s.lastReport;let titles={cash:'Your cash',fans:'Your audience',streams:'Your streams',energy:'Your energy',time:'Your week'};let rows,description;
if(key==='cash'){rows=[['Available balance',exactWallet()],['Tax reserve (separate)',exactCash(s.finance.reserve)],['Last week’s royalties',r?exactCash(r.royalties):'No results yet'],['Current royalty rate','$0.50 per stream'],['Work shift income','$180.00']];description='Available cash includes your actions so far. Royalties are streaming income only, not total weekly profit. Large denominations: M million, B billion, T trillion, Qa quadrillion, Qi quintillion. Cash debits and credits are kept in an exact cents ledger. Large stream totals and calculated revenue are still simulation estimates.'}
if(key==='fans'){rows=[['True fans',fmt(s.fans)],['Net fans from last week’s streams',r?(r.fans>=0?'+':'')+fmt(r.fans):'No results yet'],['Estimated weekly listeners',compact(s.expansion.listeners)],['Fans lost last week',fmt(s.expansion.lastAudience?.churn||0)],['Career tier',tierNames[tier(s.fans)]],['Fan loyalty',s.loyalty+'/100']];description='Fans are people who support your artist. Streams count plays, so one fan can generate more than one stream. Open-mic fans join immediately; the weekly figure is new streaming fans minus audience churn. Release spacing, catalog size, and loyalty affect audience growth.'}
if(key==='streams'){rows=[['Last completed week',s.week>1?'Week '+(s.week-1):'None yet'],['Streams that week',fmt(s.streams)],['Lifetime streams',fmt(s.total)],['Released tracks',fmt(s.songs.filter(x=>x.released).length)],['Campaign this week',s.boost>0?'+'+Math.round(s.boost*100)+'% streaming boost':'No campaign']];description='Streams update after you advance the week. These totals combine all your released tracks. Album tracks are counted once.'}
if(key==='energy'){rows=[['Energy available',s.energy+'/100'],['Rest action','+30 · 1 time slot'],['New week recovery','Up to +40'],['Writing / recording / mixing','−10 / −15 / −15']];description='Energy limits how much work you can take on. Rest can restore energy now; recovery cannot take you above 100.'}
if(key==='time'){rows=[['Time available',s.ap+' of 6 slots'],['Slots already used',6-s.ap],['New week','6 fresh slots'],['Unused slots','Do not carry over']];description='Most actions take one slot. Making and releasing a single takes four in total, which you can spread across weeks. Advancing the week charges career overhead and sets aside income taxes.'}
modal(`<div class="eyebrow">Career overview</div><h2>${titles[key]}</h2>${rows.map(([label,value])=>`<div class="row"><span>${label}</span><strong>${value}</strong></div>`).join('')}<p>${description}</p>`)}


function metricRail(items){return `<div class="metric-rail">${items.map(([l,v])=>`<div><span>${l}</span><strong>${v}</strong></div>`).join('')}</div>`}
function saveStatus(message,error=false){let el=$('save-status');el.textContent=message;el.className='save-status'+(error?' error':'')}
function queueSave(){if(!saveReady||saveConflict||JSON.stringify(s)===lastSaved)return;checkpointCareer();saveStatus('Unsaved changes');clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,250)}
async function saveNow(){if(OFFLINE)return saveLocal();clearTimeout(saveTimer);if(!saveReady||saveConflict||saveBusy)return;checkpointCareer();const snapshot=JSON.stringify(s);if(snapshot===lastSaved){saveStatus('Career saved ✓');return}saveBusy=true;saveStatus('Saving…');try{let response=await fetch(SAVE_URL,{method:'PUT',headers:{'Content-Type':'application/json',...(saveEtag?{'If-Match':saveEtag}:{'If-None-Match':'*'})},body:JSON.stringify({schemaVersion:1,state:JSON.parse(snapshot)}),keepalive:snapshot.length<55000});if(response.status===409){saveConflict=true;throw Error('A different tab saved this career. Reload to continue.')}if(!response.ok)throw Error('Save failed. Keep this tab open and tap Retry save.');let result=await response.json();saveEtag=result.etag;lastSaved=snapshot;checkpointCareer();saveStatus('Career saved ✓')}catch(e){saveStatus(saveConflict?'Other tab saved · reload':'Retry save',true);toast(e.message)}finally{saveBusy=false;if(!saveConflict&&lastSaved===snapshot&&JSON.stringify(s)!==lastSaved)queueSave()}}
async function boot(){titleVisible=true;renderTitle();if(OFFLINE){await bootLocal();prepareOffline();return}saveStatus('Loading career…');try{let response=await fetch(SAVE_URL,{cache:'no-store'});if(!response.ok)throw Error('Your saved career could not be loaded.');let data=await response.json();if(data.save){if(data.save.schemaVersion!==1)throw Error('This career needs a newer game version. Reload to update.');let loaded=data.save.state;if(!loaded||!Array.isArray(loaded.world)||!Number.isFinite(loaded.week))throw Error('The saved career could not be read.');if(!!loaded.sandbox!==SANDBOX)throw Error('This save belongs to a different game mode.');s=loaded;lastSaved=JSON.stringify(s);migrateCharts();migratePacing();migrateDevelopment();migrateCareerRecords();migrateFinance();migrateChartBook();migrateAchievements()}saveEtag=data.etag;recoverPendingCareer(data);saveReady=true;$('save-status').onclick=saveNow;render();showTitle();if(lastSaved===JSON.stringify(s))saveStatus('Career restored ✓');else await saveNow()}catch(e){saveReady=false;titleVisible=false;renderTitle();saveStatus('Retry loading',true);$('save-status').onclick=boot;$('app').innerHTML=`<section class="card"><h2>Let’s protect your progress.</h2><p>${esc(e.message)} Your existing save has not been replaced.</p><button class="primary" onclick="boot()">Try again</button></section>`}}
async function newCareer(){if(saveBusy){toast('Wait for the current save to finish.');return}if(saveConflict){toast('Reload this tab before starting a new career.');return}if(!backupCareer(true))return;s=fresh();tab='Home';$('modal').close();render();await saveNow();showTitle()}
window.addEventListener('beforeunload',e=>{if(saveReady&&JSON.stringify(s)!==lastSaved){e.preventDefault();e.returnValue=''}});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')saveNow()});
function migratePacing(){if(s.pacingVersion===1)return;s.ap=Math.min(6,Math.max(0,s.ap)+2);s.pacingVersion=1;log('Update: six slots per week, +40 weekly energy, and $0.50 per future stream. Two extra slots added this week.');}
const developmentInfo={writing:['Writing','Lyrics, hooks and song structure.','Freestyle writing','Songwriting session','Intensive workshop'],recording:['Recording','Vocal execution, delivery and studio performance.','Vocal warm-up','Recording session','Vocal masterclass'],producing:['Producing','Beats, arrangement and mixing instincts.','Beat sketch','Production session','Production workshop'],charisma:['Charisma','Interviews, personality and turning listeners into fans.','Interview practice','Fan connection session','Media workshop'],marketability:['Marketability','Turn attention into fans, streams, tickets and opportunities.','Brand exercise','Campaign planning','Artist branding workshop'],stagePresence:['Stage Presence','Improves live fan conversion and performance reviews.','Stage rehearsal','Performance practice','Live masterclass'],touring:['Touring','Reduces local-run energy needs and improves live earnings.','Route planning','Show logistics','Tour management workshop'],viralAbility:['Viral Ability','Strengthens promotion and the chance of catalog discovery waves.','Trend study','Content session','Social campaign workshop']};
const coreStats=['writing','recording','producing','charisma','marketability'];
function initialDevelopment(craft=0,stage=0,other=0){return Object.fromEntries(['writing','recording','producing','charisma','marketability','stagePresence','touring','viralAbility'].map(k=>[k,{level:['writing','recording','producing'].includes(k)?craft:k==='stagePresence'?stage:other,xp:0}]))}
function migrateDevelopment(){if(s.developmentVersion===1)return;s.development=initialDevelopment(s.skill??35,s.stage??25,25);s.developmentVersion=1;log('Artist development unlocked. Your Craft became Writing, Recording and Producing; Stage Presence was preserved. Existing records keep their quality and results.')}
function level(k){return s.development[k].level}
function xpNeeded(n){return Math.round(60+n*3+(n>25?(n-25)*3:0)+(n>50?(n-50)*12:0)+(n>70?(n-70)**2*12:0)+(n>85?(n-85)**3*8:0))}
function difficulty(n){return n<=25?'Easy':n<=50?'Moderate':n<=70?'Hard':n<=85?'Very hard':n<=95?'Elite':'Generational'}
function gainXP(k,amount){let a=s.development[k];if(a.level>=100)return; a.xp+=amount;while(a.level<100&&a.xp>=xpNeeded(a.level)){a.xp-=xpNeeded(a.level);a.level++}if(a.level===100)a.xp=0}
function campaignBoost(){return .2+level('marketability')*.003+level('viralAbility')*.001}
function scoreSong(d){const v=k=>d.development[k].level;let w=directionFor(d).weights;d.quality=Math.round(clamp(coreStats.reduce((n,k,i)=>n+v(k)*w[i],0)+d.variation+Math.min(d.productionBonus||0,3+v('producing')*.08)));d.commercial=Math.round(clamp(d.quality*.55+v('marketability')*.25+v('charisma')*.1+v('viralAbility')*.1+d.appeal+directionFor(d).appeal))}
function statCard(k,sub=false){let a=s.development[k],info=developmentInfo[k];return `<section class="${sub?'substat':'card development-card'}"><div class="sectionhead"><h2>${info[0]}</h2><span class="training-score">${a.level}<small>/100</small></span></div><div class="bar" role="progressbar" aria-label="${info[0]} level" aria-valuenow="${a.level}" aria-valuemin="0" aria-valuemax="100"><i style="width:${a.level}%"></i></div><p>${info[1]}</p><div class="development-footer"><span class="fine">${a.level===100?'Maximum reached':difficulty(a.level)+' · '+fmt(a.xp)+' / '+fmt(xpNeeded(a.level))+' XP'}</span><button class="secondary" onclick="trainingDetail('${k}')">${a.level===100?'View mastery':'Train →'}</button></div>${k==='marketability'?`<details class="market-details"><summary>Performance & discovery · Details</summary><p class="fine">These abilities train independently. They do not replace or automatically increase Marketability.</p>${['stagePresence','touring','viralAbility'].map(x=>statCard(x,true)).join('')}<p class="fine">Festival opportunities and larger venue progression will come with expanded touring.</p></details>`:''}</section>`}
function training(){return head('Artist development','Stats.',`<span class="pill">⚡ ${s.energy}/100</span>`)+`<p class="development-intro">Five independent abilities. Build your sound, your presence, and your audience.</p><div class="development-stack">${coreStats.map(k=>statCard(k)).join('')}<section class="card training-rest"><div><h3>Recover & return</h3><p class="fine">Training uses energy only. Rest restores up to 30 energy for 1 time slot; a new week restores 40.</p></div><button class="secondary" ${s.energy>=100||s.ap<1?'disabled':''} onclick="action('rest')">Rest · +${Math.min(30,100-s.energy)} energy</button></section><details class="card"><summary>How development affects your music</summary><p>Standard quality: Writing 30%, Recording 30%, Producing 25%, Charisma 5%, Marketability 10%. Personal songs emphasize Writing; experimental songs emphasize Producing.</p><p>Commercial potential: Quality 55%, Marketability 25%, Charisma 10%, Viral Ability 10%, plus song-specific appeal. Creative execution varies. Audience reception and discovery still decide whether a release catches on.</p><p>Writing is captured when you start; Recording and Charisma at recording; Producing, Marketability and Viral Ability at mixing. Training never rewrites finished records.</p><p>Higher levels cost progressively more XP. Reaching 99–100 takes sustained development over years, even with intensive training.</p></details></div>`}
function trainingDetail(k){if(!developmentInfo[k])return;let a=s.development[k],info=developmentInfo[k];modal(`<div class="eyebrow">Artist development · ${difficulty(a.level)}</div><h2>${info[0]}</h2><div class="training-score">${a.level}<small> / 100</small></div><p>${info[1]}</p><div class="bar"><i style="width:${a.level===100?100:a.xp/xpNeeded(a.level)*100}%"></i></div><p>${a.level===100?'Generational mastery':`Next level: ${a.level} → ${a.level+1} · ${fmt(a.xp)} / ${fmt(xpNeeded(a.level))} XP`}</p><p class="fine">⚡ ${s.energy} energy available · No time slot or cash cost</p><div class="training-options">${[5,10,20].map((cost,i)=>`<button class="training-option" ${a.level>=100||s.energy<cost?'disabled':''} onclick="trainStat('${k}',${i})"><strong>${info[i+2]}</strong><span>+${[20,40,80][i]} XP · ⚡ ${cost}</span></button>`).join('')}</div><p class="fine">XP carries toward the next level. Elite levels need substantially more sessions.</p>`)}
function trainStat(k,i){if(!saveReady||saveConflict||!developmentInfo[k]||![0,1,2].includes(i))return;let cost=[5,10,20][i];if(level(k)>=100||s.energy<cost)return;s.started=true;s.energy-=cost;let before=level(k);gainXP(k,[20,40,80][i]);log(developmentInfo[k][0]+': +'+[20,40,80][i]+' XP'+(level(k)>before?' · Level '+level(k):'')+'.');render();trainingDetail(k)}
function tourEnergy(){return Math.round(45-level('touring')*.2)}
function tourGross(){return Math.round(100+Math.min(s.fans,5000)*.035+level('touring')*1.2+level('marketability')*.8)}
function legacyPlayTour(confirmed=false){if(s.fans<250){toast('Build an audience of 250 fans first.');return}if(s.ap<2){toast('A local run needs two time slots.');return}let energy=tourEnergy(),gross=tourGross();if(!confirmed){modal(`<h2>Book this local run?</h2><p>Three shows use 2 time slots and ${energy} energy. Pay $100 upfront; gross earnings are ${money(gross)}, for ${money(gross-100)} before weekly overhead and income tax.</p><div class="controls"><button class="secondary" onclick="$('modal').close()">Keep planning</button><button class="primary" onclick="$('modal').close();playTour(true)">Confirm local run</button></div>`);return}if(!spend(energy,100))return;s.ap--;changeCash(gross);recordIncome('live',gross);let fans=Math.round(15+level('stagePresence')*.6+level('charisma')*.2);s.fans+=fans;let review=clamp(Math.round(level('stagePresence')*.7+level('charisma')*.3+rand(-10,10)));if(review>=70)s.reputation=clamp(s.reputation+1);s.careerRecords.liveGross+=gross;s.careerRecords.liveProfit+=gross-100;s.careerRecords.tours.push({week:s.week,title:'Local run '+(s.careerRecords.tours.length+1),gross,profit:gross-100,fans,review});gainXP('touring',60);gainXP('stagePresence',40);log('Local run: '+money(gross-100)+' profit, '+fans+' fans, '+review+'/100 live review. +60 Touring XP, +40 Stage Presence XP.');render();toast('Run complete: '+money(gross-100)+' profit · '+fans+' fans · Review '+review+'/100')}

function fresh(){const state=baseFresh();if(!SANDBOX)return state;state.sandbox=true;state.achievements.baselinePending=true;state.started=true;state.name='Solace';state.cash=1000000000;state.fans=200000000;state.energy=100;state.skill=100;state.stage=100;state.reputation=100;state.loyalty=100;Object.values(state.development).forEach(a=>{a.level=100;a.xp=0});state.world.forEach(a=>{a.relation=100});state.history=[{week:1,text:'Sandbox opened: max abilities, $1 billion, 200 million fans and maximum relationships. Separate save from your normal career.'}];state.songs=['The World Is Listening','After the Spotlight','Encore Forever'].map((title,i)=>({id:90001+i,title,mood:['Catchy / radio-ready','Personal / storytelling','Raw / experimental'][i],steps:3,quality:100,commercial:100,songRules:2,released:1,streams:0,total:0,peak:null,album:null,feature:null}));return state}
function sandboxBar(){return SANDBOX?`<aside class="sandbox-banner"><div><strong>ENCORE LAB · SANDBOX</strong><p>Separate test save · Results here never enter your normal career.</p></div><div class="controls"><button class="secondary" onclick="refillSandbox()">Refill resources</button><button class="primary" onclick="sandboxEditor()">Edit sandbox</button><a class="secondary" href="${OFFLINE?'/offline':'/'}">Normal game</a></div></aside>`:''}
function refillSandbox(){if(!SANDBOX||!saveReady||saveConflict)return;changeCash(Math.max(0,1000000000-s.cash));s.energy=100;s.ap=6;log('Sandbox resources refilled: cash, energy and time slots.');render();toast('Resources refilled. Advance the week whenever you want release results.')}
function migrateCareerRecords(){if(s.careerRecords)return;s.careerRecords={sinceWeek:s.week,tours:[],openMics:0,royalties:0,liveGross:0,liveProfit:0};}

function profileRows(rows){return `<dl class="profile-facts">${rows.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`}
function careerProfile(){const released=s.songs.filter(x=>x.released),records=s.careerRecords,certifiedSongs=released.filter(x=>certificationUnits(x,'songs')>=500000),certifiedAlbums=s.albums.filter(x=>certificationUnits(x,'albums')>=500000),songOnes=released.filter(x=>x.peak===1),albumOnes=s.albums.filter(x=>x.peak===1),bestSong=released.reduce((best,x)=>!best||x.total>best.total?x:best,null),bestAlbum=s.albums.reduce((best,x)=>!best||albumStreams(x,true)>albumStreams(best,true)?x:best,null),bestTour=records.tours.reduce((best,x)=>!best||x.gross>best.gross?x:best,null),report=s.finance.last,changed=report?.net;
const plaques=[...released.map(x=>({item:x,kind:'songs'})),...s.albums.map(x=>({item:x,kind:'albums'}))].filter(x=>certificationUnits(x.item,x.kind)>=500000).sort((a,b)=>certificationUnits(b.item,b.kind)-certificationUnits(a.item,a.kind));
return `<article class="career-profile editorial-profile"><div class="profile-masthead"><span>ENCORE</span><span>THE CAREER EDITION${SANDBOX?' · LAB':''}</span></div><div class="profile-body"><div class="profile-kicker"><span class="profile-monogram">E</span> THE ARTIST FILE · Year ${Math.floor((s.week-1)/52)+1}, Week ${(s.week-1)%52+1}</div><h1>${esc(s.name)}</h1><p class="profile-role">${esc(s.genre)} · ${esc(tierNames[tier(s.fans)])} · ${s.labelBusiness?.company?'Founder, '+esc(s.labelBusiness.company.name):s.expansion.contract?esc(s.expansion.contract.name):'Independent'}</p><div class="wealth-feature"><div><span class="profile-kicker">Spendable cash</span><strong>${money(s.cash)}</strong><p>${changed===undefined?'Your first financial report is ahead.':(changed>=0?'+':'−')+money(Math.abs(changed))+' net in the last completed week'}</p></div><div class="wealth-aside"><span>Tax reserve <b>${money(s.finance.reserve)}</b></span><span>Cash + reserve <b>${money(s.cash+s.finance.reserve)}</b></span><button class="secondary" onclick="careerTab='Finances';render()">Financial report</button></div></div><div class="profile-spotlights">${[['Lifetime streams',compact(s.total)],['True fans',compact(s.fans)],['#1 songs / albums',songOnes.length+' / '+albumOnes.length],['Certified releases',certifiedSongs.length+certifiedAlbums.length]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="profile-note">Financial figures reflect this career’s cash and tax reserve, not an estimated catalog valuation or real-world wealth ranking.</p><section class="editorial-section"><div class="sectionhead"><h2>The current chapter</h2><button class="secondary" onclick="industryTab='Charts';go('Industry')">Open charts</button></div>${profileRows([['Chart issue',s.chartBook.issuedWeek?'Week '+s.chartBook.issuedWeek:'First issue pending'],['Songs charting now',chart().filter(x=>x.you).length],['Albums charting now',albumChart().filter(x=>x.you).length],['Last week’s streams',fmt(s.streams)],['Reputation / fan loyalty',s.reputation+' / '+s.loyalty],['Career length',(s.week-1)+' completed weeks'],['Featured appearances',s.expansion.featureAppearances||0],['Award wins / nominations',(s.expansion.awardWins||0)+' / '+(s.expansion.awardNominations||0)],['Estimated weekly listeners',compact(s.expansion.listeners)],['Achievements unlocked',Object.keys(s.achievements.unlocked).length+' / '+achievementDefinitions().length]])}</section><section class="editorial-section"><div class="sectionhead"><h2>The discography</h2><button class="secondary" onclick="careerTab='Releases';render()">All releases</button></div>${profileRows([['Released songs / albums',released.length+' / '+s.albums.length],['Songs with guest artists',released.filter(x=>x.feature).length],['Most-streamed song',bestSong&&bestSong.total?bestSong.title+' · '+compact(bestSong.total)+' streams':'Awaiting release results'],['Most-streamed album',bestAlbum&&albumStreams(bestAlbum,true)?bestAlbum.title+' · '+compact(albumStreams(bestAlbum,true))+' streams':'Awaiting album results'],['Song chart entries',released.filter(x=>x.peak).length],['Album chart entries',s.albums.filter(x=>x.peak).length],['Longest song run at #1',Math.max(0,...released.map(x=>x.longestNumberOne||0))+' weeks'],['Longest album run at #1',Math.max(0,...s.albums.map(x=>x.longestNumberOne||0))+' weeks']])}</section><section class="editorial-section"><div class="sectionhead"><h2>The plaque collection</h2><button class="secondary" onclick="careerTab='Certifications';render()">View awards</button></div><p class="profile-note">${certifiedSongs.length} certified songs · ${certifiedAlbums.length} certified albums. Each release is counted once at its highest award.</p><div class="profile-plaques">${plaques.slice(0,4).map(({item,kind})=>`<button class="profile-plaque" onclick="releaseDetails('${kind}',${item.id})">${certBadge(item,kind)}<strong>${esc(item.title)}</strong><small>${kind==='songs'?'Song':'Album'} · ${compact(certificationUnits(item,kind))} units</small></button>`).join('')||'<p class="profile-note">Your first Gold record belongs here. Follow every release’s progress in Certifications.</p>'}</div></section><section class="editorial-section"><h2>On the road</h2>${profileRows([['Open mics / live runs',records.openMics+' / '+records.tours.length],['Highest-grossing run',bestTour?bestTour.title+' · '+money(bestTour.gross):'No completed runs'],['Best live review',records.tours.length?Math.max(...records.tours.map(x=>x.review))+' / 100':'—'],['Live gross / profit',money(records.liveGross)+' / '+money(records.liveProfit)],['Tracked streaming royalties',money(records.royalties)]])}</section><p class="profile-note">Live and earnings records tracked from Week ${records.sinceWeek}; detailed chart history from Week ${s.chartBook.sinceWeek}. Missing historical debuts are never invented. Certifications use saved lifetime streams and tracked album downloads.</p><div class="profile-footer"><button class="secondary" onclick="setup()">Edit artist</button><button class="secondary" onclick="go('Artist')">Career settings</button>${OFFLINE?'':'<a class="secondary" href="/offline">Play offline edition</a>'}${SANDBOX?`<button class="secondary" onclick="resetAsk()">Reset sandbox</button>`:`<a class="secondary" href="${OFFLINE?'/offline/sandbox':'/sandbox'}">Open sandbox</a>`}</div></div></article>`}

function career(){const nav=careerMenu();const extra={Touring:tourPage,Campaigns:marketingPage,Opportunities:opportunitiesPage,Labels:labelPage,Legacy:legacyPage,Saves:savesPage};if(extra[careerTab])return nav+extra[careerTab]();if(careerTab==='Achievements')return nav+achievementsPage();if(careerTab==='Certifications')return nav+certificationsPage();if(careerTab==='Finances')return nav+financeScreen();if(careerTab==='Releases')return nav+catalog();if(careerTab==='Activity')return nav+head('Your career, week by week','Activity.')+`<section class="card">${s.history.map(x=>`<div class="story"><small>WEEK ${x.week}</small>${esc(x.text)}</div>`).join('')}</section>`;return nav+careerProfile()}

const cents=n=>Math.round(n*100)/100;
function initialFinance(week=1){return {version:1,sinceWeek:week,year:Math.floor((week-1)/52)+1,livingRules:3,weeks:0,revenue:0,expenses:0,reserve:0,taxesPaid:0,week:{wages:0,live:0,expenses:0},last:null,lastSettlement:null}}
function migrateFinance(){if(!s.finance)s.finance=initialFinance(s.week);if(s.finance.livingRules!==3){delete s.finance.lifestyle;s.finance.livingRules=3;log('Living-cost charges removed. Career overhead and income taxes still apply.')}}
function operationRate(){return [0,.05,.08,.1,.12,.15,.18][tier(s.fans)]}
function taxDue(profit){let remaining=Math.max(0,profit),tax=0;for(const [width,rate] of [[15000,0],[35000,.1],[100000,.2],[350000,.3],[500000,.35],[Infinity,.4]]){let slice=Math.min(remaining,width);tax+=slice*rate;remaining-=slice;if(remaining<=0)break}return cents(tax)}
function recordIncome(kind,value){s.finance.week[kind]=cents(s.finance.week[kind]+value)}
function closeFinances(royalties,rate){const f=s.finance,w=f.week,labelCut=artistLabelCut(royalties),labelBusiness=w.labelBusiness||0,labelPayroll=w.labelPayroll||0,albumSales=w.albumSales||0,overhead=cents((royalties+w.live+albumSales)*rate),revenue=cents(royalties+w.live+w.wages+albumSales+labelBusiness),expenses=cents(w.expenses+overhead+labelCut);f.weeks++;f.revenue=cents(f.revenue+revenue);f.expenses=cents(f.expenses+expenses);const profit=cents(f.revenue-f.expenses),yearEnd=s.week%52===0,target=yearEnd?taxDue(profit):cents(taxDue(Math.max(0,profit)*52/f.weeks)*f.weeks/52),reserveChange=cents(target-f.reserve);f.reserve=target;changeCash(royalties-overhead-reserveChange-labelCut);const report={week:s.week,revenue,royalties,albumSales,labelBusiness,labelPayroll,labelCut,wages:w.wages,live:w.live,expenses,actionExpenses:w.expenses,overhead,rate,taxReserve:reserveChange,net:cents(revenue-expenses-reserveChange),cash:s.cash,yearEnd,settlement:yearEnd?target:0};if(yearEnd){f.lastSettlement={year:f.year,profit,tax:target,reconciliation:reserveChange};f.taxesPaid=cents(f.taxesPaid+target);f.reserve=0;f.year++;f.weeks=0;f.revenue=0;f.expenses=0}f.week={wages:0,live:0,expenses:0};f.last=report;return report}
function financeRows(r,full=false){const payout=cents(r.royalties+(r.albumSales||0)+(r.labelBusiness||0)-(r.labelPayroll||0)-(r.labelCut||0)-r.overhead-r.taxReserve);return [...(full?[['Total revenue',money(r.revenue)],['Work, advances & live income',money(r.wages+r.live)],['Action costs','−'+money(r.actionExpenses-(r.labelPayroll||0))]]:[]),['Streaming royalties',money(r.royalties)],['Album downloads',money(r.albumSales||0)],['Label-business receipts',money(r.labelBusiness||0)],['Label payroll','−'+money(r.labelPayroll||0)],['Your label contract share','−'+money(r.labelCut||0)],['Career overhead ('+Math.round(r.rate*100)+'%)','−'+money(r.overhead)],[r.taxReserve<0?'Tax reserve returned':'Tax reserve set aside',(r.taxReserve<0?'+':'−')+money(Math.abs(r.taxReserve))],[full?'Net for the whole week':'Week-close payout',money(full?r.net:payout)],['Spendable cash',money(r.cash)]]}

function financeScreen(){const f=s.finance,rate=operationRate();return head('Money in · Money out','Finances.')+metricRail([['Spendable cash',money(s.cash)],['Tax reserve',money(f.reserve)],['Income tax paid',money(f.taxesPaid)],['Career overhead',Math.round(rate*100)+'%']])+`<section class="card"><h2>Your career operation</h2><p>${tierNames[tier(s.fans)]}: <strong>${Math.round(rate*100)}% of streaming, album download and live revenue</strong> covers management, staff and security. Work shifts are exempt. No music income means no overhead.</p><p class="fine">The rate is set by your fan tier at the start of each week close. Unknown 0% · Emerging 5% · Breakout 8% · Star 10% · Superstar 12% · Global star 15% · Global icon 18%. Recording, releases, features, promotion, industry support and tour costs are separate expenses shown before purchase.</p></section><section class="card"><h2>Taxes · Year ${f.year}</h2>${profileRows([['Tracked revenue this year',money(f.revenue)],['Deductible career expenses',money(f.expenses)],['Taxable profit so far',money(Math.max(0,f.revenue-f.expenses))],['Reserved, not spendable',money(f.reserve)],['Tax paid since tracking began',money(f.taxesPaid)]])}<p>At each week close, we estimate annual profit from your tracked weeks and reserve the proportional tax. The reserve can decrease when earnings fall or expenses rise. At Week 52, actual annual profit determines the final bill; the reserve pays it, with any difference charged or returned.</p><details><summary>View game tax brackets</summary>${profileRows([['First $15,000','0%'],['$15,000–$50,000 portion','10%'],['$50,000–$150,000 portion','20%'],['$150,000–$500,000 portion','30%'],['$500,000–$1 million portion','35%'],['Above $1 million portion','40%']])}<p class="fine">Simplified fictional rules: wages and music earnings are income; career costs are deductible. Each rate applies only to its portion. Existing cash and sandbox grants are not income. Losses offset income within the tracked year; no loss carryforward.</p></details><p class="fine">Tracking began Week ${f.sinceWeek}. Earlier earnings and existing savings are not retroactively taxed. This week’s actions enter the annual totals at week close.</p>${f.lastSettlement?`<div class="highlightbox">Year ${f.lastSettlement.year} settled: ${money(f.lastSettlement.tax)} tax on ${money(Math.max(0,f.lastSettlement.profit))} profit. Paid from the reserve; no duplicate charge.</div>`:''}</section><section class="card"><h2>Last completed week</h2>${f.last?financeRows(f.last,true).map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join(''):'<p>Advance a week to see the complete breakdown.</p>'}</section>`}

function localSaveKey(){return SANDBOX?'encore-offline-sandbox-v1':'encore-offline-v1'}
async function saveLocal(){if(!saveReady)return;try{localStorage.setItem(localSaveKey(),JSON.stringify({schemaVersion:1,state:s}));lastSaved=JSON.stringify(s);saveStatus('Saved on this device ✓')}catch{saveStatus('Device save failed · retry',true);toast('Storage is unavailable or full. Keep this game open until it saves.')}}
async function bootLocal(){titleVisible=true;renderTitle();try{const raw=localStorage.getItem(localSaveKey());if(raw){const data=JSON.parse(raw);if(data.schemaVersion!==1||!data.state||!Array.isArray(data.state.world)||!Number.isInteger(data.state.week)||!!data.state.sandbox!==SANDBOX)throw Error('This local career could not be read.');s=data.state;migrateCharts();migratePacing();migrateDevelopment();migrateCareerRecords();migrateFinance();migrateChartBook();migrateAchievements()}saveReady=true;render();showTitle();await saveLocal()}catch(e){saveReady=false;titleVisible=false;renderTitle();saveStatus('Local save unavailable',true);$('app').innerHTML='<section class="card"><h2>Cannot open your local career</h2><p>Your stored data has not been replaced. Try the same Safari browser outside private browsing.</p><button class="secondary" onclick="bootLocal()">Retry</button></section>'}}
let offlineReady=false;
function offlineBanner(){return OFFLINE?`<aside class="sandbox-banner"><div><strong>OFFLINE EDITION · ON-DEVICE SAVE</strong><p>Your online career stays separate. Clearing this site’s browser data removes this local save.</p><p id="offline-status">${offlineReady?'Ready for offline play.':'Preparing offline files—stay connected until ready.'}</p><p class="fine">On iPhone: Safari → Share → Add to Home Screen.</p></div><a class="secondary" href="/">Online game</a></aside>`:''}
async function prepareOffline(){if(!OFFLINE||!globalThis.navigator?.serviceWorker)return;try{await navigator.serviceWorker.register('/sw.js');const registration=await navigator.serviceWorker.ready;const worker=registration.active;if(!worker)throw Error('Not ready');const ready=await new Promise((resolve,reject)=>{const channel=new MessageChannel();const timer=setTimeout(()=>reject(Error('Offline check timed out')),15000);channel.port1.onmessage=e=>{clearTimeout(timer);resolve(e.data?.ready===true)};worker.postMessage({type:'CHECK_OFFLINE'},[channel.port2])});if(!ready)throw Error('Files unavailable');offlineReady=true;if($('offline-status'))$('offline-status').textContent='Ready for offline play.'}catch{if($('offline-status'))$('offline-status').textContent='Offline files are not ready. Reopen this page while connected and try again.'}}

function initialChartBook(){return {version:1,sinceWeek:1,issuedWeek:null,songs:{current:[],previous:[],records:{}},albums:{current:[],previous:[],records:{}}}}
function albumStreams(a,lifetime=false){return s.songs.filter(x=>a.tracks.includes(x.id)&&x.released).reduce((n,x)=>n+(lifetime?x.total:x.streams),0)}
function compileSongs(){return widerIndustry().concat(s.world.flatMap(a=>a.catalog.map((x,i)=>({...x,key:'npc:s:'+a.id+':'+(x.uid??i),artist:a.name,tier:tierNames[tier(a.fans)],releaseWeek:x.week})).filter(x=>x.type==='Single')),s.songs.filter(x=>x.released&&x.total>0).map(x=>({...x,key:'you:s:'+x.id,artist:s.name,tier:tierNames[tier(s.fans)],you:true,releaseWeek:x.released}))).filter(x=>x.streams>=CHART_FLOOR).sort((a,b)=>b.streams-a.streams||a.key.localeCompare(b.key)).slice(0,CHART_SIZE)}
function compileAlbums(){const week=s.chartWeek??1;const backdrop=Array.from({length:80},(_,i)=>{let era=Math.floor((week+i%16)/16);return {key:'bg:a:'+i+':'+era,title:titles.album[0][(i+era)%10]+' '+titles.album[1][(Math.floor(i/10)+era)%10],artist:seeds[i%seeds.length][0],releaseWeek:era*16-i%16,background:true,streams:Math.round((1200000+180000000*Math.pow(1-i/80,3))*(.8+.2*Math.sin(week*.4+i))),type:'Album'}});return backdrop.concat(s.world.flatMap(a=>a.catalog.map((x,i)=>({...x,key:'npc:a:'+a.id+':'+(x.uid??i),artist:a.name,releaseWeek:x.week,streams:x.streams+a.catalog.filter(t=>t.albumIndex===i).reduce((n,t)=>n+t.streams,0)})).filter(x=>x.type==='Album')),s.albums.filter(a=>a.week<=week&&(albumStreams(a)>0||a.weeklySales>0)).map(a=>({...a,key:'you:a:'+a.id,artist:s.name,releaseWeek:a.week,streams:albumStreams(a),total:albumStreams(a,true),type:'Album',you:true}))).map(x=>({...x,units:Math.floor(x.streams/1500)+(x.you?(x.weeklySales||0):0)})).filter(x=>x.units>=1000).sort((a,b)=>b.units-a.units||a.key.localeCompare(b.key)).slice(0,50)}
function chart(){return s.chartBook?.issuedWeek!==null&&s.chartBook?.issuedWeek!==undefined?s.chartBook.songs.current:compileSongs()}
function albumChart(){return s.chartBook?.issuedWeek!==null&&s.chartBook?.issuedWeek!==undefined?s.chartBook.albums.current:compileAlbums()}
function chartOwner(kind,id){return (kind==='songs'?s.songs:s.albums).find(x=>x.id===id)}
function chartRecord(kind,key){return s.chartBook?.[kind]?.records[key]??null}
function trackChartIssue(kind,list,baseline=false){const book=s.chartBook,board=book[kind],week=s.chartWeek;board.previous=baseline?[]:board.current;const prior=new Map(board.previous.map((x,i)=>[x.key,i+1]));const present=new Set(list.map(x=>x.key));board.current=list.map((x,i)=>{const rank=i+1,owner=x.you?chartOwner(kind,x.id):null;let record=board.records[x.key];const existed=!!record;let earlier=baseline||(!existed&&x.releaseWeek<book.sinceWeek);if(!record){record=board.records[x.key]={title:x.title,artist:x.artist,you:!!x.you,id:x.id??null,peak:owner?.peak??rank,weeks:baseline?(owner?.chartWeeks||0):owner?.chartWeeks||0,numberOneWeeks:owner?.numberOneWeeks||0,streak:owner?.numberOneStreak||0,longest:owner?.longestNumberOne||0,debutRank:earlier?null:rank,debutWeek:earlier?null:week,partial:earlier,history:[]}}
record.title=x.title;record.artist=x.artist;record.peak=Math.min(record.peak||rank,rank);record.lastSeen=week;record.lastRank=rank;if(!baseline){record.weeks++;record.streak=rank===1?record.streak+1:0;if(rank===1)record.numberOneWeeks++;record.longest=Math.max(record.longest,record.streak)}else record.weeks=Math.max(1,record.weeks);record.history.push({week,rank});record.history=record.history.slice(-104);if(owner){owner.peak=record.peak;owner.chartWeeks=record.weeks;owner.numberOneWeeks=record.numberOneWeeks;owner.numberOneStreak=record.streak;owner.longestNumberOne=record.longest}
const last=prior.get(x.key)??null;return {key:x.key,id:x.id??null,title:x.title,artist:x.artist,you:!!x.you,streams:x.streams,units:x.units??null,rank,last,peak:record.peak,weeks:record.weeks,debutRank:record.debutRank,debutWeek:record.debutWeek,partial:record.partial,movement:baseline?'BASE':last?(last===rank?'HOLD':last>rank?'UP':'DOWN'):existed?'RE':earlier?'ENTRY':'NEW'};});
for(const [key,record] of Object.entries(board.records)){if(!present.has(key)){if(record.lastRank!==null){record.history.push({week,rank:null});record.history=record.history.slice(-104)}record.lastRank=null;record.streak=0;const owner=record.you?chartOwner(kind,record.id):null;if(owner)owner.numberOneStreak=0;if(!record.you&&week-record.lastSeen>104)delete board.records[key]}}
}
function updateChartRecords(rankings){if(!s.chartBook)s.chartBook=initialChartBook();if(s.chartBook.issuedWeek===s.chartWeek)return;trackChartIssue('songs',rankings);trackChartIssue('albums',compileAlbums());s.chartBook.issuedWeek=s.chartWeek;updateCertifications()}
function migrateChartBook(){if(s.chartBook?.version===1)return;s.chartBook=initialChartBook();s.chartBook.sinceWeek=s.week;if(s.week>1){trackChartIssue('songs',compileSongs(),true);trackChartIssue('albums',compileAlbums(),true);s.chartBook.issuedWeek=s.chartWeek}for(const [kind,list] of [['songs',s.songs],['albums',s.albums]])for(const x of list){const key='you:'+(kind==='songs'?'s':'a')+':'+x.id;if((x.peak||x.chartWeeks)&&!s.chartBook[kind].records[key])s.chartBook[kind].records[key]={title:x.title,artist:s.name,you:true,id:x.id,peak:x.peak||null,weeks:x.chartWeeks||0,numberOneWeeks:x.numberOneWeeks||0,streak:0,longest:x.longestNumberOne||0,debutRank:null,debutWeek:null,partial:true,lastRank:null,lastSeen:s.chartWeek,history:[]}}updateCertifications(true)}
function certificationUnits(item,kind){return Math.floor((kind==='albums'?albumStreams(item,true):(item.total||0))/(kind==='albums'?1500:150))+(kind==='albums'?(item.sales||0):0)}
function certificationInfo(units){let milestone=units>=1e6?Math.floor(units/1e6)*1e6:units>=500000?500000:0;let next=milestone<500000?500000:milestone===500000?1e6:milestone+1e6;let tier=units>=1e7?'diamond':units>=2e6?'multi':units>=1e6?'platinum':units>=500000?'gold':'none';let label=tier==='diamond'?'Diamond · '+fmt(Math.floor(units/1e6))+'× Platinum':tier==='multi'?fmt(Math.floor(units/1e6))+'× Platinum':tier==='platinum'?'Platinum':tier==='gold'?'Gold':'Uncertified';return {milestone,next,tier,label,progress:clamp((units-milestone)/(next-milestone)*100)}}
function updateCertifications(recovered=false){for(const [kind,list] of [['songs',s.songs.filter(x=>x.released)],['albums',s.albums]])for(const item of list){const units=certificationUnits(item,kind),info=certificationInfo(units);if(info.milestone>(item.certification?.milestone||0)){item.certification={milestone:info.milestone,label:info.label,tier:info.tier,week:recovered?null:s.week,recovered,history:[...(item.certification?.history||[]),{label:info.label,week:recovered?null:s.week,units}].slice(-30)};if(!recovered){addBriefing('cert:'+kind+':'+item.id+':'+info.milestone,'Celebration',info.label+' certified','“'+item.title+'” reached '+fmt(units)+' equivalent units. Your '+(kind==='songs'?'song':'album')+' earned '+info.label+'.','Your award is saved in Career → Certifications.');log('“'+item.title+'” earned '+info.label+' '+(kind==='songs'?'song':'album')+' certification.')}}}}
function certBadge(item,kind){const c=certificationInfo(certificationUnits(item,kind));return `<span class="cert-badge cert-${c.tier}">${esc(c.label)}</span>`}
function certificationRules(){return `<details class="card cert-rules"><summary>How ENCORE certifications work</summary><p>Automatic game awards based on lifetime streams: 150 song streams = 1 song unit; 1,500 album-track streams = 1 album unit. Gold: 500,000 units. Platinum: 1 million. Multi-Platinum: each million above that. Diamond: 10 million units, with further million-unit milestones.</p><p>Song Gold requires 75 million streams; album Gold requires 750 million combined track streams. Albums include their member tracks’ lifetime streams, including pre-album singles, counted once per album. This adds no streams or royalties to your career total.</p><p class="fine">ENCORE uses worldwide simulated streams and one award system across genres. These are game achievements, not official RIAA certifications, audits or Billboard results.</p></details>`}
function certificationCard(item,kind){const units=certificationUnits(item,kind),c=certificationInfo(units);return `<section class="card certification-card"><div class="sectionhead"><span class="eyebrow">${kind==='songs'?'Song':'Album'}</span>${certBadge(item,kind)}</div><button class="release-link" onclick="releaseDetails('${kind}',${item.id})">${esc(item.title)}</button><p>${fmt(units)} equivalent units · ${compact(kind==='albums'?albumStreams(item,true):item.total)} streams</p><div class="bar"><i style="width:${c.progress}%"></i></div><div class="sectionhead fine"><span>${fmt(c.next-units)} units to next award</span><strong>${c.progress.toFixed(1)}%</strong></div><p class="fine">Next: ${esc(certificationInfo(c.next).label)}${item.certification?'<br>'+ (item.certification.recovered?'Current award recovered from saved totals':'Current award earned Week '+item.certification.week):''}</p></section>`}
function certificationsPage(){const list=certificateFilter==='Albums'?s.albums:s.songs.filter(x=>x.released),kind=certificateFilter==='Albums'?'albums':'songs';return head('Your catalog, recognized','Certifications.')+`<div class="chips">${['Songs','Albums'].map(t=>`<button class="${certificateFilter===t?'selected':''}" onclick="certificateFilter='${t}';render()">${t}</button>`).join('')}</div><div class="certification-grid">${list.length?list.slice().sort((a,b)=>certificationUnits(b,kind)-certificationUnits(a,kind)).map(x=>certificationCard(x,kind)).join(''):'<section class="card empty"><h2>Your first plaque starts with a release.</h2><p>Finish and release music to track its progress here.</p></section>'}</div>`+certificationRules()}
function movementLabel(x){if(x.movement==='NEW')return 'NEW';if(x.movement==='RE')return 'RE-ENTRY';if(x.movement==='ENTRY')return 'ENTRY';if(x.movement==='BASE')return '—';if(x.movement==='HOLD')return '—';return (x.movement==='UP'?'↑ ':'↓ ')+Math.abs(x.last-x.rank)}
function chartHub(){const kind=chartKind==='Albums'?'albums':'songs',list=kind==='songs'?chart():albumChart(),book=s.chartBook,board=book?.[kind],ready=book?.issuedWeek!==null&&book?.issuedWeek!==undefined,visible=chartMine?list.filter(x=>x.you):list,dropouts=ready?board.previous.filter(x=>!board.current.some(y=>y.key===x.key)):[];return head('The weekly issue',kind==='songs'?'Global Top 100.':'Global Albums 50.',`<span class="pill">${ready?'Week '+book.issuedWeek:'Preview'}</span>`)+`<div class="chart-toolbar"><div class="chips">${['Songs','Albums'].map(t=>`<button class="${chartKind===t?'selected':''}" onclick="chartKind='${t}';render()">${t}</button>`).join('')}</div><button class="secondary" aria-pressed="${chartMine}" onclick="chartMine=!chartMine;render()">${chartMine?'Show all artists':'My releases'}</button></div><div class="chart-summary"><div><span>Entries</span><strong>${list.length}</strong></div><div><span>New entries</span><strong>${list.filter(x=>x.movement==='NEW').length}</strong></div><div><span>Your entries</span><strong>${list.filter(x=>x.you).length}</strong></div><div><span>Entry cutoff</span><strong>${compact(list.at(-1)?.[kind==='songs'?'streams':'units']??(kind==='songs'?CHART_FLOOR:1000))}</strong></div></div><p class="fine">${kind==='songs'?'Weekly streams · Minimum 250,000 plays, plus a Top 100 rank.':'Weekly album units · 1,500 track streams = 1 unit. Minimum 1,000 units, plus a Top 50 rank.'} ${ready?'Movement compares the previous completed issue.':'Advance a week to publish the first issue.'}</p><div class="chart-list">${visible.map((x,index)=>`<article class="chart-entry ${x.you?'chart-you':''}"><div class="chart-place">${x.rank??list.indexOf(x)+1}<span class="movement movement-${x.movement||'BASE'}">${ready?movementLabel(x):'—'}</span></div><div class="chart-release"><button class="release-link" onclick="chartDetails('${kind}','${x.key}')">${esc(x.title)}</button><p>${esc(x.artist)}${x.you?' · YOU':''}</p>${x.you&&certificationUnits(chartOwner(kind,x.id),kind)>=500000?certBadge(chartOwner(kind,x.id),kind):''}<div class="chart-facts"><span>Last <b>${x.last?'#'+x.last:'—'}</b></span><span>Peak <b>${x.peak?'#'+x.peak:'—'}</b></span><span>Weeks <b>${x.weeks??'—'}${x.partial?'+':''}</b></span><span>Debut <b>${x.debutRank?'#'+x.debutRank:'—'}</b></span></div></div><div class="chart-volume"><strong>${compact(kind==='songs'?x.streams:x.units)}</strong><span>${kind==='songs'?'streams':'units'}</span></div></article>`).join('')||'<section class="card empty"><h2>No chart entries yet.</h2><p>Your releases need enough weekly activity to beat the competition.</p></section>'}</div>${dropouts.length?`<details class="card"><summary>Dropped out this week · ${dropouts.length}</summary>${dropouts.filter(x=>!chartMine||x.you).map(x=>`<div class="row"><button class="release-link" onclick="chartDetails('${kind}','${x.key}')">${esc(x.title)} · ${esc(x.artist)}</button><span class="fine">Last #${x.rank}</span></div>`).join('')||'<p>No releases of yours dropped out.</p>'}</details>`:''}<p class="fine">NEW = first chart entry. RE-ENTRY = returns after dropping out. ENTRY = first observed during tracking; original debut unknown. + = partial historical week count. Prior issue, debut and movement are unavailable for older data the game never recorded.</p>`}
function chartDetails(kind,key){const rec=chartRecord(kind,key),row=s.chartBook?.[kind].current.find(x=>x.key===key);if(!rec){modal('<h2>First issue pending</h2><p>Advance the week to start recording chart history.</p>');return}if(rec.you){releaseDetails(kind,rec.id);return}modal(`<div class="eyebrow">${kind==='songs'?'Song':'Album'} chart history</div><h2>${esc(rec.title)}</h2><p>${esc(rec.artist)}</p>`+chartRecordDetails(rec,row))}
function chartRecordDetails(rec,row){return profileRows([['Current position',row?'#'+row.rank:'Off chart'],['Last week',row?.last?'#'+row.last:'—'],['Peak',rec.peak?'#'+rec.peak:'Not recorded'],['Chart debut',rec.debutRank?'#'+rec.debutRank+' · Week '+rec.debutWeek:'Not recorded before tracking'],['Weeks charted',rec.weeks+(rec.partial?' (partial history)':'')],['Weeks at #1',rec.numberOneWeeks],['Longest #1 streak',rec.longest+' weeks']])+`<h3 style="margin-top:22px">Recent chart path</h3><div class="chart-path">${rec.history.slice(-12).map(p=>`<div><small>W${p.week}</small><strong>${p.rank?'#'+p.rank:'OUT'}</strong></div>`).join('')}</div><p class="fine">Recent recorded results shown. Full week counts and peak are kept; detailed history retains the latest 104 chart events.</p>`}
function releaseDetails(kind,id){const item=chartOwner(kind,id);if(!item)return;const key='you:'+(kind==='songs'?'s':'a')+':'+id,rec=chartRecord(kind,key),row=s.chartBook?.[kind].current.find(x=>x.key===key),units=certificationUnits(item,kind);modal(`<div class="eyebrow">${kind==='songs'?'Song':'Album'} · Released Week ${kind==='songs'?item.released:item.week}</div><h2>${esc(item.title)}</h2>${certBadge(item,kind)}${profileRows([['Lifetime streams',fmt(kind==='albums'?albumStreams(item,true):item.total)],['Certification units',fmt(units)],...(kind==='albums'?[['Album cohesion',(item.cohesion??'Not tracked')+'/100'],['Critical reception',(item.criticalReception??'Not tracked')+'/100']]:[['Lifecycle',item.lifecycle||'Awaiting debut'],['Genre fit this week',item.marketFit?item.marketFit+'%':'Pending']]),['Release debut streams',item.debutStreams!==undefined?fmt(item.debutStreams):'Not recorded / pending']])}${rec?chartRecordDetails(rec,row):'<p>No recorded chart entry yet.</p>'}${kind==='songs'?`<p class="fine">Quality ${item.quality}/100 · Commercial potential ${item.commercial??'—'}/100</p>`:''}${item.certification?`<h3>Award history</h3>${item.certification.history.map(h=>`<div class="row"><span>${esc(h.label)}</span><span class="fine">${h.week?'Week '+h.week:'Recovered from saved streams'}</span></div>`).join('')}`:'<p class="fine">Gold is the first certification at 500,000 equivalent units.</p>'}`)}

function initialAchievements(){return {version:1,unlocked:{},briefings:[],popups:true}}
function achievementDefinitions(){return [
{id:'first_lesson',title:'Find your voice',description:'Raise any development stat to level 1.',target:1,value:Math.max(...Object.values(s.development).map(x=>x.level)),group:'Development'},
{id:'craft25',title:'Putting in the work',description:'Reach level 25 in any development stat.',target:25,value:Math.max(...Object.values(s.development).map(x=>x.level)),group:'Development'},
{id:'mastery',title:'Generational talent',description:'Reach level 100 in any development stat.',target:100,value:Math.max(...Object.values(s.development).map(x=>x.level)),group:'Development'},
{id:'first_song',title:'The first record',description:'Release your first song.',target:1,value:s.songs.filter(x=>x.released).length,group:'Releases'},
{id:'ten_songs',title:'A catalog of your own',description:'Release ten songs.',target:10,value:s.songs.filter(x=>x.released).length,group:'Releases'},
{id:'first_album',title:'Your first era',description:'Release your first album.',target:1,value:s.albums.length,group:'Releases'},
{id:'feature',title:'Better together',description:'Release a song with a guest artist.',target:1,value:s.songs.filter(x=>x.released&&x.feature).length,group:'Releases'},
{id:'fans100',title:'The first hundred',description:'Build an audience of 100 true fans.',target:100,value:s.fans,group:'Audience'},
{id:'fans1k',title:'They know your name',description:'Reach 1,000 true fans.',target:1000,value:s.fans,group:'Audience'},
{id:'fans1m',title:'A million believers',description:'Reach one million true fans.',target:1e6,value:s.fans,group:'Audience'},
{id:'fans100m',title:'Global icon',description:'Reach 100 million true fans.',target:1e8,value:s.fans,group:'Audience'},
{id:'streams1m',title:'On repeat',description:'Earn one million lifetime streams.',target:1e6,value:s.total,group:'Audience'},
{id:'streams1b',title:'The billion club',description:'Earn one billion lifetime streams.',target:1e9,value:s.total,group:'Audience'},
{id:'chart',title:'On the board',description:'Land a song on the Global Top 100.',target:1,value:s.songs.filter(x=>x.peak).length,group:'Charts'},
{id:'song1',title:'Top of the world',description:'Reach number one on the song chart.',target:1,value:s.songs.filter(x=>x.peak===1).length,group:'Charts'},
{id:'album1',title:'An era at number one',description:'Reach number one on the album chart.',target:1,value:s.albums.filter(x=>x.peak===1).length,group:'Charts'},
{id:'gold',title:'Worth its weight',description:'Earn a Gold or higher song or album award.',target:500000,value:Math.max(0,...s.songs.filter(x=>x.released).map(x=>certificationUnits(x,'songs')),...s.albums.map(x=>certificationUnits(x,'albums'))),group:'Awards'},
{id:'platinum',title:'Platinum status',description:'Earn a Platinum or higher award.',target:1e6,value:Math.max(0,...s.songs.filter(x=>x.released).map(x=>certificationUnits(x,'songs')),...s.albums.map(x=>certificationUnits(x,'albums'))),group:'Awards'},
{id:'diamond',title:'Pressure made a diamond',description:'Earn a Diamond award.',target:1e7,value:Math.max(0,...s.songs.filter(x=>x.released).map(x=>certificationUnits(x,'songs')),...s.albums.map(x=>certificationUnits(x,'albums'))),group:'Awards'},
{id:'openmic',title:'Take the stage',description:'Perform your first open mic.',target:1,value:s.careerRecords.openMics,group:'Live'},
{id:'tour',title:'On the road',description:'Complete your first local run.',target:1,value:s.careerRecords.tours.length,group:'Live'}]}
function addBriefing(id,type,title,body,detail=''){if(!s.achievements)s.achievements=initialAchievements();if(s.achievements.briefings.some(x=>x.id===id))return;s.achievements.briefings.unshift({id,type,title,body,detail,week:s.week,read:id.startsWith('cert:')});s.achievements.briefings=s.achievements.briefings.slice(0,80)}
function scanAchievements(recovered=false){if(!s.achievements)s.achievements=initialAchievements();if(s.achievements.baselinePending){delete s.achievements.baselinePending;recovered=true}const earned=[];for(const a of achievementDefinitions()){if(a.value>=a.target&&!s.achievements.unlocked[a.id]){s.achievements.unlocked[a.id]={week:recovered?null:s.week,recovered};earned.push(a)}}if(earned.length&&!recovered)addBriefing('ach:'+earned.map(x=>x.id).join('-'),'Achievement',earned.length===1?earned[0].title:earned.length+' milestones unlocked',earned.map(x=>x.title+' — '+x.description).join('\n'),'Saved permanently in your achievement collection.');return earned}
function migrateAchievements(){if(s.achievements?.version===1)return;s.achievements=initialAchievements();scanAchievements(true)}
let briefingTimer;
function scheduleBriefing(){clearTimeout(briefingTimer);if(!saveReady||saveConflict||!s.achievements?.popups)return;briefingTimer=setTimeout(()=>{if(!titleVisible&&tourStep<0&&!$('modal').open){const next=s.achievements.briefings.find(x=>!x.read&&!x.id.startsWith('cert:'));if(next)showBriefing(next.id)}},120)}
function memoFrame(type,title,body,footer='',issueWeek=s.week){return `<article class="artist-memo"><div class="memo-tab">${esc(type)}</div><div class="memo-brand">ENCORE</div><div class="memo-subtitle">ARTIST RELATIONS · PRIVATE BRIEFING</div><dl class="memo-address"><div><dt>TO</dt><dd>${esc(s.name)}</dd></div><div><dt>FROM</dt><dd>${type==='Industry news'?'Industry Desk':type==='Weekly recap'?'Your Career Team':'Artist Relations'}</dd></div><div><dt>DATE</dt><dd>Year ${Math.floor((issueWeek-1)/52)+1} · Week ${(issueWeek-1)%52+1}</dd></div></dl><h2>${esc(title)}</h2>${body}<div class="memo-signoff">Your next chapter starts here.<strong>The ENCORE Team</strong></div>${footer}</article>`}
function showBriefing(id){if(!saveReady||saveConflict)return;const b=s.achievements?.briefings.find(x=>x.id===id);if(!b)return;b.read=true;modal(memoFrame(b.type,b.title,`<span class="memo-stamp">${esc(b.type==='Achievement'?'UNLOCKED':b.type==='Celebration'?'MILESTONE':'BRIEFED')}</span><p class="memo-copy">${b.id.startsWith('catalog:')?esc(b.body.split('\n\n')[0])+'</p><details><summary>All release records</summary><p class="memo-copy">'+esc(b.body.split('\n\n').slice(1).join('\n\n')).replaceAll('\n','<br>')+'</p></details><p>':esc(b.body).replaceAll('\n','<br><br>')}</p>${b.detail?`<p class="memo-note">${esc(b.detail)}</p>`:''}<p class="memo-note">Filed Week ${b.week}</p>`,`<button class="memo-primary" onclick="$('modal').close()">Continue career</button><button class="memo-secondary" onclick="$('modal').close();careerTab='Achievements';go('Career')">View achievements & briefings</button>`,b.week),'memo-dialog');queueSave()}
function catalogReport(completed){
const tracks=s.songs.filter(x=>x.released);if(!tracks.length)return;
for(const t of tracks){t.reportStreams=(t.reportStreams||[]).filter(x=>x.week>completed-4&&x.week!==completed);t.reportStreams.push({week:completed,streams:t.streams||0})}
if(completed%4!==0)return;
const from=completed-3,ranked=tracks.map(t=>({track:t,streams:t.reportStreams.filter(x=>x.week>=from).reduce((n,x)=>n+x.streams,0)})).sort((a,b)=>b.streams-a.streams);
const observed=Math.min(...tracks.flatMap(t=>t.reportStreams.map(x=>x.week))),top=ranked[0],total=ranked.reduce((n,x)=>n+x.streams,0);
const songLines=ranked.map(({track:t,streams})=>'“'+t.title+'” — '+compact(streams)+' streams · '+(chartPosition(t)?'Chart #'+chartPosition(t):'Uncharted')+(t.certification?' · '+t.certification.label:''));
const albumLines=s.albums.map(a=>{const streams=ranked.filter(x=>a.tracks.includes(x.track.id)).reduce((n,x)=>n+x.streams,0);return '“'+a.title+'” — '+compact(streams)+' track streams'+(a.certification?' · '+a.certification.label:'')});
const awards=[...tracks,...s.albums].flatMap(t=>(t.certification?.history||[]).filter(x=>x.week!==null&&x.week>=from&&x.week<=completed).map(x=>'“'+t.title+'” — '+x.label));
addBriefing('catalog:'+completed,'Music report','Your music · Weeks '+from+'–'+completed,
'Total song streams: '+compact(total)+'\nBiggest song: “'+top.track.title+'” · '+compact(top.streams)+' streams\n\nSONGS\n'+songLines.join('\n')+(albumLines.length?'\n\nALBUMS\n'+albumLines.join('\n'):'')+(awards.length?'\n\nNEW CERTIFICATIONS\n'+awards.join('\n'):''),
(observed>from?'Stream tracking started Week '+observed+'; earlier weeks are not included. ':'')+'Album streams are included in the song total, not added twice. Chart positions and awards are current at the end of Week '+completed+'. Your next music report arrives in four weeks.');
}
function weeklyNews(completed){const releases=s.feed.filter(x=>x.week===completed).sort((a,b)=>b.streams-a.streams);if(!releases.length)return;const lead=releases[0];addBriefing('news:'+completed,'Industry news',lead.name+' leads the release desk','“'+lead.title+'” arrived with '+compact(lead.streams)+' debut streams. '+(releases.length>1?(releases.length-1)+' other projects dropped this week.':'It was the week’s new industry release.'),'Open Industry → New releases to see who you are competing with.')}
function achievementsPage(){const defs=achievementDefinitions(),unlocked=Object.keys(s.achievements.unlocked).length,visible=defs.filter(a=>achievementFilter==='All'||(achievementFilter==='Unlocked'?!!s.achievements.unlocked[a.id]:!s.achievements.unlocked[a.id]));return head('The story you are building','Achievements.',`<span class="pill">${unlocked} / ${defs.length}</span>`)+`<div class="achievement-controls"><div class="chips">${['All','Unlocked','Locked'].map(t=>`<button class="${achievementFilter===t?'selected':''}" onclick="achievementFilter='${t}';render()">${t}</button>`).join('')}</div><button class="secondary" aria-pressed="${s.achievements.popups}" onclick="toggleBriefings()">Pop-ups: ${s.achievements.popups?'On':'Off'}</button></div><div class="achievement-stack">${visible.map(a=>{const earned=s.achievements.unlocked[a.id];return `<section class="card achievement-card ${earned?'earned':''}"><span class="achievement-mark">${earned?'✓':'○'}</span><div><span class="eyebrow">${esc(a.group)}</span><h2>${esc(a.title)}</h2><p>${esc(a.description)}</p><div class="bar"><i style="width:${earned?100:clamp(a.value/a.target*100)}%"></i></div><span class="fine">${earned?(earned.recovered?'Recovered from saved career · Original date unknown':'Unlocked Week '+earned.week):compact(Math.min(a.value,a.target))+' / '+compact(a.target)}</span></div></section>`}).join('')||'<section class="card"><p>No achievements in this view yet.</p></section>'}</div><section class="card"><div class="sectionhead"><h2>Briefing archive</h2><button class="secondary" onclick="readAllBriefings()">Mark all read</button></div><p class="fine">News, celebrations and milestones. Latest 80 briefings are kept; unlocked achievements are permanent.</p>${s.achievements.briefings.map(b=>`<button class="briefing-row" onclick="showBriefing('${b.id}')"><span><small>${esc(b.type)} · Week ${b.week}${b.read?'':' · NEW'}</small><strong>${esc(b.title)}</strong></span><span>Open</span></button>`).join('')||'<p>Your news and milestone letters will appear here.</p>'}</section>`}
function toggleBriefings(){if(!saveReady||saveConflict)return;s.achievements.popups=!s.achievements.popups;render()}
function readAllBriefings(){if(!saveReady||saveConflict)return;s.achievements.briefings.forEach(b=>b.read=true);render()}
function briefingShortcut(){const unread=s.achievements.briefings.filter(x=>!x.read&&!x.id.startsWith('cert:')).length;return `<button class="briefing-shortcut" onclick="careerTab='Achievements';go('Career')"><span><strong>Your achievements & briefings</strong><small>${Object.keys(s.achievements.unlocked).length} milestones unlocked${unread?' · '+unread+' unread':''}</small></span><span>Open</span></button>`}
function weekRecap(completed,count,added,debut,financial,earned=[]){const top=debut.slice().sort((a,b)=>b.streams-a.streams)[0];modal(memoFrame('Weekly recap','Week '+completed+' · Your career report',`<div class="memo-headline"><span>Streams this week</span><strong>${compact(count)}</strong><small>${added>=0?'+':''}${compact(added)} net fans</small></div><div class="memo-finances">${financeRows(financial).map(([k,v])=>`<div><span>${esc(k)}</span><strong>${esc(v)}</strong></div>`).join('')}</div>${earned.length?`<p class="memo-note">${earned.length} new achievements filed.</p>`:''}${financial.yearEnd?`<p class="memo-note">Tax year settled: ${money(financial.settlement)} paid from your reserve.</p>`:''}<p class="memo-note">Six time slots restored · Up to 40 energy recovered. ${s.feed.filter(x=>x.week===completed).length} industry projects released.</p>`,`<button class="memo-primary" onclick="$('modal').close()">Start week ${s.week}</button><button class="memo-secondary" onclick="$('modal').close();careerTab='Finances';go('Career')">Full financial report</button>`,completed),'memo-dialog');queueSave()}
$('modal').addEventListener?.('close',()=>{ if(!$('modal').open){$('modal').className='';scheduleBriefing()}});



/* Career progression: budgets, audiences, live shows, opportunities and contracts. */
const studioPackages=[{name:'Home studio',fee:0,quality:0},{name:'Professional studio',fee:1500,quality:5},{name:'Premium production',fee:25000,quality:9}];
const promotionPlans=[{name:'Grassroots',cost:50,boost:.18},{name:'Targeted campaign',cost:2500,boost:.4},{name:'National campaign',cost:50000,boost:.65}];
const venueTiers=[
{name:'Local rooms',fans:250,seats:300,ticket:8,cost:100},
{name:'Clubs',fans:5000,seats:1800,ticket:20,cost:12000},
{name:'Theaters',fans:50000,seats:9000,ticket:40,cost:140000},
{name:'Arenas',fans:500000,seats:45000,ticket:65,cost:1500000},
{name:'Stadiums',fans:5000000,seats:180000,ticket:100,cost:8500000}];
const labelDeals=[{name:'Boutique label',fans:1000,rep:15,advance:25000,share:.15,lift:.12},{name:'Major label',fans:250000,rep:45,advance:1500000,share:.3,lift:.28}];
function migrateExpansion(){if(!s.expansion)s.expansion={version:1,sinceWeek:s.week,listeners:0,inactive:0,timeline:[],opportunities:[],awards:[],albumRollout:null,contract:null,contractHistory:[],campaignWeek:0,tourWeek:0,careerPeakFans:s.fans};if(!s.walletCents)s.walletCents=decimalCents(s.cash).toString();for(const a of s.world){let next=a.nextCatalogId??(Math.max(-1,...a.catalog.map(x=>x.uid??-1))+1);for(const x of a.catalog)if(x.uid===undefined)x.uid=next++;a.nextCatalogId=next}}
function decimalCents(value){const str=String(value),m=str.match(/^(-?)(\d+)(?:\.(\d+))?(?:e([+-]?\d+))?$/i);if(!m)throw Error('Invalid money amount');let digits=BigInt(m[2]+(m[3]||'')),shift=2+Number(m[4]||0)-(m[3]||'').length;if(shift>=0)digits*=10n**BigInt(shift);else{const divisor=10n**BigInt(-shift);digits=(digits+divisor/2n)/divisor}return m[1]?-digits:digits}
function changeCash(delta){if(!s.walletCents||Number(BigInt(s.walletCents))/100!==s.cash)s.walletCents=decimalCents(s.cash).toString();s.walletCents=(BigInt(s.walletCents)+decimalCents(delta)).toString();s.cash=Number(BigInt(s.walletCents))/100;return s.cash}
function exactWallet(){migrateExpansion();const n=BigInt(s.walletCents),a=n<0n?-n:n;return (n<0n?'−':'')+'$'+(a/100n).toLocaleString('en-US')+'.'+String(a%100n).padStart(2,'0')}
function milestone(id,title,detail=''){if(s.expansion.timeline.some(x=>x.id===id))return;s.expansion.timeline.push({id,title,detail,week:s.week});s.expansion.timeline=s.expansion.timeline.slice(-200)}
function logCareerMilestones(){const released=s.songs.filter(x=>x.released);if(released.length)milestone('first-release','First release',released[0].title);if(s.songs.some(x=>x.peak))milestone('first-chart','First chart entry');if(s.songs.some(x=>x.certification))milestone('first-cert','First certified record');for(let i=1;i<thresholds.length;i++)if(s.fans>=thresholds[i])milestone('tier-'+i,tierNames[i]+' era',compact(s.fans)+' fans');s.expansion.careerPeakFans=Math.max(s.expansion.careerPeakFans,s.fans)}
function genreFit(track){const index=genres.indexOf(track.genre||s.genre);return .92+.16*(.5+.5*Math.sin(Math.floor(s.week/8)*.65+index*1.7))}
function adjustReleaseStreams(track,n){const age=s.week-track.released;const stage=age<2?'Discovery':age<8?'Peak window':age<26?'Catalog':'Legacy';track.lifecycle=stage;const recent=s.songs.filter(x=>x.released&&s.week-x.released<4).length;const fatigue=1/(1+Math.max(0,recent-2)*.08);const album=s.albums.find(a=>a.id===track.album);const albumLift=album&&s.week-album.week<4?1+(album.cohesion||0)/1000:1;const factor=genreFit(track)*fatigue*albumLift*(1+trackMarketingBoost(track))*(age>52?.97:1);n=Math.max(0,Math.round(n*factor));track.marketFit=Math.round(genreFit(track)*100);track.rolloutFactor=fatigue;return n}
function settleAudience(streams,raw){const released=s.songs.filter(x=>x.released),recent=released.some(x=>s.week-x.released<8),old=s.fans;const listeners=Math.round(streams/(2.5+Math.min(5,released.length*.12)));s.expansion.listeners=listeners;const available=Math.max(0,listeners-old*.25);const acquired=Math.round(Math.min(raw/Math.sqrt(1+Math.max(0,released.length-3)*.18),available*.05));const churn=Math.round(old*(recent?.0005:.0025)*(1-s.loyalty/150));s.expansion.inactive+=churn;s.expansion.lastAudience={acquired,churn,listeners};return acquired-churn}
function beginCareerWeek(){migrateExpansion();migrateExperience();backupCareer(false);prepareLabelWeek();resolveMarketing();const e=s.expansion;if(e.contract&&s.week<=e.contract.ends)s.boost+=e.contract.lift;if(e.albumRollout){const r=e.albumRollout;if(s.week<=r.until){const song=s.songs.find(x=>x.id===r.lead);if(song)s.boost+=r.boost}else{e.albumRollout=null;log('Your album campaign has ended.')}}}
function finishCareerWeek(){const e=s.expansion;if(e.albumRollout&&e.albumRollout.until<=s.week)e.albumRollout=null;logCareerMilestones();scoutLabels();if(e.contract&&s.week>=e.contract.ends){e.contractHistory.unshift({...e.contract,ended:s.week});e.contractHistory=e.contractHistory.slice(0,20);milestone('label-'+e.contract.started,'Contract completed',e.contract.name);log(e.contract.name+' contract ended. Your artist income returns to your independent career.');e.contract=null}if(s.week%4===0)createOpportunity();if(s.week%52===0)annualAwards();compactCareer()}
function compactCareer(){for(const a of s.world){for(const x of a.catalog)if(x.uid===undefined)x.uid=a.nextCatalogId++;if(a.catalog.length>60){const keep=a.catalog.map((x,i)=>({x,i})).slice(-60),map=new Map(keep.map((v,i)=>[v.i,i]));a.archivedStreams=(a.archivedStreams||0)+a.catalog.slice(0,-60).reduce((n,x)=>n+(x.total||0),0);for(const {x} of keep)if(x.albumIndex!==undefined)x.albumIndex=map.get(x.albumIndex)??-1;a.catalog=keep.map(v=>v.x)}}for(const kind of ['songs','albums'])for(const [key,r] of Object.entries(s.chartBook[kind].records)){r.history=r.history.slice(r.you?-52:-12);if(!r.you&&s.week-r.lastSeen>26)delete s.chartBook[kind].records[key]}s.expansion.opportunities=s.expansion.opportunities.filter(x=>x.expires>=s.week&&!x.done).slice(-6);s.expansion.awards=s.expansion.awards.slice(-50);for(const b of s.achievements.briefings)if(b.id.startsWith('catalog:')&&s.week-b.week>32){b.body=b.body.split('\n\n')[0];b.detail='Summary archived. Full lifetime records remain in Career.'}if(s.week%26===0&&JSON.stringify(s).length>1500000)addBriefing('save-size:'+s.week,'News','Back up your long career','Your save is approaching the online storage limit. Export a copy from Career → Saves. Your complete player catalog is preserved.');for(const track of s.songs)if(track.released&&s.week-track.released>52){delete track.development;delete track.variation;delete track.appeal} }
function studioPackageInput(){return `<label>Recording budget<select name="package">${studioPackages.map((x,i)=>`<option value="${i}">${x.name} · ${x.fee?money(x.fee)+' upfront · up to +'+x.quality+' quality':'standard $90 single cost'}</option>`).join('')}</select></label><p class="fine">Extra production is paid when writing starts. Skills still matter; equipment cannot guarantee a hit.</p>`}
function tourEstimate(i){const v=venueTiers[i],demand=clamp(.4+level('marketability')*.003+level('stagePresence')*.003+Math.min(1,s.fans/v.fans)*.15,0,1);const sold=Math.round(v.seats*demand);const cost=Math.round(v.cost*(1-level('touring')*.002));return {sold,cost,gross:sold*v.ticket,energy:Math.round(48-level('touring')*.15),review:Math.round(level('stagePresence')*.7+level('charisma')*.3)}}
function tourPage(){return head('Plan your next live run','On the road.')+`<p>Three shows per run. Two slots, energy, and an upfront production budget. Estimates assume your current audience and skills.</p><div class="career-options">${venueTiers.map((v,i)=>{const t=tourEstimate(i);return `<section class="card"><h2>${v.name}</h2><p>${compact(v.fans)} fans required · ${compact(v.seats)} total seats</p>${profileRows([['Projected tickets',fmt(t.sold)],['Upfront budget',money(t.cost)],['Projected gross',money(t.gross)],['Projected profit',money(t.gross-t.cost)],['Time / energy','2 slots / '+t.energy]])}<button class="primary" ${s.fans<v.fans||s.expansion.tourWeek===s.week?'disabled':''} onclick="bookRun(${i})">Review booking</button></section>`}).join('')}</div><p class="fine">One run per week. Demand varies by up to 15%; tax and career overhead apply at week close.</p>`}
function bookRun(i,confirmed=false){if(!saveReady||saveConflict||!venueTiers[i])return;migrateExpansion();const v=venueTiers[i],t=tourEstimate(i);if(s.fans<v.fans||s.expansion.tourWeek===s.week)return;if(!confirmed){modal(`<h2>${v.name}: confirm your run</h2><p>Pay ${money(t.cost)} now. Uses 2 slots and ${t.energy} energy. Projected gross ${money(t.gross)}; actual ticket sales can vary. Unsold seats can mean a loss.</p><button class="primary" onclick="bookRun(${i},true)">Book and perform</button>`);return}if(s.ap<2){toast('You need two slots.');return}if(!spend(t.energy,t.cost))return;s.ap--;const sold=Math.min(v.seats,Math.round(t.sold*rand(.85,1.15))),gross=sold*v.ticket;changeCash(gross);recordIncome('live',gross);const fans=Math.round(sold*(.01+level('stagePresence')*.0002));s.fans+=fans;s.expansion.tourWeek=s.week;s.careerRecords.liveGross+=gross;s.careerRecords.liveProfit+=gross-t.cost;s.careerRecords.tours.push({week:s.week,title:v.name+' run '+(s.careerRecords.tours.length+1),gross,profit:gross-t.cost,fans,review:clamp(t.review+Math.round(rand(-8,8))),tickets:sold});gainXP('touring',60);gainXP('stagePresence',40);milestone('venue-'+i,'Played '+v.name.toLowerCase(),fmt(sold)+' tickets');log(v.name+': '+fmt(sold)+' tickets, '+money(gross-t.cost)+' profit before weekly overhead and tax.');$('modal').close();render();toast('Run complete · '+money(gross-t.cost)+' profit')}
function marketingPage(){const r=s.expansion.albumRollout;return head('Give your next era a plan','Marketing & promotion.')+marketingStudio()+`<section class="card"><details><summary>Catalog campaign budgets</summary><p>Choose the scale of your campaign. Each uses 1 slot and 10 energy. Once per week.</p>${promotionPlans.map((p,i)=>`<div class="row"><div><strong>${p.name}</strong><p>${money(p.cost)} · +${Math.round(p.boost*100)}% reach before audience response</p></div><button class="secondary" ${s.boost>0?'disabled':''} onclick="buyPromotion(${i})">Review</button></div>`).join('')}</details></section><section class="card"><h2>Four-week album rollout</h2>${r?`<p>Active through Week ${r.until}. Lead single: ${esc(s.songs.find(x=>x.id===r.lead)?.title||'Catalog')}.</p>`:`<p>Announce your next album and choose a released lead single. The budget funds four weeks of catalog promotion. Include that lead single on the album and release during the window for +10 cohesion. Cohesion adds up to 10% streams during the album’s first four weeks.</p><form class="form" onsubmit="planRollout(event)"><label>Album campaign name<input name="name" maxlength="55" required></label><label>Lead single<select name="lead">${s.songs.filter(x=>x.released).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><label>Budget<select name="plan"><option value="0">Grassroots · $200 · +10% each week</option><option value="1">Targeted · $10,000 · +25% each week</option><option value="2">National · $200,000 · +40% each week</option></select></label><button class="primary" ${s.songs.some(x=>x.released)?'':'disabled'}>Review rollout</button></form>`}</section>`}
function buyPromotion(i,confirmed=false){const p=promotionPlans[i];if(!p||s.boost>0)return;if(!confirmed){modal(`<h2>${p.name}</h2><p>Pay ${money(p.cost)} for +${Math.round(p.boost*100)}% catalog reach this week. Uses 1 slot and 10 energy. Results still depend on listeners.</p><button class="primary" onclick="buyPromotion(${i},true)">Launch campaign</button>`);return}if(!spend(10,p.cost))return;s.boost=p.boost;s.expansion.campaignWeek=s.week;$('modal').close();render()}
let pendingRollout=null;
function planRollout(event){event.preventDefault();const f=new FormData(event.target),i=Number(f.get('plan')),lead=Number(f.get('lead'));if(![0,1,2].includes(i)||!s.songs.some(x=>x.id===lead&&x.released))return;pendingRollout={name:String(f.get('name')).slice(0,55),lead,cost:[200,10000,200000][i],boost:[.1,.25,.4][i]};modal(`<h2>Announce ${esc(pendingRollout.name)}?</h2><p>${money(pendingRollout.cost)} upfront · 1 slot · 5 energy. Four weeks of promotion; no automatic album release.</p><button class="primary" onclick="confirmRollout()">Announce rollout</button>`)}
function confirmRollout(){if(!pendingRollout||s.expansion.albumRollout)return;const r=pendingRollout;if(!spend(5,r.cost))return;s.expansion.albumRollout={...r,started:s.week,until:s.week+3};pendingRollout=null;log('Announced '+r.name+' with a four-week rollout.');$('modal').close();render()}
function createOpportunity(){const choices=['Interview','Opening slot','Feature invitation','Festival set'];const type=choices[Math.floor(s.week/4)%choices.length],artist=s.world.filter(a=>a.fans<=Math.max(1000,s.fans*5)&&a.relation>-40).sort((a,b)=>b.fans-a.fans)[0]||s.world[s.world.length-1];const fee=Math.round(100+Math.sqrt(Math.max(1,s.fans))*12);s.expansion.opportunities.push({id:'offer-'+s.week,type,artist:artist.id,name:artist.name,fee,expires:s.week+4,week:s.week});addBriefing('offer:'+s.week,'Opportunity',type+' offer',artist.name+' has an opportunity for you. Review the payment, time, and audience effect in Career → Opportunities.')}
function opportunitiesPage(){return head('Choose your next opening','Opportunities.')+`<p>New offers arrive every four weeks. Offers expire; declining has no penalty.</p>${s.expansion.opportunities.filter(x=>!x.done&&x.expires>=s.week).map(o=>`<section class="card"><span class="eyebrow">Through Week ${o.expires}</span><h2>${esc(o.type)}</h2><p>With ${esc(o.name)} · ${esc(s.world[o.artist].genre)}</p><p>Earn ${money(o.fee)} · 1 slot · 15 energy. ${o.type==='Feature invitation'?'Build your relationship and earn a featured appearance.':'Gain audience exposure based on your charisma.'}</p><button class="primary" onclick="acceptOpportunity('${o.id}')">Review offer</button><button class="secondary" onclick="declineOpportunity('${o.id}')">Decline</button></section>`).join('')||'<section class="card"><p>No active offers. Keep building your career and check after Week '+(Math.floor(s.week/4)*4+4)+'.</p></section>'}`}
function declineOpportunity(id){if(!saveReady||saveConflict)return;const o=s.expansion.opportunities.find(x=>x.id===id);if(o)o.done=true;render()}
function acceptOpportunity(id,confirmed=false){const o=s.expansion.opportunities.find(x=>x.id===id&&!x.done&&x.expires>=s.week);if(!o)return;if(!confirmed){modal(`<h2>${esc(o.type)}</h2><p>Accept ${money(o.fee)} for 1 slot and 15 energy. Earn exposure and +5 relationship with ${esc(o.name)}. Income is included in this week’s finances.</p><button class="primary" onclick="acceptOpportunity('${o.id}',true)">Accept and complete</button>`);return}if(!spend(15))return;o.done=true;changeCash(o.fee);recordIncome('live',o.fee);s.world[o.artist].relation=clamp(s.world[o.artist].relation+5,-100,100);s.fans+=Math.round(20+Math.sqrt(s.fans)*(.1+level('charisma')*.003));if(o.type==='Feature invitation'){s.expansion.featureAppearances=(s.expansion.featureAppearances||0)+1;const a=s.world[o.artist];a.catalog.push({uid:a.nextCatalogId++,title:generate('song')+' (feat. '+s.name+')',type:'Single',week:s.week,base:a.fans*.5,streams:Math.round(a.fans*.5),total:Math.round(a.fans*.5),factor:1})}milestone(o.id,o.type+' completed',o.name);log(o.type+' with '+o.name+': '+money(o.fee)+' earned.');$('modal').close();render()}
function signLabel(i,confirmed=false){const d=labelDeals[i];if(!d||s.labelBusiness?.company||s.expansion.contract||s.fans<d.fans||s.reputation<d.rep)return;if(!confirmed){modal(`<h2>Sign with ${d.name}?</h2><p>Receive ${money(d.advance)} now. For 26 weeks, the label takes ${Math.round(d.share*100)}% of all streaming royalties and adds ${Math.round(d.lift*100)}% reach support. You cannot cancel early. The advance is taxable.</p><button class="primary" onclick="signLabel(${i},true)">Sign 26-week contract</button>`);return}if(!saveReady||saveConflict)return;s.expansion.contract={...d,started:s.week,ends:s.week+25};changeCash(d.advance);recordIncome('wages',d.advance);milestone('signed-'+s.week,'Signed with '+d.name);$('modal').close();render()}
function annualAwards(){const year=Math.ceil(s.week/52),entries=s.songs.filter(x=>x.released> s.week-52&&x.released<=s.week),best=entries.slice().sort((a,b)=>awardScore(b)-awardScore(a))[0];const score=best?awardScore(best):0;const nominated=score>=60,won=nominated&&score>=78&&Math.random()<Math.min(.85,(score-60)/40);const result={year,title:best?.title||null,score:Math.round(score),nominated,won};s.expansion.awards.push(result);s.expansion.awardNominations=(s.expansion.awardNominations||0)+(nominated?1:0);s.expansion.awardWins=(s.expansion.awardWins||0)+(won?1:0);if(nominated){milestone('award-'+year,won?'ENCORE Record Award winner':'ENCORE Record Award nominee',best.title);addBriefing('awards:'+year,'Celebration','Year '+year+' ENCORE Record Awards',best.title+(won?' won Record of the Year.':' earned a Record of the Year nomination.')+' Judged on quality, chart performance, and audience reach.')}}
function awardScore(x){return x.quality*.65+Math.min(20,Math.log10(1+(x.total||0))*2.5)+(x.peak?15*(1-(x.peak-1)/100):0)}
function legacyPage(){return head('The story behind your numbers','Legacy.')+`<section class="card"><h2>ENCORE Record Awards</h2><p>At each 52-week year end, your best song released that year is considered. Score: 65% quality, up to 20 points for lifetime reach, and up to 15 for chart peak. Nomination: 60 points. Winning eligibility: 78; the final panel vote includes chance.</p>${s.expansion.awards.map(a=>`<div class="row"><span>Year ${a.year} · ${esc(a.title||'No eligible release')}</span><strong>${a.won?'Winner':a.nominated?'Nominee':'No nomination'} · ${a.score}</strong></div>`).join('')||'<p>Your first awards season arrives at Week 52.</p>'}</section><section class="card"><h2>Career timeline</h2><p class="fine">Most recent 200 milestones. Award detail retains 50 years; lifetime win and nomination totals remain in your profile.</p>${s.expansion.timeline.slice().reverse().map(x=>`<div class="story"><small>WEEK ${x.week}</small><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div>`).join('')||'<p>Your next milestone starts the story.</p>'}</section>`}
function careerTools(){return `<div class="chips">${['Touring','Campaigns','Opportunities','Labels','Legacy','Saves'].map(t=>`<button class="${careerTab===t?'selected':''}" onclick="careerTab='${t}';render()">${t}</button>`).join('')}</div>`}


/* Portable saves, recovery and isolated practice. */
const BACKUP_KEY='encore-recovery-v1-'+(SANDBOX?'sandbox':'career')+'-'+(OFFLINE?'offline':'online');
let pendingImport=null,practice=null;
function saveBundle(){return {format:'encore-career',schemaVersion:1,exportedAt:new Date().toISOString(),mode:SANDBOX?'sandbox':'career',state:JSON.parse(JSON.stringify(s))}}
function downloadBundle(bundle,prefix='ENCORE-save'){const url=URL.createObjectURL(new Blob([JSON.stringify(bundle,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=prefix+'-'+bundle.mode+'-week-'+bundle.state.week+'.json';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCareer(){if(saveReady){downloadBundle(saveBundle());noteBetaExport();toast('Save download prepared. Keep a copy in Files.')}}
function backupCareer(manual=false){if(!saveReady||saveConflict)return false;try{localStorage.setItem(BACKUP_KEY,JSON.stringify(saveBundle()));if(manual)toast('Recovery snapshot saved on this device.');return true}catch{if(manual)toast('Recovery storage unavailable. Export your career before replacing or resetting it.');return false}}
function readRecovery(){try{return JSON.parse(localStorage.getItem(BACKUP_KEY)||'null')}catch{return null}}
function savesPage(){const b=readRecovery();return head('Keep your story safe','Saves & recovery.')+`<section class="card"><h2>Portable career saves</h2><p>Download a JSON save and import it on another device or into the offline edition. Normal and sandbox files stay separate.</p><div class="save-actions"><button class="primary" onclick="exportCareer()">Export career</button><label class="secondary">Import save<input type="file" accept=".json,application/json" onchange="readImport(this.files[0]);this.value=''" style="display:block;max-width:100%;margin-top:8px"></label></div><p class="fine">Review the artist and week before replacing progress. Keep exports private: they contain your full career.</p></section><section class="card"><h2>Recovery snapshot</h2><p>A device-local snapshot is attempted before each week advance. This is one rotating backup. Export regularly in case browser storage is cleared.</p><p>${b?esc(b.state.name)+' · Week '+b.state.week+' · '+esc(b.exportedAt):'No snapshot yet.'}</p><div class="save-actions"><button class="secondary" onclick="backupCareer(true);render()">Back up now</button>${b?`<button class="secondary" onclick="previewImport(readRecovery())">Review restore</button><button class="secondary" onclick="downloadBundle(readRecovery(),'ENCORE-recovery')">Export recovery</button>`:''}</div></section><section class="card"><h2>Practice without consequences</h2><p>Write, record, mix and release a sample song using temporary resources.</p><button class="secondary" onclick="startPractice()">Practice a release</button></section>`}
function validateBundle(bundle){
 if(!bundle||bundle.format!=='encore-career'||bundle.schemaVersion!==1||!bundle.state)throw Error('Choose an ENCORE exported save.');
 if(bundle.mode!==(SANDBOX?'sandbox':'career')||!!bundle.state.sandbox!==SANDBOX)throw Error('Wrong game mode. Open '+(bundle.mode==='sandbox'?'sandbox':'normal career')+' to import this file.');
 const state=bundle.state;if(JSON.stringify(bundle).length>1800000)throw Error('Save exceeds the safe import limit.');let nodes=0;
 function walk(v,key='',depth=0){if(++nodes>150000||depth>18)throw Error('Save is too complex.');if(typeof v==='number'&&!Number.isFinite(v))throw Error('Invalid number.');if(typeof v==='string'){if(v.length>100000)throw Error('Text is too long.');if(['id','uid','key'].includes(key)&&!/^[-\w:.]+$/.test(v))throw Error('Invalid identifier.')}if(v&&typeof v==='object')for(const [k,x] of Object.entries(v)){if(['__proto__','prototype','constructor'].includes(k))throw Error('Unsafe save structure.');walk(x,k,depth+1)}}walk(state);
 const integer=(v,min,max)=>Number.isInteger(v)&&v>=min&&v<=max,numeric=(o,ks)=>ks.every(k=>Number.isFinite(o?.[k]));
 if(!integer(state.week,1,100000)||!integer(state.ap,0,6)||!integer(state.energy,0,100)||!numeric(state,['cash','fans','reputation','loyalty','streams','total','boost'])||state.fans<0||typeof state.name!=='string'||state.name.length>100||!genres.includes(state.genre))throw Error('Artist data is invalid.');
 for(const k of ['songs','albums','world','feed','history'])if(!Array.isArray(state[k]))throw Error('Missing '+k+'.');
 if(state.world.length!==24)throw Error('Incomplete industry roster.');
 if(!state.development||!Object.keys(developmentInfo).every(k=>numeric(state.development[k],['level','xp'])&&integer(state.development[k].level,0,100)&&state.development[k].xp>=0))throw Error('Invalid skill records.');
 if(!numeric(state.finance,['year','weeks','revenue','expenses','reserve','taxesPaid'])||!numeric(state.finance.week,['wages','live','expenses']))throw Error('Incomplete finances.');
 if(!state.careerRecords||!Array.isArray(state.careerRecords.tours)||!numeric(state.careerRecords,['openMics','royalties','liveGross','liveProfit']))throw Error('Incomplete career history.');
 if(!state.achievements||!state.achievements.unlocked||!Array.isArray(state.achievements.briefings)||!state.chartBook)throw Error('Incomplete milestones.');
 for(const kind of ['songs','albums']){const b=state.chartBook[kind];if(!b||!Array.isArray(b.current)||!b.records||typeof b.records!=='object')throw Error('Incomplete charts.');for(const r of Object.values(b.records))if(!Array.isArray(r.history))throw Error('Invalid chart history.');}
 const ids=new Set();for(const x of state.songs){if(!numeric(x,['id','quality','streams','total'])||typeof x.title!=='string'||typeof x.mood!=='string'||ids.has(x.id)||(x.released!==null&&!integer(x.released,1,state.week)))throw Error('Invalid song.');ids.add(x.id);if(x.feature&&!integer(x.feature.id,0,23))throw Error('Invalid feature.');}
 for(const a of state.albums)if(!numeric(a,['id','week'])||typeof a.title!=='string'||!Array.isArray(a.tracks)||a.tracks.some(id=>!ids.has(id)))throw Error('Incomplete album.');
 state.world.forEach((a,i)=>{if(a.id!==i||!Array.isArray(a.catalog)||!numeric(a,['fans','skill','reputation','relation','nextRelease'])||typeof a.name!=='string')throw Error('Invalid industry artist.');for(const t of a.catalog)if(typeof t.title!=='string'||!numeric(t,['week','streams','total']))throw Error('Invalid industry catalog.');});
 if(state.draft&&(!numeric(state.draft,['id','steps','quality'])||!state.draft.development||typeof state.draft.title!=='string'||typeof state.draft.mood!=='string'))throw Error('Invalid unfinished song.');
 if(state.projects!==undefined){if(!Array.isArray(state.projects)||state.projects.length>1000)throw Error('Invalid project library.');const projectIds=new Set(state.songs.map(x=>x.id));if(state.draft)projectIds.add(state.draft.id);for(const p of state.projects){if(!numeric(p,['id','steps','quality'])||!integer(p.steps,1,3)||typeof p.title!=='string'||typeof p.mood!=='string'||!p.development||projectIds.has(p.id))throw Error('Invalid parked project.');projectIds.add(p.id);}}
 if(state.studioIdea&&(typeof state.studioIdea.title!=='string'||typeof state.studioIdea.mood!=='string'||typeof state.studioIdea.package!=='string'))throw Error('Invalid studio idea.');
 for(const a of state.albums){if(a.price!==undefined&&!albumPrices.some(p=>p.value===a.price))throw Error('Invalid album price.');for(const k of ['sales','salesRevenue','weeklySales'])if(a[k]!==undefined&&(!Number.isFinite(a[k])||a[k]<0))throw Error('Invalid album sales.');}
 if(state.expansion?.marketingActions!==undefined){if(!Array.isArray(state.expansion.marketingActions))throw Error('Invalid campaigns.');for(const a of state.expansion.marketingActions)if(!marketingChannels.some(c=>c.id===a.channel)||!integer(a.week,1,state.week)||!Number.isFinite(a.estimate)||a.estimate<0||a.estimate>2||(a.boost!==null&&(!Number.isFinite(a.boost)||a.boost<0||a.boost>3))||(a.target!=='all'&&!state.songs.some(x=>x.id===a.target)))throw Error('Invalid campaign record.');}
 if(state.walletCents!==undefined&&(!/^-?\d{1,310}$/.test(state.walletCents)||!Number.isFinite(Number(BigInt(state.walletCents))/100)))throw Error('Invalid cash ledger.');
 const e=state.expansion;if(e){for(const k of ['timeline','opportunities','awards','contractHistory'])if(!Array.isArray(e[k]))throw Error('Incomplete expansion records.');if(e.contract&&(!numeric(e.contract,['ends','share','lift','started'])||e.contract.share<0||e.contract.share>1))throw Error('Invalid contract.');for(const o of e.opportunities)if(!integer(o.artist,0,23)||!numeric(o,['fee','expires'])||o.fee<0)throw Error('Invalid opportunity.');}
 for(const b of state.achievements.briefings)if(!b||typeof b.id!=='string'||typeof b.body!=='string'||typeof b.title!=='string')throw Error('Invalid briefing.');
 for(const t of state.careerRecords.tours)if(!t||!numeric(t,['week','gross','profit','fans','review'])||typeof t.title!=='string')throw Error('Invalid tour record.');
 if(e){for(const a of e.awards)if(!a||!numeric(a,['year','score'])||typeof a.nominated!=='boolean'||typeof a.won!=='boolean')throw Error('Invalid award.');for(const m of e.timeline)if(!m||typeof m.id!=='string'||typeof m.title!=='string'||typeof m.detail!=='string'||!Number.isFinite(m.week))throw Error('Invalid milestone.');}
 const candidate=JSON.parse(JSON.stringify(state)),active=s;
 try{s=candidate;migrateCharts();migratePacing();migrateDevelopment();migrateCareerRecords();migrateFinance();migrateChartBook();migrateAchievements();migrateExpansion();migrateLabelBusiness();validateLabelBusiness();for(const view of [home,studio,careerProfile,catalog,training,financeScreen,achievementsPage,certificationsPage,tourPage,marketingPage,opportunitiesPage,labelPage,legacyPage])view();}
 catch{throw Error('This save has incomplete gameplay data. Your active career was not changed.');}finally{s=active}
 return candidate;
}
async function readImport(file){if(!file)return;try{if(file.size>2000000)throw Error('Choose a save smaller than 2 MB.');previewImport(JSON.parse(await file.text()))}catch(e){toast('Import stopped: '+e.message)}}
function previewImport(bundle){try{pendingImport=validateBundle(bundle);modal(`<h2>Import this career?</h2>${profileRows([['Artist',pendingImport.name],['Week',pendingImport.week],['Mode',SANDBOX?'Sandbox':'Normal career'],['Cash',money(pendingImport.cash)],['Songs',pendingImport.songs.length]])}<p>This replaces the active career in this mode. We first save a recovery snapshot of your current career on this device.</p><button class="secondary" onclick="pendingImport=null;$('modal').close()">Cancel</button><button class="primary" onclick="confirmImport()">Back up and import</button>`)}catch(e){pendingImport=null;toast('Import stopped: '+e.message)}}
async function confirmImport(){if(!pendingImport||!saveReady||saveConflict||saveBusy){toast('Wait for saving to finish, or reload if another tab changed this career.');return}if(!backupCareer(true))return;clearTimeout(saveTimer);s=pendingImport;pendingImport=null;migrateCharts();migratePacing();migrateDevelopment();migrateCareerRecords();migrateFinance();migrateChartBook();migrateAchievements();migrateExpansion();$('modal').close();tab='Career';careerTab='Saves';render();await saveNow();toast(lastSaved===JSON.stringify(s)?'Career imported and saved.':'Imported in this tab. Save is pending—keep this tab open and use Retry save.')}
function playTour(){careerTab='Touring';go('Career')}
function startPractice(){practice={step:0,cash:650,energy:100,slots:6};practiceScreen()}
function practiceScreen(){const steps=[['Write a song','Choose a title and direction. Writing uses one slot and 10 energy.','Write · 10 energy'],['Record vocals','Recording uses your Recording skill. Pay $40, one slot and 15 energy.','Record · $40'],['Mix the record','Producing helps shape quality. Pay $30, one slot and 15 energy.','Mix · $30'],['Release the single','Publish for $20, one slot and 5 energy. The real game asks you to confirm.','Release · $20'],['Advance the week','Streams arrive at week close. Quality, promotion, and listener response all matter.','See sample results'],['Weekly report','Example: 300 streams earn $150 gross at $0.50 each. This is below the global chart floor. The real report also shows label shares, expenses, overhead and tax reserves.','Finish practice']];const t=steps[practice.step];modal(`<span class="eyebrow">ISOLATED PRACTICE · ${practice.step+1}/6</span><h2>${t[0]}</h2><p>${t[1]}</p><div class="practice-meter">${money(practice.cash)} · ${practice.energy}/100 energy · ${practice.slots}/6 slots</div><p class="fine">Your saved career is unchanged.</p><button class="primary" onclick="practiceNext()">${t[2]}</button><button class="secondary" onclick="practice=null;$('modal').close()">Leave practice</button>`)}
function practiceNext(){if(!practice)return;const costs=[[0,10],[40,15],[30,15],[20,5]];if(practice.step<4){practice.cash-=costs[practice.step][0];practice.energy-=costs[practice.step][1];practice.slots--}else if(practice.step===4){practice.cash+=150;practice.slots=6;practice.energy=Math.min(100,practice.energy+40)}else{practice=null;$('modal').close();return}practice.step++;practiceScreen()}
window.addEventListener('pageshow',e=>{if(e.persisted&&saveReady){endTour();$('modal').close();showTitle()}});


/* Beta support: explicit, player-controlled sharing; no automatic reports. */
const GAME_VERSION='0.4.0-beta.1';
const PUBLIC_GAME_URL='https://encoremusicsim.com';
const BETA_EXPORT_KEY='encore-last-export-'+(SANDBOX?'sandbox':'career')+'-'+(OFFLINE?'offline':'online');
let betaReportText='';
function betaInvitation(){return `I’m opening a small beta for ENCORE, my music career simulator!\n\nCreate your artist, write and release music, build relationships, climb the charts, and grow from local shows toward stadiums. Play in your browser—no sign-up.\n\nTry it here: ${PUBLIC_GAME_URL}\n\nStart a normal career and try your first 10 in-game weeks. Tell me what’s fun, confusing, too easy, or too hard. If something breaks, open Beta & feedback to prepare a report and send it back to me.\n\nThis is an early beta, so bugs and balance changes are expected. Back up your progress in Career → Saves. Thanks for helping shape ENCORE!`}
function betaInfo(){modal(`<span class="eyebrow">ENCORE · ${GAME_VERSION}</span><h2>Welcome to the beta.</h2><p>Help shape the game by playing a fresh career through your first ten weeks. The title screen always opens before gameplay.</p><div class="controls"><button class="primary" onclick="betaFeedback()">Report a bug / give feedback</button><button class="secondary" onclick="betaShare()">Invite a tester</button></div><h3>What to try</h3><ol><li>Create an artist and try the optional gameplay tour.</li><li>Write, record, mix and release your first song.</li><li>Train a skill, meet an artist, and advance the week.</li><li>Close and reopen the game to check your save.</li><li>Export a backup in Career → Saves.</li></ol><h3>Known limitations</h3><ul><li>Mobile layouts and long-term balance are still being tested. Tell us your device and browser if something looks wrong.</li><li>Online careers belong to this browser’s guest save. Clearing cookies can lose access. Offline careers are separate; use export/import to transfer.</li><li>Very large stream and income calculations are approximate. Extremely long careers can reach the save-size limit.</li><li>This is a solo simulation. Sandbox progress is separate from normal careers.</li></ul><h3>Protect your career</h3><p>Keep a downloaded backup before updates, switching devices, or clearing browser data. Automatic recovery is a single rotating snapshot on this device.</p>${saveReady?`<button class="secondary" onclick="exportCareer()">Export career backup</button>`:''}<details><summary>What’s new · ${GAME_VERSION}</summary><p>Beta version labels, player-controlled feedback reports, sharing tools, known issues, backup reminders and a first-session checklist. Existing careers and progression are preserved.</p></details><details><summary>Next priorities</summary><p>First: mobile controls and save reliability. Next: tune the first ten weeks and mid-career economy using tester feedback. Later: wider browser release and an installed app beta. Dates are not promised.</p></details><p class="fine">Online feedback is sent to the ENCORE beta host and stored for review. If sending fails, the game gives you a copy/share fallback. Do not include passwords or private information.</p><button class="secondary" onclick="$('modal').close()">Back to game</button>`)}
function betaFeedback(){modal(`<span class="eyebrow">${GAME_VERSION}</span><h2>Help improve ENCORE</h2><form class="form" onsubmit="submitBetaFeedback(event)"><label>Report type<select name="kind"><option>Bug</option><option>Confusing control</option><option>Balance feedback</option><option>Suggestion</option><option>Other</option></select></label><label>What happened?<textarea name="summary" required maxlength="2000" rows="4" placeholder="Describe the issue or your feedback"></textarea></label><label>Steps to reproduce<textarea name="steps" maxlength="2000" rows="3" placeholder="What did you tap before it happened?"></textarea></label><label>What did you expect?<textarea name="expected" maxlength="1000" rows="2"></textarea></label><label>Email (optional)<input name="contact" type="email" maxlength="254" autocomplete="email" placeholder="Only if you want a reply"></label><label>Device and browser<input name="device" maxlength="150" placeholder="For example: iPhone 15, Safari"></label><label style="display:none" aria-hidden="true">Website<input name="website" tabindex="-1" autocomplete="off"></label><button class="primary" id="beta-submit">Send feedback</button><p class="fine">Automatically includes ENCORE version, mode, current screen, in-game week, save status, and browser details. It does not send your career, artist name, cookies, or account data.</p></form>`)}
async function submitBetaFeedback(event){
 event.preventDefault();
 const form=event.target,f=new FormData(form),value=(key,max)=>String(f.get(key)||'').trim().slice(0,max);
 if(value('website',200))return;
 const summary=value('summary',2000);
 if(!summary){toast('Describe what happened first.');return}
 const button=$('beta-submit');if(button){button.disabled=true;button.textContent='Sending…'}
 const payload={version:GAME_VERSION,kind:value('kind',60),summary,steps:value('steps',2000),expected:value('expected',1000),contact:value('contact',254),mode:(SANDBOX?'Sandbox':'Normal career')+' / '+(OFFLINE?'Offline':'Browser'),week:saveReady?String(s.week):'Not loaded',screen:titleVisible?'Title':tab+(tab==='Career'?' / '+careerTab:''),saveStatus:saveConflict?'Conflict':saveBusy?'Saving':saveReady?(JSON.stringify(s)===lastSaved?'Saved':'Unsaved changes'):'Not loaded',device:value('device',150)||navigator.userAgent.slice(0,500)};
 if(OFFLINE){prepareBetaReport(event);return}
 try{
   const response=await fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
   const data=await response.json().catch(()=>({}));
   if(!response.ok)throw Error(data.error||'Could not send feedback');
   modal(`<span class="eyebrow">${GAME_VERSION}</span><h2>Feedback sent ✓</h2><p>Thank you for helping build ENCORE. Your report was received${data.id?' as <strong>'+esc(data.id.slice(0,8))+'</strong>':''}.</p><p class="fine">${data.emailed?'An email alert was also sent to the beta host.':'Your report is safely stored for review.'}</p><button class="primary" onclick="$('modal').close()">Back to game</button>`);
 }catch(error){
   betaReportText=`ENCORE BETA FEEDBACK\nVersion: ${GAME_VERSION}\nType: ${payload.kind}\nMode: ${payload.mode}\nWeek: ${payload.week}\nScreen: ${payload.screen}\nSave: ${payload.saveStatus}\nDevice/browser: ${payload.device}\nContact: ${payload.contact||'Not provided'}\n\nWhat happened:\n${payload.summary}\n\nSteps:\n${payload.steps||'Not provided'}\n\nExpected:\n${payload.expected||'Not provided'}`;
   modal(`<h2>Couldn’t send automatically</h2><p>Your report is still ready. Copy or share it so your feedback is not lost.</p><textarea id="beta-copy" readonly rows="12">${esc(betaReportText)}</textarea><div class="controls"><button class="primary" onclick="copyBetaText()">Copy report</button><button class="secondary" onclick="shareBetaText(false)">Share report</button></div><p id="beta-copy-status" role="status"></p>`);
 }finally{if(button){button.disabled=false;button.textContent='Send feedback'}}
}
function prepareBetaReport(event){event.preventDefault();const f=new FormData(event.target),value=(key,max)=>String(f.get(key)||'').trim().slice(0,max);if(!value('summary',2000)){toast('Describe what happened first.');return}betaReportText=`ENCORE BETA FEEDBACK\nVersion: ${GAME_VERSION}\nType: ${value('kind',40)}\nMode: ${SANDBOX?'Sandbox':'Normal career'} / ${OFFLINE?'Offline':'Browser'}\nWeek: ${saveReady?s.week:'Not loaded'}\nScreen: ${titleVisible?'Title':tab+(tab==='Career'?' / '+careerTab:'')}\nSave: ${saveConflict?'Conflict':saveBusy?'Saving':saveReady?(JSON.stringify(s)===lastSaved?'Saved':'Unsaved changes'):'Not loaded'}\nDevice/browser: ${value('device',150)||'Not provided'}\n\nWhat happened:\n${value('summary',2000)}\n\nSteps:\n${value('steps',2000)||'Not provided'}\n\nExpected:\n${value('expected',1000)||'Not provided'}`;betaReportPreview()}
function betaReportPreview(){modal(`<h2>Your report is ready</h2><p>Send this to the person who invited you. Include a screenshot separately if it helps. This report has not been submitted.</p><textarea id="beta-copy" readonly rows="12">${esc(betaReportText)}</textarea><div class="controls"><button class="primary" onclick="copyBetaText()">Copy report</button><button class="secondary" onclick="shareBetaText(false)">Share report</button><button class="secondary" onclick="downloadBetaReport()">Download report</button></div><p id="beta-copy-status" role="status"></p>`)}
function betaShare(){modal(`<h2>Invite someone to ENCORE</h2><p>This invitation opens the normal game, with a separate career for each browser.</p><textarea id="beta-copy" readonly rows="12">${esc(betaInvitation())}</textarea><div class="controls"><button class="primary" onclick="shareBetaText(true)">Share invitation</button><button class="secondary" onclick="copyBetaText()">Copy invitation</button></div><p id="beta-copy-status" role="status"></p>`)}
async function copyBetaText(){const el=$('beta-copy');try{if(!globalThis.navigator?.clipboard?.writeText)throw Error('Unavailable');await navigator.clipboard.writeText(el.value);$('beta-copy-status').textContent='Copied. Paste it into your message.'}catch{el.focus?.();el.select?.();$('beta-copy-status').textContent='Select and copy the text above using your browser.'}}
async function shareBetaText(invitation){const text=invitation?betaInvitation():betaReportText;if(globalThis.navigator?.share){try{await navigator.share({title:invitation?'Try ENCORE beta':'ENCORE beta feedback',text});return}catch(e){if(e.name==='AbortError')return}}await copyBetaText()}
function downloadBetaReport(){const url=URL.createObjectURL(new Blob([betaReportText],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='ENCORE-beta-report.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('beta-copy-status').textContent='Download prepared. Send the saved file to your beta host.'}
function noteBetaExport(){try{localStorage.setItem(BETA_EXPORT_KEY,JSON.stringify({week:s.week,at:Date.now()}))}catch{}}
function betaHomeNotice(){let last=null;try{last=JSON.parse(localStorage.getItem(BETA_EXPORT_KEY)||'null')}catch{}const due=s.started&&(!last||s.week-last.week>=4||s.week<last.week);return `<aside class="beta-strip"><div><strong>ENCORE BETA · ${GAME_VERSION}</strong><p>${due?'Keep a downloaded career backup. Recovery snapshots stay on this device.':'Help us test your first ten weeks. Report confusing controls, bugs, or balance issues.'}</p></div><div class="controls">${due?'<button class="secondary" onclick="exportCareer()">Export backup</button>':''}<button class="secondary" onclick="betaInfo()">Beta & feedback</button></div></aside>`}


/* Studio continuity, release strategy and accessible career navigation. */
const directions=[
 {id:'Personal / storytelling',name:'Storytelling',note:'Writing-led; stronger fan conversion.',weights:[.4,.3,.15,.05,.1],reach:1,fans:.026,decay:[.81,.95],appeal:0,viral:1},
 {id:'Catchy / radio-ready',name:'Radio hook',note:'+20% debut reach; brighter commercial appeal.',weights:[.3,.3,.25,.05,.1],reach:1.2,fans:.016,decay:[.8,.94],appeal:8,viral:1},
 {id:'Raw / experimental',name:'Experimental',note:'Production-led; unpredictable audience reception.',weights:[.25,.25,.35,.05,.1],reach:1,fans:.018,decay:[.8,.94],appeal:0,viral:1.2},
 {id:'Heartbreak / intimate',name:'Heartbreak',note:'Vocals and lyrics; loyal fans, softer debut.',weights:[.35,.4,.1,.05,.1],reach:.9,fans:.029,decay:[.83,.96],appeal:-3,viral:.8},
 {id:'Club / dancefloor',name:'Club anthem',note:'Production and hooks; fast launch, faster fade.',weights:[.2,.25,.35,.05,.15],reach:1.15,fans:.014,decay:[.76,.91],appeal:6,viral:1.4},
 {id:'Acoustic / stripped-back',name:'Stripped back',note:'Writing and delivery; smaller, longer-lived reach.',weights:[.4,.4,.1,.05,.05],reach:.85,fans:.025,decay:[.85,.97],appeal:-4,viral:.7},
 {id:'Anthem / statement',name:'Statement',note:'Writing and charisma; strong audience connection.',weights:[.4,.25,.15,.15,.05],reach:.95,fans:.03,decay:[.82,.95],appeal:0,viral:1.1},
 {id:'Cinematic / atmospheric',name:'Cinematic',note:'Production-led; patient discovery and catalog life.',weights:[.2,.25,.4,.05,.1],reach:.9,fans:.02,decay:[.85,.97],appeal:-2,viral:.9}
];
const albumPrices=[{value:5,label:'Accessible',detail:'$5 download · more buyers',demand:1.7},{value:10,label:'Standard',detail:'$10 download · balanced demand',demand:1},{value:15,label:'Premium',detail:'$15 download · fewer buyers',demand:.58},{value:20,label:'Supporter',detail:'$20 download · smallest audience',demand:.35}];
const marketingChannels=[
 {id:'community',name:'Fan community',cost:0,energy:10,boost:.04,skill:'charisma',scale:.0008,note:'Build connection. +1 loyalty on completion.'},
 {id:'video',name:'Short-form video',cost:150,energy:12,boost:.06,skill:'viralAbility',scale:.0015,note:'Reach varies from 70–150% of the estimate.'},
 {id:'playlist',name:'Playlist pitch',cost:1000,energy:10,boost:.2,skill:'marketability',scale:.001,note:'65% placement chance. A miss adds just 2% reach.'},
 {id:'press',name:'Press interview',cost:2500,energy:15,boost:.12,skill:'charisma',scale:.0015,note:'A completed interview also adds 1 reputation.'},
 {id:'radio',name:'Radio campaign',cost:10000,energy:10,boost:.35,skill:'marketability',scale:.001,note:'A predictable reach boost, influenced by marketability.'},
 {id:'creator',name:'Creator partnership',cost:25000,energy:15,boost:.45,skill:'viralAbility',scale:.0015,note:'Broader discovery; still no guaranteed hit.'}
];
function directionFor(track){return directions.find(x=>x.id===track.mood)||directions[0]}
function rollChoices(name,choices,selected){return `<fieldset class="roll-field"><legend>${esc(name==='mood'?'Creative direction':name==='package'?'Production budget':name==='price'?'Download price':'Choose an option')}</legend><div class="roll-options" role="group" aria-label="${esc(name)} choices">${choices.map(c=>`<label class="roll-choice"><input type="radio" name="${esc(name)}" value="${esc(c.value)}" ${String(c.value)===String(selected)?'checked':''}><span><strong>${esc(c.label)}</strong><small>${esc(c.detail)}</small></span></label>`).join('')}</div><p class="fine">Swipe for more choices, or use Tab and arrow keys.</p></fieldset>`}
function migrateExperience(){if(!Array.isArray(s.projects))s.projects=[];if(!s.studioIdea)s.studioIdea={title:'',mood:directions[0].id,package:'0'};if(!Array.isArray(s.expansion.marketingActions))s.expansion.marketingActions=[];for(const a of s.albums){if(a.price===undefined)a.price=10;if(!a.salesTrackingWeek)a.salesTrackingWeek=s.week;if(!Number.isFinite(a.sales))a.sales=0;if(!Number.isFinite(a.salesRevenue))a.salesRevenue=0;if(!Number.isFinite(a.weeklySales))a.weeklySales=0}}
function captureStudioIdea(form){if(!saveReady||saveConflict)return;const f=new FormData(form);s.studioIdea={title:String(f.get('songtitle')||'').slice(0,70),mood:String(f.get('mood')||directions[0].id),package:String(f.get('package')||'0')};queueSave()}
function studio(){migrateExperience();const d=s.draft,idea=s.studioIdea;return head('Your projects stay with you','The studio.',`<button class="secondary" onclick="openSettings()">Settings</button>`)+metricRail([['Energy',s.energy+'/100'],['Time',s.ap+' slots'],['Cash',money(s.cash)],['In progress',s.projects.length+(d?1:0)]])+`<div class="studio-stack"><section class="card studio-active">${d?`<span class="eyebrow">ACTIVE PROJECT · ${esc(d.mood)}</span><h2>${esc(d.title)}</h2><p class="project-persist">Saved in your career · Carries into future weeks</p><div class="project-stages">${['Written','Recorded','Mixed'].map((label,i)=>`<span class="${d.steps>i?'complete':''}">${d.steps>i?'✓ ':''}${label}</span>`).join('')}</div>${profileRows([['Quality',d.quality+'/100'],['Commercial potential',(d.commercial??d.quality)+'/100'],['Next step',d.steps===1?'Record · $40 · 15 energy · 1 slot':d.steps===2?'Mix · $30 · 15 energy · 1 slot':'Release · $20 · 5 energy · 1 slot']])}<div class="controls">${d.steps<3?`<button class="primary" onclick="progressSong()">${d.steps===1?'Record vocals':'Mix the song'}</button>`:`<button class="primary" onclick="finishSong(true)">Review single release</button><button class="secondary" onclick="finishSong(false)">Keep for an album</button>`}<button class="secondary" onclick="parkProject()">Save & work on another</button></div>${d.feature?`<p>Featuring ${esc(d.feature.name)} · ${money(d.feature.fee)} fee</p>`:`<button class="text-button" onclick="featurePicker()">Choose a featured artist</button>`}`:`<h2>Start your next record</h2><form class="form" oninput="captureStudioIdea(this)" onchange="captureStudioIdea(this)" onsubmit="newSong(event)"><label>Song title${nameInput('songtitle','song',idea.title,'Name your next record')}</label>${rollChoices('mood',directions.map(x=>({value:x.id,label:x.name,detail:x.note})),idea.mood)}${rollChoices('package',studioPackages.map((x,i)=>({value:i,label:x.name,detail:x.fee?money(x.fee)+' upfront · up to +'+x.quality+' quality':'No upfront fee · $90 total to release'})),idea.package)}<button class="primary">Start writing · 10 energy · 1 slot</button><p class="fine">Title and choices save as an idea before you start. Writing begins a project that stays across weeks. Base release total: $90, 45 energy and 4 slots, plus the selected production budget.</p></form>`}</section><section class="card"><div class="sectionhead"><h2>Project library</h2><span class="pill">${s.projects.length} parked</span></div>${s.projects.map(p=>`<div class="project-row"><div><strong>${esc(p.title)}</strong><small>${['','Written · recording next','Recorded · mixing next','Finished · ready to release'][p.steps]} · ${esc(p.mood)}</small></div><button class="secondary" onclick="resumeProject(${p.id})">Resume</button></div>`).join('')||'<p>No parked projects. Use “Save & work on another” to keep a song here.</p>'}</section><section class="card"><h2>Finished recordings</h2>${s.songs.filter(x=>!x.released).map(x=>`<div class="project-row"><div><strong>${esc(x.title)}</strong><small>Ready for a single or an album · Quality ${x.quality}</small></div><button class="secondary" onclick="releaseShelf(${x.id})">Review release</button></div>`).join('')||'<p>Mixed songs kept for an album appear here.</p>'}<div class="controls"><button class="primary" onclick="albumForm()">Assemble an album</button><button class="secondary" onclick="careerTab='Campaigns';go('Career')">Marketing & promotion</button></div><p class="fine">Albums need at least three finished recordings. Choose your download price before release.</p></section></div>`}
function parkProject(){if(!saveReady||saveConflict||!s.draft)return;s.projects.push({...s.draft,parkedWeek:s.week});s.draft=null;render();toast('Project saved. Resume it from your project library anytime.')}
function resumeProject(id){if(!saveReady||saveConflict)return;const p=s.projects.find(x=>x.id===id);if(!p)return;s.projects=s.projects.filter(x=>x.id!==id);if(s.draft)s.projects.push({...s.draft,parkedWeek:s.week});s.draft=p;tab='Create';render();toast('Project resumed. Its progress and feature are preserved.')}
function openSettings(){modal(`<span class="eyebrow">ENCORE · ${GAME_VERSION}</span><h2>Settings & help</h2><div class="settings-stack"><button onclick="toggleTheme();openSettings()"><strong>Appearance</strong><span>${theme==='dark'?'Dark':'Light'} mode · tap to switch</span></button><button onclick="$('modal').close();careerTab='Saves';go('Career')"><strong>Saves & recovery</strong><span>Export, import, or review a backup</span></button><button onclick="$('modal').close();setup()"><strong>Artist profile</strong><span>Edit your name and genre</span></button><button onclick="openTour(0)"><strong>Gameplay tour</strong><span>Walk through the game screens</span></button><button onclick="startPractice()"><strong>Practice a release</strong><span>Learn with separate temporary resources</span></button><button onclick="toggleBriefings();openSettings()"><strong>News & achievement pop-ups</strong><span>${s.achievements.popups?'On':'Off'}</span></button><button onclick="betaInfo()"><strong>Beta & feedback</strong><span>Report a bug or review known issues</span></button><button onclick="$('modal').close();showTitle()"><strong>Title screen</strong><span>Return to the opening screen</span></button><button onclick="resetAsk()"><strong>New career</strong><span>Review before resetting this mode</span></button></div>`)}
const careerGroups=[{name:'Overview',tabs:['Profile','Releases']},{name:'Business',tabs:['Campaigns','Touring','Opportunities','Labels','Finances']},{name:'Legacy',tabs:['Achievements','Certifications','Legacy','Activity']},{name:'Manage',tabs:['Saves']}];
function careerMenu(){const group=careerGroups.find(g=>g.tabs.includes(careerTab))||careerGroups[0];return `<div class="career-navigation"><div class="career-groups">${careerGroups.map(g=>`<button class="${g===group?'selected':''}" onclick="careerTab='${g.tabs[0]}';render()">${g.name}</button>`).join('')}<button onclick="openSettings()" aria-label="Open settings">Settings</button></div><div class="career-subnav" aria-label="${group.name} sections">${group.tabs.map(t=>`<button class="${careerTab===t?'selected':''}" aria-current="${careerTab===t?'page':'false'}" onclick="careerTab='${t}';render()">${t==='Profile'?'Artist wealth':t==='Campaigns'?'Marketing':t}</button>`).join('')}</div></div>`}
function pricingField(selected=10){return rollChoices('price',albumPrices,selected)}
function changeAlbumPrice(id,confirmed=false){const a=s.albums.find(x=>x.id===id);if(!a||!saveReady||saveConflict)return;if(!confirmed){modal(`<h2>Price “${esc(a.title)}”</h2><p>Price affects paid downloads. Streaming royalties remain $0.50 per play. Changes apply to future weeks.</p><form onsubmit="event.preventDefault();applyAlbumPrice(${id},Number(new FormData(this).get('price')))">${pricingField(a.price)}<button class="primary">Save price</button></form>`)} }
function applyAlbumPrice(id,price){if(!saveReady||saveConflict||!albumPrices.some(x=>x.value===price))return;const a=s.albums.find(x=>x.id===id);if(!a)return;a.price=price;log('“'+a.title+'” download price set to '+money(price)+'.');$('modal').close();render()}
function settleAlbumSales(){let income=0;for(const a of s.albums){const tracks=s.songs.filter(x=>a.tracks.includes(x.id)),quality=tracks.reduce((n,x)=>n+x.quality,0)/Math.max(1,tracks.length),tier=albumPrices.find(x=>x.value===a.price)||albumPrices[1],age=Math.max(0,s.week-a.week),remaining=Math.max(0,Math.floor(s.fans*.35)-a.sales);const demand=s.fans*.025*tier.demand*(.4+quality/100)*(1+s.loyalty/200)*Math.pow(.88,age)*(1+Math.min(1,s.boost));a.weeklySales=Math.min(remaining,Math.max(0,Math.round(demand)));a.sales+=a.weeklySales;const gross=a.weeklySales*a.price;a.salesRevenue=cents(a.salesRevenue+gross);income+=gross}if(income){changeCash(income);s.finance.week.albumSales=cents((s.finance.week.albumSales||0)+income)}return income}
function channelEstimate(c){return c.boost+level(c.skill)*c.scale}
function marketingActions(){return s.expansion.marketingActions.filter(x=>x.week===s.week)}
function marketingStudio(){const active=marketingActions(),released=s.songs.filter(x=>x.released);return `<section class="card"><span class="eyebrow">CHOOSE YOUR CHANNEL · ${active.length}/2 THIS WEEK</span><h2>Reach the right listeners</h2><p>Pick up to two different channels each week. Choose the full catalog or one released song. Each action uses one slot.</p><div class="channel-stack">${marketingChannels.map(c=>`<div class="channel-card"><div><h3>${c.name}</h3><p>${money(c.cost)} · ${c.energy} energy · Estimated +${Math.round(channelEstimate(c)*100)}% reach</p><p class="fine">${c.note}</p></div><button class="secondary" ${!released.length||active.length>=2||active.some(a=>a.channel===c.id)?'disabled':''} onclick="reviewMarketing('${c.id}')">Choose</button></div>`).join('')}</div>${active.length?`<div class="highlightbox">Booked: ${active.map(a=>esc(marketingChannels.find(c=>c.id===a.channel).name)).join(', ')}. Results arrive at week close.</div>`:''}</section>`}
function reviewMarketing(id){const c=marketingChannels.find(x=>x.id===id);if(!c)return;modal(`<h2>${c.name}</h2><p>${c.note}</p><form onsubmit="bookMarketing(event,'${c.id}')"><label>Promote<select name="target"><option value="all">Full catalog</option>${s.songs.filter(x=>x.released).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('')}</select></label><p>Pay ${money(c.cost)} now · 1 slot · ${c.energy} energy. The campaign runs at this week’s close.</p><button class="primary">Confirm campaign</button></form>`)}
function bookMarketing(event,id){event.preventDefault();const c=marketingChannels.find(x=>x.id===id),active=marketingActions(),target=new FormData(event.target).get('target');if(!c||active.length>=2||active.some(a=>a.channel===id)||!s.songs.some(x=>x.released))return;if(target!=='all'&&!s.songs.some(x=>x.id===Number(target)&&x.released))return;if(!spend(c.energy,c.cost))return;s.expansion.marketingActions.push({week:s.week,channel:id,target:target==='all'?'all':Number(target),estimate:channelEstimate(c),boost:null});$('modal').close();render()}
function resolveMarketing(){for(const action of marketingActions()){if(action.boost!==null)continue;const c=marketingChannels.find(x=>x.id===action.channel);if(!c)continue;action.boost=action.estimate;if(c.id==='video')action.boost*=rand(.7,1.5);if(c.id==='playlist'&&Math.random()>.65)action.boost=.02;if(c.id==='community')s.loyalty=clamp(s.loyalty+1);if(c.id==='press')s.reputation=clamp(s.reputation+1);log(c.name+' delivered +'+Math.round(action.boost*100)+'% reach'+(action.target==='all'?' across your catalog.':' for your selected song.'))}s.expansion.marketingActions=s.expansion.marketingActions.filter(a=>s.week-a.week<8)}
function trackMarketingBoost(track){return Math.min(1.5,marketingActions().filter(a=>a.target==='all'||a.target===track.id).reduce((n,a)=>n+(a.boost||0),0))}
const CHECKPOINT_KEY='encore-pending-v1-'+(SANDBOX?'sandbox':'career');
function checkpointCareer(){if(OFFLINE||!saveReady||saveConflict)return;try{localStorage.setItem(CHECKPOINT_KEY,JSON.stringify({etag:saveEtag,state:s,mode:SANDBOX,at:Date.now()}))}catch{}}
function recoverPendingCareer(data){if(OFFLINE||!data.save||!data.etag)return;try{const pending=JSON.parse(localStorage.getItem(CHECKPOINT_KEY)||'null');if(!pending||pending.mode!==SANDBOX||pending.etag!==data.etag||pending.state.week<data.save.state.week)return;const candidate=validateBundle({format:'encore-career',schemaVersion:1,mode:SANDBOX?'sandbox':'career',state:pending.state});s=candidate;}catch{}}

/* Sandbox edits have a separate save and never run in the normal mode. */
function sandboxEditor(){if(!SANDBOX||!saveReady||saveConflict)return;modal(`<div class="eyebrow">ENCORE LAB</div><h2>Edit your sandbox</h2><p>Changes apply only to this sandbox. Released music keeps its existing quality; new recordings use your edited skills. Money edits are test grants, not taxable income.</p><form class="form" onsubmit="applySandboxEdits(event)"><h3>Resources</h3><label>Money (dollars)<input name="cash" inputmode="decimal" value="${(BigInt(s.walletCents)/100n).toString()}.${String(BigInt(s.walletCents)%100n).padStart(2,'0')}" required></label><label>Fans<input name="fans" type="number" min="0" max="9007199254740991" step="1" value="${s.fans}" required></label>${[['energy','Energy',100],['ap','Time slots',6],['reputation','Reputation',100],['loyalty','Fan loyalty',100]].map(([key,label,max])=>`<label>${label}<input type="number" name="${key}" min="0" max="${max}" step="1" value="${s[key]}" required></label>`).join('')}<h3>Artist skills · 0–100</h3>${Object.entries(developmentInfo).map(([key,info])=>`<label>${info[0]}<input type="number" min="0" max="100" step="1" name="stat_${key}" value="${level(key)}" required></label>`).join('')}<details><summary>Relationships · all ${s.world.length} artists</summary><p>−100 = enemies · 0 = neutral · 100 = close friends. Reputation and fan requirements still apply to features.</p>${s.world.map(a=>`<label>${esc(a.name)} · ${esc(a.genre)}<input name="relation_${a.id}" type="number" min="-100" max="100" step="1" value="${a.relation}" required></label>`).join('')}</details><p id="lab-error" role="alert"></p><button class="primary">Apply sandbox changes</button></form>`)}
function applySandboxEdits(event){event.preventDefault();if(!SANDBOX||!saveReady||saveConflict)return;try{const f=new FormData(event.target),num=(key,min,max)=>{const raw=f.get(key);const n=Number(raw);if(raw===null||String(raw).trim()===''||!Number.isSafeInteger(n)||n<min||n>max)throw Error('Enter a whole number from '+min+' to '+max+' for '+key.replace('stat_','').replace('relation_','relationship ')+'.');return n};const raw=String(f.get('cash')||'').replaceAll(',','').trim();if(!/^\d{1,25}(\.\d{1,2})?$/.test(raw))throw Error('Use a positive dollar amount with up to 25 digits and two decimal places.');const parts=raw.split('.'),cash=BigInt(parts[0])*100n+BigInt((parts[1]||'').padEnd(2,'0'));const values={fans:num('fans',0,Number.MAX_SAFE_INTEGER),energy:num('energy',0,100),ap:num('ap',0,6),reputation:num('reputation',0,100),loyalty:num('loyalty',0,100)},stats=Object.fromEntries(Object.keys(developmentInfo).map(k=>[k,num('stat_'+k,0,100)])),relations=s.world.map(a=>num('relation_'+a.id,-100,100));Object.assign(s,values);s.walletCents=cash.toString();s.cash=Number(cash)/100;for(const [k,level] of Object.entries(stats))if(s.development[k].level!==level)s.development[k]={level,xp:0};s.world.forEach((a,i)=>{if(a.relation!==relations[i])a.discount=0;a.relation=relations[i]});log('Sandbox values updated.');$('modal').close();render();toast('Sandbox changes applied.')}catch(e){$('lab-error').textContent=e.message}}
const titleDials={};
function dialMarkup(id,kind){return `<details class="title-picker" ontoggle="if(this.open)prepareTitleDial('${id}','${kind}')"><summary>Turn the title dial</summary><p class="fine">Drag around the record, scroll, or use arrow keys. Your selected title fills the field above; you can still type your own.</p><div class="title-dial-row"><button type="button" class="secondary" aria-label="Previous title" onclick="turnTitleDial('${id}',-1)">‹</button><div class="title-dial" id="dial-${id}" role="slider" tabindex="0" aria-label="${kind} title dial" aria-valuemin="1" aria-valuemax="40" aria-valuenow="1" onpointerdown="dragTitleDial(event,'${id}')" onkeydown="keyTitleDial(event,'${id}')" onwheel="event.preventDefault();turnTitleDial('${id}',event.deltaY>0?1:-1)"><span>ENCORE<br>TURN TO NAME</span><i></i></div><button type="button" class="secondary" aria-label="Next title" onclick="turnTitleDial('${id}',1)">›</button></div><output id="dial-label-${id}" class="dial-title" aria-live="polite"></output><button type="button" class="secondary" onclick="prepareTitleDial('${id}','${kind}',true)">New batch of 40</button></details>`}
function prepareTitleDial(id,kind,refresh=false){{const values=Array.from({length:40},()=>generate(kind));const current=$(id).value;if(current&&!refresh)values[0]=current;titleDials[id]={values,index:0,kind}}paintTitleDial(id,true)}
function paintTitleDial(id,apply=true){const d=titleDials[id];if(!d)return;const value=d.values[d.index],el=$('dial-'+id);el.style.setProperty('--turn',(d.index*18)+'deg');el.setAttribute('aria-valuenow',d.index+1);el.setAttribute('aria-valuetext',value);$('dial-label-'+id).textContent=value;if(apply){$(id).value=value;if(id==='songtitle')captureStudioIdea($(id).closest('form'))}}
function turnTitleDial(id,step){const d=titleDials[id];if(!d)return;d.index=(d.index+step+d.values.length)%d.values.length;paintTitleDial(id)}
function keyTitleDial(e,id){const steps={ArrowRight:1,ArrowDown:1,ArrowLeft:-1,ArrowUp:-1,PageDown:5,PageUp:-5};if(steps[e.key]){e.preventDefault();turnTitleDial(id,steps[e.key])}}
function dragTitleDial(e,id){if(e.button!==0)return;e.preventDefault();const el=e.currentTarget,rect=el.getBoundingClientRect(),angle=ev=>Math.atan2(ev.clientY-rect.top-rect.height/2,ev.clientX-rect.left-rect.width/2)*180/Math.PI;let last=angle(e),travel=0;el.setPointerCapture(e.pointerId);el.focus();el.onpointermove=ev=>{let next=angle(ev),delta=((next-last+540)%360)-180;last=next;travel+=delta;while(Math.abs(travel)>=18){const step=Math.sign(travel);turnTitleDial(id,step);travel-=step*18}};const end=()=>{el.onpointermove=null;el.onpointerup=null;el.onpointercancel=null};el.onpointerup=end;el.onpointercancel=end}

/* Label ownership, offers and direct studio collaboration. All amounts are game rules. */
const labelStaff={manager:{name:'Label manager',salary:1500,detail:'Expands the roster from 3 to 6 artists while hired. Routine settlements use no time slots.'},marketing:{name:'Marketing team',salary:2500,detail:'Adds 15% streams to newly released roster records when payroll is funded.'},ar:{name:'A&R scout',salary:1000,detail:'Reduces the advances artists request by 15% while employed.'}};
function migrateLabelBusiness(){if(!s.labelBusiness)s.labelBusiness={offers:[],auditions:{},lastScouted:0,company:null};}
function labelActive(){return saveReady&&!saveConflict}
function ownerContracts(){return s.labelBusiness.company?.contracts.filter(c=>c.ends>=s.week)||[]}
function labelPayroll(){const co=s.labelBusiness.company;return co?Object.keys(labelStaff).reduce((n,k)=>n+(co.staff[k]?labelStaff[k].salary:0),0):0}
function labelCapacity(){return s.labelBusiness.company?.staff.manager?6:3}
function labelPage(){migrateLabelBusiness();return head('Your music. Your business.','Labels.')+`<div class="label-sections"><section class="card"><h2>Your artist deal</h2><p>Offers arrive as your career grows. Submit a released song as a demo to pitch a label earlier. Deals last 26 weeks; review income shares before signing.</p>${s.expansion.contract?`<h3>${esc(s.expansion.contract.name)}</h3>${profileRows([['Ends after week',s.expansion.contract.ends],['Label share',Math.round(s.expansion.contract.share*100)+'%'],['Scope',s.expansion.contract.type==='360'?'Streaming, album downloads and live income':s.expansion.contract.type==='record'?'Streaming and album downloads':'Streaming royalties'],['Advance',money(s.expansion.contract.advance)]])}`:s.labelBusiness.company?'<p>You run your own label. Your artist career remains independent.</p>':`<h3>Incoming offers</h3>${s.labelBusiness.offers.filter(o=>!o.used&&o.expires>=s.week).map(o=>`<div class="project-row"><div><strong>${esc(labelDeals[o.label].name)}</strong><small>${o.source} · Expires after Week ${o.expires}</small></div><button class="primary" onclick="reviewArtistOffer('${o.id}')">Review & negotiate</button></div>`).join('')||'<p>No offers yet. Build your audience or send a demo below.</p>'}<h3>Pitch a label</h3>${labelDeals.map((d,i)=>`<div class="project-row"><div><strong>${d.name}</strong><small>Demo target ${i?75:45}/100 · Writing quality, charisma and marketability</small></div><button class="secondary" ${!s.songs.some(x=>x.released)||s.week-(s.labelBusiness.auditions[i]??-100)<4?'disabled':''} onclick="demoForm(${i})">Submit demo</button></div>`).join('')}`}</section>${companyPage()}</div>`}
function scoutLabels(){migrateLabelBusiness();const b=s.labelBusiness;if(s.expansion.contract||b.company||s.week-b.lastScouted<4)return;b.lastScouted=s.week;for(let i=0;i<labelDeals.length;i++){const d=labelDeals[i];if(s.fans>=d.fans&&s.reputation>=d.rep&&!b.offers.some(o=>o.label===i&&!o.used&&o.expires>=s.week))createLabelOffer(i,'Scouted your career')}b.offers=b.offers.filter(o=>!o.used&&o.expires>=s.week).slice(-8)}
function createLabelOffer(i,source){const b=s.labelBusiness;if(b.offers.some(o=>o.label===i&&!o.used&&o.expires>=s.week))return;b.offers.push({id:'label-'+i+'-'+s.week,label:i,source,expires:s.week+4,used:false});addBriefing('label-offer:'+i+':'+s.week,'Opportunity',labelDeals[i].name+' wants to talk','Review the advance, royalty share and contract options in Career → Business → Labels. This offer expires after Week '+(s.week+4)+'.')}
function demoForm(i){if(!labelActive()||!labelDeals[i]||s.expansion.contract||s.labelBusiness.company)return;modal(`<h2>Pitch ${labelDeals[i].name}</h2><p>Submit one released song · 1 slot · 10 energy · no cash fee. One submission per label every four weeks. Score: 70% song quality, 20% charisma, 10% marketability. Target ${i?75:45}.</p><form class="form" onsubmit="submitDemo(event,${i})"><label>Demo song<select name="song">${s.songs.filter(x=>x.released).map(x=>`<option value="${x.id}">${esc(x.title)} · Quality ${x.quality}</option>`).join('')}</select></label><button class="primary">Submit demo</button></form>`)}
function submitDemo(e,i){e.preventDefault();if(!labelActive()||!labelDeals[i]||s.expansion.contract||s.labelBusiness.company||s.week-(s.labelBusiness.auditions[i]??-100)<4)return;const song=s.songs.find(x=>x.id===Number(new FormData(e.target).get('song'))&&x.released);if(!song||!spend(10))return;s.labelBusiness.auditions[i]=s.week;const score=Math.round(song.quality*.7+level('charisma')*.2+level('marketability')*.1);if(score>=(i?75:45))createLabelOffer(i,'Demo accepted · '+score+'/100');log(labelDeals[i].name+' demo review: '+score+'/100'+(score>=(i?75:45)?' — offer received.':' — declined. Improve your next demo.'));$('modal').close();render();toast(score>=(i?75:45)?'Your demo earned an offer.':'Demo declined. You can try this label again in four weeks.')}
function artistOfferTerms(o,choice){const d=labelDeals[o.label];return {...d,type:choice==='360'?'360':'record',share:choice==='artist'?Math.max(.1,d.share-.05):choice==='360'?Math.min(.5,d.share+.1):d.share,advance:Math.round(d.advance*(choice==='artist'?.5:choice==='360'?1.6:1))}}
function reviewArtistOffer(id){const o=s.labelBusiness.offers.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(!o||!labelActive()||s.expansion.contract||s.labelBusiness.company)return;modal(`<h2>${labelDeals[o.label].name}: choose your terms</h2><p>26 weeks, no early cancellation. Advances are taxable signing income, not recoupable debt in this version. Wages and your future label-business income are excluded from all deals.</p>${['standard','artist','360'].map(k=>{const d=artistOfferTerms(o,k);return `<section class="card"><h3>${k==='artist'?'Negotiate a lower share':k==='360'?'360 offer':'Recording deal'}</h3><p>Advance ${money(d.advance)} · Label takes ${Math.round(d.share*100)}% of ${d.type==='360'?'streaming, album downloads and live income':'streaming and album downloads'} · +${Math.round(d.lift*100)}% reach.</p><button class="primary" onclick="acceptArtistOffer('${id}','${k}',false)">Review signing</button></section>`}).join('')}`)}
function acceptArtistOffer(id,choice,confirmed=false){const o=s.labelBusiness.offers.find(x=>x.id===id&&!x.used&&x.expires>=s.week);if(!labelActive()||!o||!['standard','artist','360'].includes(choice)||s.expansion.contract||s.labelBusiness.company)return;const d=artistOfferTerms(o,choice);if(!confirmed){modal(`<h2>Sign this ${d.type==='360'?'360':'recording'} deal?</h2><p>${esc(d.name)} pays ${money(d.advance)} now and receives ${Math.round(d.share*100)}% of ${d.type==='360'?'streaming, album downloads and live income':'streaming and album downloads'} through Week ${s.week+25}. No early cancellation.</p><button class="primary" onclick="acceptArtistOffer('${id}','${choice}',true)">Sign contract</button>`);return}o.used=true;s.expansion.contract={...d,started:s.week,ends:s.week+25};changeCash(d.advance);recordIncome('wages',d.advance);log('Signed '+d.name+' '+d.type+' deal.');$('modal').close();render()}
function companyPage(){const co=s.labelBusiness.company;if(!co)return `<section class="card"><h2>Build your own label</h2><p>Sign artists, negotiate royalty splits and hire staff. Formation costs $25,000, 1 slot and 10 energy. You must be independent. Start with three roster spaces; a manager expands capacity to six.</p><button class="primary" ${s.expansion.contract?'disabled':''} onclick="foundLabelForm()">Start a label</button></section>`;return `<section class="card"><span class="eyebrow">YOUR RECORD COMPANY</span><h2>${esc(co.name)}</h2>${profileRows([['Active artists',ownerContracts().length+' / '+labelCapacity()],['Weekly staff payroll',money(labelPayroll())],['Total label receipts',money(co.receipts)],['Last week receipts / payroll',money(co.last?.income||0)+' / '+money(co.last?.payroll||0)]])}<p>Signed artists keep releasing on their own schedules. Deals cover new recordings released during their term; earlier catalog is excluded. Automatic weekly accounting uses no slots.</p><details><summary>Staff & recurring costs</summary>${Object.entries(labelStaff).map(([k,v])=>`<div class="project-row"><div><strong>${v.name} · ${money(v.salary)}/week</strong><small>${v.detail}</small></div><button class="secondary" onclick="toggleLabelStaff('${k}')">${co.staff[k]?'Dismiss':'Hire'}</button></div>`).join('')}<p class="fine">Payroll is charged at week close. If you cannot cover the total payroll before royalties arrive, all staff pause that week without charging you. Signed roster contracts continue.</p></details></section><section class="card"><h2>Your roster</h2>${ownerContracts().map(c=>`<div class="project-row"><div><strong>${esc(s.world[c.artist].name)}</strong><small>${c.type==='360'?'360':'Recording'} · Label ${Math.round(c.share*100)}% / Artist ${Math.round((1-c.share)*100)}% · through Week ${c.ends}</small><small>Advance ${money(c.advance)} · Label receipts ${money(c.receipts)}</small></div></div>`).join('')||'<p>No artists signed yet.</p>'}<details><summary>Scout & negotiate</summary>${s.world.filter(a=>!ownerContracts().some(c=>c.artist===a.id)).map(a=>`<div class="project-row"><div><strong>${esc(a.name)}</strong><small>${esc(a.genre)} · ${compact(a.fans)} fans · Relationship ${a.relation}</small></div><button class="secondary" ${ownerContracts().length>=labelCapacity()?'disabled':''} onclick="rosterOfferForm(${a.id})">Negotiate</button></div>`).join('')}</details></section>${co.last?`<section class="card"><h2>Label statement · Week ${co.last.week}</h2>${profileRows([['Recording receipts',money(co.last.recording)],['360 live & merch receipts',money(co.last.other)],['Payroll charged',money(co.last.payroll)],['Net before tax',money(co.last.income-co.last.payroll)]])}<p class="fine">For 360 contracts, live and merchandise gross is simulated every fourth contract week from the artist’s audience. Their remaining share stays with the artist. No historical earnings are claimed.</p></section>`:''}`}
function foundLabelForm(){if(!labelActive()||s.expansion.contract||s.labelBusiness.company)return;modal(`<h2>Found your record label</h2><p>$25,000 formation expense · 1 slot · 10 energy. Staff and artist advances are additional costs. Your first roster can hold three artists.</p><form class="form" onsubmit="foundLabel(event)"><label>Label name<input name="name" maxlength="55" required placeholder="Your label name"></label><button class="primary">Pay $25,000 & create label</button></form>`)}
function foundLabel(e){e.preventDefault();if(!labelActive()||s.expansion.contract||s.labelBusiness.company)return;const name=String(new FormData(e.target).get('name')||'').trim().slice(0,55);if(!name||!spend(10,25000))return;s.labelBusiness.company={name,started:s.week,staff:{manager:false,marketing:false,ar:false},contracts:[],receipts:0,last:null,preparedWeek:0,settledWeek:0};milestone('own-label','Founded '+name);$('modal').close();render()}
function toggleLabelStaff(k,confirmed=false){const co=s.labelBusiness.company;if(!labelActive()||!co||!labelStaff[k])return;if(k==='manager'&&co.staff.manager&&ownerContracts().length>3){toast('Wait until your roster has three or fewer artists before dismissing the manager.');return}if(!confirmed){modal(`<h2>${co.staff[k]?'Dismiss':'Hire'} ${labelStaff[k].name}?</h2><p>${co.staff[k]?'Future weekly payroll decreases by ':'Recurring payroll increases by '}${money(labelStaff[k].salary)}. Effective at the next week close. No slot or immediate fee.</p><button class="primary" onclick="toggleLabelStaff('${k}',true)">Confirm</button>`);return}co.staff[k]=!co.staff[k];$('modal').close();render()}
function rosterTerms(a,type,share,weeks){const co=s.labelBusiness.company;const base=Math.max(1000,Math.round(a.fans*.12+a.skill*100));return {minimum:Math.round(base*(1+(share-.1)*3+(type==='360'?.8:0)+(weeks===52?.3:0))*(1-Math.max(-50,a.relation)*.003)*(co.staff.ar?.85:1)),reputation:Math.max(0,Math.round(a.reputation)-25)}}
function rosterOfferForm(id){const a=s.world[id];if(!labelActive()||!s.labelBusiness.company||!a||ownerContracts().some(c=>c.artist===id)||ownerContracts().length>=labelCapacity())return;modal(`<h2>Negotiate with ${esc(a.name)}</h2><p>Artist advances are non-recoupable signing fees in this version. Bigger label shares, longer terms and 360 rights increase the advance they request. Beef at −40 blocks a deal.</p><form class="form" oninput="previewRosterTerms(this,${id})" onsubmit="reviewRosterOffer(event,${id})"><label>Deal type<select name="type"><option value="record">Recording royalties</option><option value="360">360: recording, live & merch</option></select></label><label>Your label’s share<select name="share">${[10,25,40,60,80].map(n=>`<option value="${n}">${n}% label / ${100-n}% artist</option>`).join('')}</select></label><label>Term<select name="weeks"><option value="26">26 weeks</option><option value="52">52 weeks</option></select></label><label>Your signing advance<input name="advance" type="number" min="0" step="1" value="${rosterTerms(a,'record',.1,26).minimum}" required></label><p id="roster-preview">Requested advance ${money(rosterTerms(a,'record',.1,26).minimum)} · Reputation ${s.reputation}/${rosterTerms(a,'record',.1,26).reputation}</p><button class="primary">Present offer</button></form>`)}
function readRosterTerms(form){const f=new FormData(form),type=f.get('type'),share=Number(f.get('share'))/100,weeks=Number(f.get('weeks')),advance=Number(f.get('advance'));if(!['record','360'].includes(type)||![.1,.25,.4,.6,.8].includes(share)||![26,52].includes(weeks)||!Number.isSafeInteger(advance)||advance<0)throw Error('Choose valid deal terms.');return {type,share,weeks,advance}}
function previewRosterTerms(form,id){try{const t=readRosterTerms(form),r=rosterTerms(s.world[id],t.type,t.share,t.weeks);$('roster-preview').textContent='Requested advance '+money(r.minimum)+' · Reputation '+s.reputation+'/'+r.reputation+' · '+(t.advance>=r.minimum?'Advance meets their request.':'Raise the advance or reduce your share/term.')}catch{}}
let pendingRosterOffer=null;
function reviewRosterOffer(e,id){e.preventDefault();if(!labelActive()||!s.labelBusiness.company||!s.world[id])return;try{const t=readRosterTerms(e.target),r=rosterTerms(s.world[id],t.type,t.share,t.weeks);if(s.world[id].relation<=-40||s.reputation<r.reputation){toast('Repair the relationship or build more reputation before signing this artist.');return}if(t.advance<r.minimum){$('roster-preview').textContent='Counteroffer: '+money(r.minimum)+' advance for these terms. You can adjust the split, term or advance.';return}pendingRosterOffer={...t,artist:id};modal(`<h2>Sign ${esc(s.world[id].name)}?</h2><p>Pay ${money(t.advance)} now · 1 slot · 10 energy. Your label receives ${Math.round(t.share*100)}%; the artist keeps ${Math.round((1-t.share)*100)}%. ${t.type==='360'?'Includes new recording royalties plus simulated live and merchandise revenue.':'Includes new recording royalties only.'} Ends after Week ${s.week+t.weeks-1}. No early cancellation or automatic renewal.</p><button class="primary" onclick="confirmRosterOffer()">Pay advance & sign artist</button>`)}catch(err){toast(err.message)}}
function confirmRosterOffer(){const t=pendingRosterOffer,co=s.labelBusiness.company;if(!labelActive()||!co||!t||ownerContracts().length>=labelCapacity()||ownerContracts().some(c=>c.artist===t.artist))return;const a=s.world[t.artist],r=rosterTerms(a,t.type,t.share,t.weeks);if(a.relation<=-40||s.reputation<r.reputation||t.advance<r.minimum)return;if(!spend(10,t.advance))return;co.contracts.push({...t,started:s.week,ends:s.week+t.weeks-1,receipts:0,excludedIds:a.catalog.map(x=>x.uid)});a.relation=clamp(a.relation+5,-100,100);pendingRosterOffer=null;log('Signed '+a.name+' to '+co.name+'.');$('modal').close();render()}
function prepareLabelWeek(){migrateLabelBusiness();const co=s.labelBusiness.company;if(!co||co.preparedWeek===s.week)return;co.preparedWeek=s.week;const wages=labelPayroll();co.staffFunded=s.cash>=wages;co.payrollThisWeek=co.staffFunded?wages:0;if(co.payrollThisWeek){changeCash(-wages);s.finance.week.expenses=cents(s.finance.week.expenses+wages);s.finance.week.labelPayroll=wages}if(!co.staffFunded)log('Label staff paused: insufficient cash for payroll. No payroll charged.')}
function settleLabelWeek(){const co=s.labelBusiness.company;if(!co||co.settledWeek===s.week)return;co.settledWeek=s.week;let recording=0,other=0;for(const c of ownerContracts()){const a=s.world[c.artist];let streams=0;for(const x of a.catalog){if(x.week<c.started||c.excludedIds.includes(x.uid))continue;if(x.week===s.week&&co.staff.marketing&&co.staffFunded){const bonus=Math.round(x.streams*.15);x.streams+=bonus;x.total+=bonus;a.weekly+=bonus;const feed=s.feed.find(f=>f.week===s.week&&f.name===a.name&&f.title===x.title);if(feed)feed.streams=x.streams}streams+=x.streams}const music=cents(streams*.5*c.share),live=c.type==='360'&&(s.week-c.started+1)%4===0?cents(a.fans*.02*(.5+a.skill/100)*c.share):0;recording+=music;other+=live;c.receipts=cents(c.receipts+music+live);if(c.type==='360'&&c.share>=.6)a.relation=clamp(a.relation-1,-100,100)}const income=cents(recording+other);co.receipts=cents(co.receipts+income);co.last={week:s.week,recording:cents(recording),other:cents(other),income,payroll:co.payrollThisWeek||0};changeCash(income);s.finance.week.labelBusiness=cents((s.finance.week.labelBusiness||0)+income);for(const c of co.contracts)if(c.ends===s.week)log(s.world[c.artist].name+' completed their label contract. No further royalties will be collected.');co.contracts=co.contracts.filter(c=>c.ends>=s.week-52)}
function artistLabelCut(royalties){const c=s.expansion.contract,w=s.finance.week;if(!c)return 0;return cents((royalties+(['record','360'].includes(c.type)?w.albumSales||0:0)+(c.type==='360'?w.live:0))*c.share)}
let featurePickerGenre='All';
function featurePicker(){if(!labelActive()||!s.draft||s.draft.feature)return;modal(`<span class="eyebrow">FEATURE FOR ${esc(s.draft.title)}</span><h2>Choose your guest</h2><p>Compare prices and eligibility here. Booking uses no extra slot; relationship-building and negotiations each use one.</p><label>Genre<select onchange="featurePickerGenre=this.value;featurePicker()">${['All',...genres].map(g=>`<option ${g===featurePickerGenre?'selected':''}>${g}</option>`).join('')}</select></label>${s.world.filter(a=>featurePickerGenre==='All'||a.genre===featurePickerGenre).sort((a,b)=>Number(accessible(b))-Number(accessible(a))||quote(a)-quote(b)).map(a=>`<div class="project-row"><div><strong>${esc(a.name)}</strong><small>${esc(a.genre)} · ${tierNames[tier(a.fans)]} · ${money(quote(a))}</small><small>${accessible(a)?'Open to collaborate':'Requirements not met'} · Relationship ${a.relation}</small></div><button class="secondary" onclick="studioGuest(${a.id})">View offer</button></div>`).join('')}`)}
function studioGuest(id){const a=s.world[id];if(!labelActive()||!a||!s.draft)return;modal(`<button class="secondary" onclick="featurePicker()">‹ All guests</button><h2>${esc(a.name)}</h2><p>${esc(a.genre)} · ${tierNames[tier(a.fans)]} · ${money(quote(a))}</p>${featureRequirements(a)}<p>${a.relation<=-40?'They refuse while you are beefing. Apologize to repair the relationship.':'Friendship and negotiation can lower the price.'}</p><div class="controls"><button class="secondary" ${a.lastTalk===s.week?'disabled':''} onclick="social(${id},'${a.relation<0?'apologize':'talk'}');studioGuest(${id})">${a.relation<0?'Apologize':'Talk'} · 1 slot · 5 energy</button><button class="secondary" ${!accessible(a)||a.lastNegotiate===s.week?'disabled':''} onclick="negotiate(${id});studioGuest(${id})">Negotiate · 1 slot · 5 energy</button><button class="primary" ${!accessible(a)||s.draft.feature||s.cash<quote(a)?'disabled':''} onclick="studioBookFeature(${id})">Review feature</button></div>`)}
function studioBookFeature(id){const a=s.world[id];if(!labelActive()||!a||!s.draft||s.draft.feature||!accessible(a))return;modal(`<h2>Add ${esc(a.name)}?</h2><p>Song: ${esc(s.draft.title)}. Pay ${money(quote(a))} now. No extra time slot. The fee is non-refundable; a feature does not guarantee a hit.</p><button class="secondary" onclick="studioGuest(${id})">Back</button><button class="primary" onclick="bookFeature(${id},true)">Confirm feature</button>`)}
function validateLabelBusiness(){const b=s.labelBusiness,validNum=(n,min,max)=>Number.isFinite(n)&&n>=min&&n<=max;if(!b||!Array.isArray(b.offers)||!b.auditions||!validNum(b.lastScouted,0,s.week))throw Error('Invalid label records.');for(const o of b.offers)if(!labelDeals[o.label]||typeof o.id!=='string'||typeof o.source!=='string'||!validNum(o.expires,1,s.week+4)||typeof o.used!=='boolean')throw Error('Invalid label offer.');for(const [k,v] of Object.entries(b.auditions))if(!labelDeals[k]||!validNum(v,1,s.week))throw Error('Invalid demo history.');const co=b.company;if(!co)return;if(s.expansion.contract||typeof co.name!=='string'||co.name.length>55||!co.staff||!Array.isArray(co.contracts)||!validNum(co.receipts,0,1e100)||!validNum(co.started,1,s.week))throw Error('Invalid record company.');for(const k of Object.keys(labelStaff))if(typeof co.staff[k]!=='boolean')throw Error('Invalid label staff.');const active=new Set();for(const c of co.contracts){if(!s.world[c.artist]||!['record','360'].includes(c.type)||![.1,.25,.4,.6,.8].includes(c.share)||![26,52].includes(c.weeks)||!validNum(c.started,1,s.week)||c.ends!==c.started+c.weeks-1||!validNum(c.advance,0,Number.MAX_SAFE_INTEGER)||!validNum(c.receipts,0,1e100)||!Array.isArray(c.excludedIds)||!c.excludedIds.every(Number.isFinite))throw Error('Invalid roster contract.');if(c.ends>=s.week){if(active.has(c.artist))throw Error('Duplicate roster artist.');active.add(c.artist)}}if(active.size>labelCapacity())throw Error('Roster exceeds capacity.');}

boot();
